 5: use App\Models\Customer;
 6: use App\Models\ProductVariant;
 7: use App\Services\WholesaleService;
 8: use Illuminate\Support\Collection;
 9: use Maatwebsite\Excel\Concerns\FromCollection;
10: use Maatwebsite\Excel\Concerns\ShouldAutoSize;
11: use Maatwebsite\Excel\Concerns\WithCustomValueBinder;
12: use Maatwebsite\Excel\Concerns\WithHeadings;
13: use Maatwebsite\Excel\Concerns\WithStyles;
14: use PhpOffice\PhpSpreadsheet\Cell\Cell;
15: use PhpOffice\PhpSpreadsheet\Cell\DataType;
16: use PhpOffice\PhpSpreadsheet\Cell\DefaultValueBinder;
17: use PhpOffice\PhpSpreadsheet\Worksheet\Worksheet;
18: 
19: class WholesalePriceListExport extends DefaultValueBinder implements FromCollection, ShouldAutoSize, WithCustomValueBinder, WithHeadings, WithStyles
20: {
21:     public function __construct(private readonly Customer $customer) {}
22: 
23:     public function headings(): array
24:     {
25:         return ['SKU', 'Barcode', 'Product Name', 'Base Price', 'Your Wholesale Price', 'Quantity Tiers'];
26:     }
27: 
28:     public function bindValue(Cell $cell, mixed $value): bool
29:     {
30:         if (in_array($cell->getColumn(), ['A', 'B', 'C', 'F'], true)) {
31:             $cell->setValueExplicit((string) $value, DataType::TYPE_STRING);
32: 
33:             return true;
34:         }
35: 
36:         return parent::bindValue($cell, $value);
37:     }
38: 
39:     public function collection(): Collection
40:     {
41:         return ProductVariant::query()->with('product')->where('is_active', true)
42:             ->whereHas('product', fn ($q) => $q->where('is_active', true)->where('status', 'published')->whereIn('sales_channel', ['wholesale', 'both']))
43:             ->orderBy('id')->get()->map(function ($variant): array {
44:                 $row = app(WholesaleService::class)->product($variant, $this->customer);
45: 
46:                 return [$row['sku'], $row['barcode'], $row['product_name'], $row['base_price'], $row['unit_price'],
47:                     $row['tier_prices']->map(fn ($tier) => $tier['min_qty'].'+: '.$tier['unit_price'])->implode(' | ')];
48:             });
49:     }
50: 
51:     public function styles(Worksheet $sheet): array
52:     {
53:         $sheet->freezePane('A2');
54:         $sheet->setAutoFilter($sheet->calculateWorksheetDimension());
55: 
56:         return [1 => ['font' => ['bold' => true], 'fill' => ['fillType' => 'solid', 'startColor' => ['rgb' => 'DDEBF7']]]];
57:     }
