11: class ReportController extends Controller
12: {
13:     public function __construct(private readonly ReportService $reports) {}
14: 
15:     public function sales(Request $request)
16:     {
17:         return response()->json(['data' => $this->reports->sales($this->filters($request))]);
18:     }
19: 
20:     public function inventory(Request $request)
21:     {
22:         return response()->json(['data' => $this->reports->inventory($this->filters($request))]);
23:     }
24: 
25:     public function profit(Request $request)
26:     {
27:         return response()->json(['data' => $this->reports->profit($this->filters($request))]);
28:     }
29: 
30:     public function suppliers(Request $request)
31:     {
32:         app(BranchAccess::class)->assertCentralAccess($request->user());
33: 
34:         return response()->json(['data' => $this->reports->suppliers($this->filters($request))]);
35:     }
36: 
37:     public function shifts(Request $request)
38:     {
39:         return response()->json(['data' => $this->reports->shifts($this->filters($request))]);
40:     }
41: 
42:     public function dashboard(Request $request)
43:     {
44:         return response()->json(['data' => $this->reports->dashboard($this->filters($request))]);
45:     }
46: 
47:     private function filters(Request $request): array
48:     {
49:         $filters = $request->validate([
50:             'from_date' => 'nullable|date_format:Y-m-d', 'to_date' => ['nullable', 'date_format:Y-m-d', Rule::when($request->filled('from_date'), 'after_or_equal:from_date')],
51:             'branch_id' => 'nullable|integer|min:1', 'cashier_id' => 'nullable|integer|min:1',
52:             'channel' => 'nullable|in:store,wholesale,pos,admin', 'payment_method' => 'nullable|in:cash,card,mixed,cod,wallet,credit,bank_transfer',
53:             'group_by' => 'nullable|in:day,month,branch,channel,cashier,payment_method', 'dead_days' => 'nullable|integer|min:1|max:3650',
54:             'differences_only' => 'nullable|boolean', 'per_page' => 'nullable|integer|min:1|max:100',
55:         ]);
56:         $branch = app(BranchAccess::class)->restrictedBranch($request->user());
57:         if ($branch !== null) {
58:             abort_if(isset($filters['branch_id']) && (int) $filters['branch_id'] !== $branch, 403);
59:             $filters['branch_id'] = $branch;
60:         }
61: 
62:         return $filters;
63:     }
