 5: use App\Http\Controllers\Controller;
 6: use App\Models\Order;
 7: use App\Models\WholesalePaymentNotice;
 8: use App\Services\PrivateAttachments;
 9: use Barryvdh\DomPDF\Facade\Pdf;
10: use Illuminate\Http\Request;
11: use Illuminate\Support\Facades\DB;
12: use Illuminate\Support\Str;
13: 
14: class InvoiceController extends Controller
15: {
16:     public function index(Request $request)
17:     {
18:         return response()->json(Order::where('customer_id', $request->user()->id)->where('channel', 'wholesale')->latest()->paginate(20));
19:     }
20: 
21:     public function download(Request $request, Order $order)
22:     {
23:         abort_unless((int) $order->customer_id === (int) $request->user()->id && $order->channel === 'wholesale', 404);
24: 
25:         return Pdf::loadView('pdfs.wholesale_invoice', ['order' => $order->load('items'), 'customer' => $request->user()])->download('invoice-'.$order->order_number.'.pdf');
26:     }
27: 
28:     public function statement(Request $request)
29:     {
30:         $entries = DB::table('customer_credit_transactions')->where('customer_id', $request->user()->id)
31:             ->select('*')->selectRaw('CASE WHEN amount > 0 THEN amount ELSE 0 END AS debit, CASE WHEN amount < 0 THEN -amount ELSE 0 END AS credit, SUM(amount) OVER (ORDER BY created_at, id ROWS UNBOUNDED PRECEDING) AS running_balance');
32: 
33:         return response()->json(DB::query()->fromSub($entries, 'statement')->orderBy('created_at')->orderBy('id')->paginate(20));
34:     }
35: 
36:     public function storePaymentNotice(Request $request)
37:     {
38:         $data = $request->validate([
39:             'order_id' => 'nullable|integer|exists:orders,id', 'amount' => 'required|numeric|min:0.01|max:99999999',
40:             'payment_method' => 'required|in:bank_transfer,check,deposit', 'bank_name' => 'required|string|max:191',
41:             'reference_number' => 'required|string|max:191', 'transfer_date' => 'required|date_format:Y-m-d|before_or_equal:today',
42:             'receipt' => 'required|file|mimes:jpg,jpeg,png,pdf|max:5120',
43:         ]);
44:         if (! empty($data['order_id'])) {
45:             Order::where('customer_id', $request->user()->id)->where('channel', 'wholesale')->findOrFail($data['order_id']);
46:         }
47:         $notice = PrivateAttachments::transaction(function ($files) use ($request, $data) {
48:             unset($data['receipt']);
49: 
50:             return WholesalePaymentNotice::create([
51:                 ...$data, 'customer_id' => $request->user()->id, 'notice_number' => 'PN-'.Str::ulid(),
52:                 'receipt_file_path' => $files->store($request->file('receipt'), 'wholesale/receipts'),
53:             ]);
54:         });
55: 
56:         return response()->json(['data' => $notice], 201);
57:     }
58: } 1: <?php
