11: class OrderController extends Controller
12: {
13:     public function reorder(Request $request, Order $order, CartService $carts)
14:     {
15:         abort_unless((int) $order->customer_id === (int) $request->user()->id, 404);
16:         $cart = DB::transaction(function () use ($request, $order, $carts) {
17:             $cart = $carts->resolveCart($request->user(), null);
18:             foreach ($order->items as $item) {
19:                 $cart = $carts->addItem($cart, $request->user(), $item->product_variant_id, (float) $item->qty);
20:             }
21: 
22:             return $cart;
23:         });
24: 
25:         return response()->json(['data' => $carts->present($cart, $request->user())]);
26:     }
