17:     {
18:         $data = $request->validate(['per_page' => 'sometimes|integer|min:1|max:100', 'q' => 'nullable|string|max:100']);
19:         $products = ProductVariant::query()->with('product')->where('is_active', true)
20:             ->whereHas('product', fn ($q) => $q->where('is_active', true)->where('status', 'published')->whereIn('sales_channel', ['wholesale', 'both']))
21:             ->when($data['q'] ?? null, fn ($q, $term) => $q->where(fn ($q) => $q->where('sku', $term)->orWhere('barcode', $term)
22:                 ->orWhereHas('product', fn ($p) => $p->where('name_ar', 'like', '%'.$term.'%'))))
23:             ->orderBy('id')->paginate($data['per_page'] ?? 20);
24:         $products->through(fn ($variant) => $wholesale->product($variant, $request->user()));
25: 
26:         return response()->json($products);
