 3: namespace App\Http\Controllers\Api\V1\Wholesale;
 4: 
 5: use App\Exceptions\BusinessException;
 6: use App\Http\Controllers\Controller;
 7: use App\Imports\QuickOrderImport;
 8: use App\Models\ProductVariant;
 9: use App\Services\CartService;
10: use App\Services\WholesaleService;
11: use Illuminate\Http\Request;
12: use Illuminate\Support\Collection;
13: use Illuminate\Support\Facades\Validator;
14: use Maatwebsite\Excel\Facades\Excel;
15: 
16: class QuickOrderController extends Controller
17: {
18:     public function lookup(Request $request, WholesaleService $wholesale)
19:     {
20:         $data = $request->validate([
21:             'skus' => 'required_without:barcodes|array|max:1000', 'skus.*' => 'string|max:191',
22:             'barcodes' => 'required_without:skus|array|max:1000', 'barcodes.*' => 'string|max:191',
23:             'quantities' => 'sometimes|array|max:1000', 'quantities.*' => 'integer|min:1|max:100000',
24:         ]);
25:         $field = isset($data['skus']) ? 'sku' : 'barcode';
26:         $codes = $data['skus'] ?? $data['barcodes'];
27:         $variants = ProductVariant::query()->with('product')->where('is_active', true)
28:             ->whereHas('product', fn ($q) => $q->where('is_active', true)->where('status', 'published')->whereIn('sales_channel', ['wholesale', 'both']))
29:             ->whereIn($field, $codes)->get()->keyBy($field);
30:         $rows = [];
31:         foreach ($codes as $index => $code) {
32:             $rows[] = isset($variants[$code]) ? $wholesale->product($variants[$code], $request->user(), $data['quantities'][$index] ?? 1)
33:                 : ['code' => $code, 'error' => 'not_found'];
34:         }
35: 
36:         return response()->json(['data' => $rows]);
37:     }
38: 
39:     public function import(Request $request, CartService $carts)
40:     {
41:         $request->validate(['file' => 'required|file|mimes:xlsx,xls,csv|max:5120']);
42:         $import = new QuickOrderImport;
43:         Excel::import($import, $request->file('file'));
44:         abort_if($import->rows->count() > 1000, 422, 'الحد الأقصى 1000 صنف.');
45:         $cart = $carts->resolveCart($request->user(), null);
46:         $report = ['added' => [], 'unavailable' => []];
47:         foreach ($import->rows as $index => $row) {
48:             $row = $row instanceof Collection ? $row->all() : (array) $row;
49:             if (isset($row['sku']) && is_numeric($row['sku'])) {
50:                 $row['sku'] = (string) $row['sku'];
51:             }
52:             $validator = Validator::make($row, ['sku' => 'required|string|max:191', 'qty' => 'required|integer|min:1|max:100000']);
53:             if ($validator->fails()) {
54:                 $report['unavailable'][] = ['row' => $index + 2, 'errors' => $validator->errors()];
55: 
56:                 continue;
57:             }
58:             $variant = ProductVariant::where('sku', $row['sku'])->first();
59:             if (! $variant) {
60:                 $report['unavailable'][] = ['sku' => $row['sku'], 'error' => 'not_found'];
61: 
62:                 continue;
63:             }
64:             try {
65:                 $cart = $carts->addItem($cart, $request->user(), $variant->id, (float) $row['qty']);
66:                 $report['added'][] = ['sku' => $row['sku'], 'qty' => $row['qty']];
67:             } catch (BusinessException $error) {
68:                 $report['unavailable'][] = ['sku' => $row['sku'], 'error' => $error->getMessage()];
69:             }
70:         }
71: 
72:         return response()->json(['data' => $report]);
73:     }
74: } 1: <?php
