11: use App\Events\WholesaleApplicationSubmitted;
12: use App\Models\Customer;
13: use App\Models\SupplierUser;
14: use App\Models\User;
15: use App\Notifications\LowStockAlertNotification;
16: use App\Notifications\OrderConfirmationNotification;
17: use App\Notifications\PurchaseOrderSentToSupplierNotification;
18: use App\Notifications\TransferPendingApprovalNotification;
19: use App\Notifications\WholesaleApplicationReviewedNotification;
20: use App\Notifications\WholesaleApplicationSubmittedNotification;
21: use Illuminate\Contracts\Queue\ShouldQueueAfterCommit;
22: 
23: class SendBusinessNotifications implements ShouldQueueAfterCommit
24: {
25:     public function handle(BusinessEvent $event): void
26:     {
27:         $class = match (true) {
28:             $event instanceof OrderCreated => OrderConfirmationNotification::class,
29:             $event instanceof StockLowDetected => LowStockAlertNotification::class,
30:             $event instanceof TransferPendingApproval => TransferPendingApprovalNotification::class,
31:             $event instanceof WholesaleApplicationSubmitted => WholesaleApplicationSubmittedNotification::class,
32:             $event instanceof WholesaleApplicationReviewed => WholesaleApplicationReviewedNotification::class,
33:             $event instanceof PurchaseOrderSentToSupplier => PurchaseOrderSentToSupplierNotification::class,
34:         };
35:         $data = ['event' => class_basename($event), ...$event->data];
36:         if ($event instanceof PurchaseOrderSentToSupplier) {
37:             SupplierUser::where('supplier_id', $event->data['supplier_id'])->where('is_active', true)
38:                 ->eachById(fn ($user) => $user->notify(new $class($data)));
39: 
40:             return;
41:         }
42:         if ($event instanceof OrderCreated || $event instanceof WholesaleApplicationReviewed) {
43:             Customer::find($event->data['customer_id'] ?? null)?->notify(new $class($data));
44:         }
45:         if ($event instanceof WholesaleApplicationReviewed) {
46:             return;
47:         }
48:         $permissions = match (true) {
49:             $event instanceof StockLowDetected => ['inventory.view', 'purchases.view'],
50:             $event instanceof TransferPendingApproval => ['transfers.approve'],
51:             $event instanceof WholesaleApplicationSubmitted => ['customers.manage'],
52:             default => ['orders.view'],
53:         };
54:         User::query()->where('is_active', true)
55:             ->where(fn ($q) => $q->whereHas('roles', fn ($r) => $r->where('name', 'Super Admin'))
56:                 ->orWhereHas('permissions', fn ($p) => $p->whereIn('name', $permissions))
57:                 ->orWhereHas('roles.permissions', fn ($p) => $p->whereIn('name', $permissions)))
58:             ->when($event->data['branch_id'] ?? null, fn ($q, $branch) => $q->where(fn ($q) => $q->whereNull('branch_id')->orWhere('branch_id', $branch)))
59:             ->eachById(fn ($user) => $user->notify(new $class($data)));
60:     }
61: } 1: <?php
