  5: namespace App\Services;
  6: 
  7: use App\Models\Order;
  8: use App\Models\ReturnRequest;
  9: use Carbon\Carbon;
 10: use Illuminate\Database\Query\Builder;
 11: use Illuminate\Support\Facades\DB;
 12: 
 13: class ReportService
 14: {
 15:     private function period(Builder $query, array $filters, string $column): Builder
 16:     {
 17:         return $query->where($column, '>=', Carbon::parse($filters['from_date'] ?? now()->startOfMonth())->startOfDay())
 18:             ->where($column, '<', Carbon::parse($filters['to_date'] ?? now())->addDay()->startOfDay());
 19:     }
 20: 
 21:     private function facts(array $filters): Builder
 22:     {
 23:         $sign = 'CASE WHEN orders.original_pos_order_id IS NOT NULL THEN -1 ELSE 1 END';
 24:         $sales = DB::table('orders')->leftJoin('pos_shifts', 'pos_shifts.id', '=', 'orders.pos_shift_id')
 25:             ->whereNull('orders.deleted_at')->whereIn('orders.status', ['shipped', 'delivered', 'returned'])
 26:             ->selectRaw("orders.created_at AS sale_date, orders.allocated_branch_id AS branch_id, orders.channel,
 27:                 pos_shifts.user_id AS cashier_id, orders.payment_method,
 28:                 CASE WHEN orders.original_pos_order_id IS NULL THEN 1 ELSE 0 END AS order_count,
 29:                 $sign * orders.subtotal AS gross_sales, $sign * orders.discount_amount AS discounts,
 30:                 $sign * orders.tax_amount AS taxes, $sign * (orders.subtotal - orders.discount_amount) AS net_sales");
 31:         // RMA refunds include the item's tax share, but exclude delivery fees.
 32:         $netRefund = 'ROUND(r.total_refund_amount * (o.subtotal - o.discount_amount) / NULLIF(o.subtotal - o.discount_amount + o.tax_amount, 0), 2)';
 33:         $refunds = DB::table('return_requests AS r')->join('orders AS o', 'o.id', '=', 'r.order_id')
 34:             ->leftJoin('pos_shifts AS s', 's.id', '=', 'o.pos_shift_id')->where('r.status', 'refunded')
 35:             ->selectRaw("r.refunded_at AS sale_date, r.branch_id, o.channel, s.user_id AS cashier_id, o.payment_method,
 36:                 0 AS order_count, -COALESCE($netRefund, 0) AS gross_sales, 0 AS discounts,
 37:                 -(r.total_refund_amount - COALESCE($netRefund, 0)) AS taxes, -COALESCE($netRefund, 0) AS net_sales");
 38:         $directReturns = DB::table('orders')->leftJoin('pos_shifts', 'pos_shifts.id', '=', 'orders.pos_shift_id')
 39:             ->whereNull('orders.deleted_at')->whereNull('orders.original_pos_order_id')->where('orders.status', 'returned')
 40:             ->whereNotExists(fn ($q) => $q->selectRaw('1')->from('return_requests')->whereColumn('return_requests.order_id', 'orders.id')->where('return_requests.status', 'refunded'))
 41:             ->selectRaw('orders.updated_at AS sale_date, orders.allocated_branch_id AS branch_id, orders.channel,
 42:                 pos_shifts.user_id AS cashier_id, orders.payment_method, 0 AS order_count,
 43:                 -orders.subtotal AS gross_sales, -orders.discount_amount AS discounts, -orders.tax_amount AS taxes,
 44:                 -(orders.subtotal - orders.discount_amount) AS net_sales');
 45:         $facts = DB::query()->fromSub($sales->unionAll($refunds)->unionAll($directReturns), 'facts');
 46: 
 47:         return $this->period($facts, $filters, 'sale_date')
 48:             ->when($filters['branch_id'] ?? null, fn ($q, $id) => $q->where('branch_id', $id))
 49:             ->when($filters['channel'] ?? null, fn ($q, $value) => $q->where('channel', $value))
 50:             ->when($filters['cashier_id'] ?? null, fn ($q, $id) => $q->where('cashier_id', $id))
 51:             ->when($filters['payment_method'] ?? null, fn ($q, $value) => $q->where('payment_method', $value));
 52:     }
 53: 
 54:     private function orders(array $filters): Builder
 55:     {
 56:         return $this->period(DB::table('orders')->leftJoin('pos_shifts', 'pos_shifts.id', '=', 'orders.pos_shift_id')
 57:             ->whereNull('orders.deleted_at')->whereIn('orders.status', ['shipped', 'delivered', 'returned']), $filters, 'orders.created_at')
 58:             ->when($filters['branch_id'] ?? null, fn ($q, $id) => $q->where('orders.allocated_branch_id', $id));
 59:     }
 60: 
 61:     public function sales(array $filters): array
 62:     {
 63:         $group = match ($filters['group_by'] ?? 'day') {
 64:             'month' => "TO_CHAR(sale_date, 'YYYY-MM')", 'branch' => 'branch_id', 'channel' => 'channel',
 65:             'cashier' => 'cashier_id', 'payment_method' => 'payment_method', default => 'DATE(sale_date)',
 66:         };
 67:         $query = $this->facts($filters)->selectRaw("$group AS period, SUM(order_count) AS order_count,
 68:             SUM(gross_sales) AS gross_sales, SUM(discounts) AS discounts, SUM(taxes) AS taxes, SUM(net_sales) AS net_sales")
 69:             ->groupByRaw($group);
 70:         $totals = DB::query()->fromSub(clone $query, 'sales')->selectRaw('COALESCE(SUM(order_count),0) AS order_count,
 71:             COALESCE(SUM(gross_sales),0) AS gross_sales, COALESCE(SUM(discounts),0) AS discounts,
 72:             COALESCE(SUM(taxes),0) AS taxes, COALESCE(SUM(net_sales),0) AS net_sales')->first();
 73: 
 74:         return ['totals' => $totals, 'net_sales_after_returns' => (float) $totals->net_sales,
 75:             'rows' => $query->orderByRaw($group)->paginate($filters['per_page'] ?? 50)];
 76:     }
 77: 
 78:     public function inventory(array $filters): array
 79:     {
 80:         $stock = DB::table('stock_levels')->join('product_variants', 'product_variants.id', '=', 'stock_levels.product_variant_id')
 81:             ->when($filters['branch_id'] ?? null, fn ($q, $id) => $q->where('stock_levels.branch_id', $id));
 82:         $values = (clone $stock)->selectRaw('stock_levels.branch_id, SUM(stock_levels.on_hand * COALESCE(product_variants.cost_price, 0)) AS inventory_value,
 83:             SUM(stock_levels.on_hand) AS quantity, SUM(CASE WHEN product_variants.cost_price IS NULL AND stock_levels.on_hand > 0 THEN 1 ELSE 0 END) AS missing_cost_count')
 84:             ->groupBy('stock_levels.branch_id')->get();
 85:         $cutoff = now()->subDays($filters['dead_days'] ?? 90);
 86:         $dead = (clone $stock)->where('stock_levels.on_hand', '>', 0)
 87:             ->where('product_variants.created_at', '<', $cutoff)
 88:             ->whereNotExists(fn ($q) => $q->selectRaw('1')->from('stock_movements')
 89:                 ->whereColumn('stock_movements.product_variant_id', 'stock_levels.product_variant_id')
 90:                 ->whereColumn('stock_movements.branch_id', 'stock_levels.branch_id')->where('stock_movements.created_at', '>=', $cutoff))
 91:             ->select('stock_levels.*', 'product_variants.sku')->orderBy('stock_levels.id')->paginate($filters['per_page'] ?? 50);
 92: 
 93:         return ['valuation' => $values, 'dead_stock' => $dead];
 94:     }
 95: 
 96:     public function profit(array $filters): array
 97:     {
 98:         $sales = $this->sales($filters);
 99:         $movements = DB::table('stock_movements AS m')
100:             ->leftJoin('return_requests AS r', fn ($join) => $join->on('r.id', '=', 'm.reference_id')->whereIn('m.reference_type', ['return_request', ReturnRequest::class]))
101:             ->leftJoin('orders AS o', fn ($join) => $join->whereRaw('o.id = CASE WHEN m.reference_type IN (?, ?) THEN m.reference_id ELSE r.order_id END', ['order', Order::class]))
102:             ->leftJoin('pos_shifts AS s', 's.id', '=', 'o.pos_shift_id')->whereIn('m.type', ['sale', 'sale_return']);
103:         $cost = $this->period($movements, $filters, 'm.created_at')
104:             ->when($filters['branch_id'] ?? null, fn ($q, $id) => $q->where('m.branch_id', $id))
105:             ->when($filters['channel'] ?? null, fn ($q, $channel) => $q->where('o.channel', $channel))
106:             ->when($filters['cashier_id'] ?? null, fn ($q, $id) => $q->where('s.user_id', $id))
107:             ->when($filters['payment_method'] ?? null, fn ($q, $method) => $q->where('o.payment_method', $method))
108:             ->selectRaw('COALESCE(SUM(-m.quantity * m.unit_cost), 0) AS cogs, SUM(CASE WHEN m.unit_cost IS NULL THEN 1 ELSE 0 END) AS missing_cost_count')->first();
109:         $expenses = (float) $this->period(DB::table('expenses'), $filters, 'expense_date')
110:             ->when($filters['branch_id'] ?? null, fn ($q, $id) => $q->where('branch_id', $id))->sum('amount');
111:         $net = $sales['net_sales_after_returns'];
112:         $gross = round($net - (float) $cost->cogs, 2);
113: 
114:         return ['net_sales_revenue' => $net, 'cogs' => $cost->cogs, 'missing_cost_count' => (int) $cost->missing_cost_count,
115:             'gross_profit' => $gross, 'total_expenses' => $expenses, 'net_profit' => round($gross - $expenses, 2)];
116:     }
117: 
118:     public function suppliers(array $filters): array
119:     {
120:         $asOf = Carbon::parse($filters['to_date'] ?? now())->toDateString();
121:         $payments = DB::table('supplier_payments')->where('payment_date', '<=', $asOf)->where(fn ($q) => $q->whereNull('voided_at')->orWhere('voided_at', '>', Carbon::parse($asOf)->endOfDay()))
122:             ->selectRaw('supplier_invoice_id, SUM(amount) AS paid')->groupBy('supplier_invoice_id');
123:         $invoices = DB::table('supplier_invoices AS i')->leftJoinSub($payments, 'p', 'p.supplier_invoice_id', '=', 'i.id')
124:             ->whereIn('i.status', ['posted', 'partially_paid', 'paid'])->where('i.issue_date', '<=', $asOf)
125:             ->selectRaw('i.supplier_id, i.due_date, i.total_amount, i.total_amount - COALESCE(p.paid,0) AS due');
126:         $aging = DB::query()->fromSub($invoices, 'i')->selectRaw('supplier_id, SUM(total_amount) AS total_purchases, SUM(due) AS invoice_balance,
127:                 SUM(CASE WHEN due_date >= ?::date THEN due ELSE 0 END) AS current_due,
128:                 SUM(CASE WHEN ?::date - due_date BETWEEN 1 AND 30 THEN due ELSE 0 END) AS overdue_1_30,
129:                 SUM(CASE WHEN ?::date - due_date BETWEEN 31 AND 60 THEN due ELSE 0 END) AS overdue_31_60,
130:                 SUM(CASE WHEN ?::date - due_date BETWEEN 61 AND 90 THEN due ELSE 0 END) AS overdue_61_90,
131:                 SUM(CASE WHEN ?::date - due_date > 90 THEN due ELSE 0 END) AS overdue_over_90', array_fill(0, 5, $asOf))->groupBy('supplier_id');
132:         $allPaid = DB::table('supplier_payments')->where('payment_date', '<=', $asOf)->where(fn ($q) => $q->whereNull('voided_at')->orWhere('voided_at', '>', Carbon::parse($asOf)->endOfDay()))->selectRaw('supplier_id, SUM(amount) AS total_paid')->groupBy('supplier_id');
133:         $rows = DB::table('suppliers AS s')->leftJoinSub($aging, 'a', 'a.supplier_id', '=', 's.id')
134:             ->leftJoinSub($allPaid, 'paid', 'paid.supplier_id', '=', 's.id')
135:             ->selectRaw('s.id AS supplier_id, s.name, s.opening_balance, COALESCE(a.total_purchases,0) AS total_purchases,
136:                 s.opening_balance + COALESCE(a.total_purchases,0) - COALESCE(paid.total_paid,0) AS balance,
137:                 COALESCE(a.invoice_balance,0) AS invoice_balance, COALESCE(a.current_due,0) AS current_balance,
138:                 COALESCE(a.overdue_1_30,0) AS overdue_1_30, COALESCE(a.overdue_31_60,0) AS overdue_31_60,
139:                 COALESCE(a.overdue_61_90,0) AS overdue_61_90, COALESCE(a.overdue_over_90,0) AS overdue_over_90')
140:             ->orderBy('s.id')->paginate($filters['per_page'] ?? 50);
141: 
142:         return ['as_of' => $asOf, 'rows' => $rows];
143:     }
144: 
145:     public function shifts(array $filters): array
146:     {
147:         $query = $this->period(DB::table('pos_shifts'), $filters, 'opened_at')
148:             ->when($filters['branch_id'] ?? null, fn ($q, $id) => $q->where('branch_id', $id))
149:             ->when($filters['cashier_id'] ?? null, fn ($q, $id) => $q->where('user_id', $id))
150:             ->when($filters['differences_only'] ?? false, fn ($q) => $q->where('cash_difference', '<>', 0));
151: 
152:         return ['totals' => (clone $query)->selectRaw('COALESCE(SUM(cash_sales_total),0) AS cash_sales, COALESCE(SUM(card_sales_total),0) AS card_sales,
153:             COALESCE(SUM(cash_difference),0) AS cash_difference, COUNT(*) AS shift_count')->first(),
154:             'rows' => $query->orderByDesc('opened_at')->paginate($filters['per_page'] ?? 50)];
155:     }
156: 
157:     public function dashboard(array $filters): array
158:     {
159:         $branch = $filters['branch_id'] ?? null;
160:         $kpis = [];
161:         foreach (['today' => now()->toDateString(), 'month' => now()->startOfMonth()->toDateString()] as $period => $from) {
162:             $range = [...$filters, 'from_date' => $from, 'to_date' => now()->toDateString(), 'group_by' => 'channel'];
163:             $kpis[$period] = [
164:                 'sales_by_channel' => $this->sales($range)['rows']->items(),
165:                 'new_orders' => $this->period(DB::table('orders')->whereNull('deleted_at'), $range, 'created_at')
166:                     ->when($branch, fn ($q) => $q->where('allocated_branch_id', $branch))->count(),
167:             ];
168:         }
169:         $topItems = $this->orders($filters)->join('order_items', 'order_items.order_id', '=', 'orders.id')
170:             ->join('product_variants', 'product_variants.id', '=', 'order_items.product_variant_id')
171:             ->selectRaw('product_variants.product_id, SUM(CASE WHEN orders.original_pos_order_id IS NULL THEN order_items.line_total ELSE -order_items.line_total END) AS sales,
172:                 SUM(CASE WHEN orders.original_pos_order_id IS NULL THEN order_items.qty ELSE -order_items.qty END) AS quantity')
173:             ->groupBy('product_variants.product_id')->orderByDesc('sales')->limit(5)->get();
174:         $topBranches = $this->facts($filters)->whereNotNull('branch_id')->selectRaw('branch_id, SUM(net_sales) AS sales')
175:             ->groupBy('branch_id')->orderByDesc('sales')->limit(5)->get();
176: 
177:         return [...$kpis,
178:             'low_stock_count' => DB::table('stock_levels')->join('product_variants', 'product_variants.id', '=', 'stock_levels.product_variant_id')
179:                 ->when($branch, fn ($q) => $q->where('stock_levels.branch_id', $branch))
180:                 ->whereRaw('stock_levels.available <= COALESCE(NULLIF(stock_levels.reorder_level,0),product_variants.reorder_level,0)')->distinct()->count('stock_levels.product_variant_id'),
181:             'pending_wholesale_count' => DB::table('customers')->whereNull('deleted_at')->whereIn('type', ['wholesale', 'distributor'])->where('status', 'pending')->count(),
182:             'top_products' => $topItems, 'top_branches' => $topBranches];
183:     }
