 23: class WholesaleService
 24: {
 25:     public function __construct(private readonly PricingService $pricing) {}
 26: 
 27:     public function usedCredit(Customer $customer): float
 28:     {
 29:         return (float) DB::table('customer_credit_transactions')->where('customer_id', $customer->id)->sum('amount');
 30:     }
 31: 
 32:     public function recordCreditPurchase(Order $order): void
 33:     {
 34:         $customer = Customer::query()->lockForUpdate()->findOrFail($order->customer_id);
 35:         if ($customer->status !== CustomerStatus::Approved || $customer->type === CustomerType::Retail) {
 36:             throw new BusinessException('الشراء الآجل متاح لحسابات الجملة المعتمدة فقط.');
 37:         }
 38:         if ($this->usedCredit($customer) + (float) $order->grand_total > (float) $customer->credit_limit) {
 39:             throw new BusinessException('الحد الائتماني غير كافٍ.');
 40:         }
 41:         DB::table('customer_credit_transactions')->insert([
 42:             'customer_id' => $customer->id, 'order_id' => $order->id, 'type' => 'purchase', 'amount' => $order->grand_total,
 43:             'created_at' => now(), 'updated_at' => now(),
 44:         ]);
 45:     }
 46: 
 47:     public function reverseCredit(Order $order, ?ReturnRequest $return = null): void
 48:     {
 49:         Customer::query()->lockForUpdate()->findOrFail($order->customer_id);
 50:         $remaining = (float) DB::table('customer_credit_transactions')->where('order_id', $order->id)->where('type', '!=', 'payment')->sum('amount');
 51:         $amount = $return ? (float) $return->total_refund_amount : $remaining;
 52:         if ($amount <= 0) {
 53:             return;
 54:         }
 55:         DB::table('customer_credit_transactions')->insert([
 56:             'customer_id' => $order->customer_id, 'order_id' => $order->id, 'return_request_id' => $return?->id,
 57:             'type' => $return ? 'return' : 'cancellation', 'amount' => -$amount, 'created_at' => now(), 'updated_at' => now(),
 58:         ]);
 59:     }
