 61:     public function product(ProductVariant $variant, Customer $customer, int $qty = 1): array
 62:     {
 63:         $tiers = collect($this->pricing->tiers($variant, $customer));
 64: 
 65:         return [
 66:             'id' => $variant->id, 'sku' => $variant->sku, 'barcode' => $variant->barcode,
 67:             'product_name' => $variant->product?->name_ar, 'base_price' => $variant->base_price,
 68:             'unit_price' => $this->pricing->resolve($variant, $customer, $qty)['unit_price'],
 69:             'tier_prices' => $tiers, 'qty' => $qty,
 70:             'available' => (app(StoreCatalogService::class)->availabilityMap([$variant->id])[$variant->id] ?? 0),
 71:         ];
 72:     }
