 74:     public function saveQuotation(Customer $customer, array $data, ?Quotation $quotation = null): Quotation
 75:     {
 76:         return DB::transaction(function () use ($customer, $data, $quotation): Quotation {
 77:             if ($quotation) {
 78:                 $quotation = Quotation::query()->where('customer_id', $customer->id)->lockForUpdate()->findOrFail($quotation->id);
 79:                 if (! in_array($quotation->status, ['draft', 'requested'], true)) {
 80:                     throw new BusinessException('لا يمكن تعديل عرض تم تسعيره أو إغلاقه.');
 81:                 }
 82:             } else {
 83:                 $quotation = Quotation::create(['customer_id' => $customer->id, 'quotation_number' => 'QT-'.Str::ulid()]);
 84:             }
 85:             $quotation->items()->delete();
 86:             $subtotal = 0;
 87:             foreach ($data['items'] as $item) {
 88:                 $variant = ProductVariant::query()->where('is_active', true)->whereHas('product', fn ($q) => $q->where('status', 'published')->whereIn('sales_channel', ['wholesale', 'both']))->findOrFail($item['product_variant_id']);
 89:                 $price = $this->pricing->resolve($variant, $customer, $item['qty'])['unit_price'];
 90:                 $total = round($price * $item['qty'], 2);
 91:                 $quotation->items()->create([
 92:                     ...$item, 'offered_unit_price' => $price, 'line_total' => $total,
 93:                 ]);
 94:                 $subtotal += $total;
 95:             }
 96:             $quotation->update(['status' => $data['status'] ?? 'requested', 'customer_notes' => $data['customer_notes'] ?? null,
 97:                 'subtotal' => $subtotal, 'discount_amount' => 0, 'tax_amount' => 0, 'grand_total' => $subtotal]);
 98: 
 99:             return $quotation->fresh('items');
100:         });
101:     }
102: 
103:     public function priceQuotation(Quotation $quotation, array $data): Quotation
104:     {
105:         return DB::transaction(function () use ($quotation, $data): Quotation {
106:             $quotation = Quotation::query()->lockForUpdate()->findOrFail($quotation->id);
107:             if (! in_array($quotation->status, ['requested', 'priced_by_admin'], true)) {
108:                 throw new BusinessException('عرض السعر غير قابل للتسعير.');
109:             }
110:             if (count($data['items']) !== $quotation->items()->count()) {
111:                 throw new BusinessException('يجب تسعير كل عناصر العرض.');
112:             }
113:             foreach ($data['items'] as $item) {
114:                 $line = $quotation->items()->whereKey($item['id'])->firstOrFail();
115:                 $line->update(['offered_unit_price' => $item['offered_unit_price'], 'line_total' => round($item['offered_unit_price'] * $line->qty, 2)]);
116:             }
117:             $subtotal = (float) $quotation->items()->sum('line_total');
118:             $discount = (float) ($data['discount_amount'] ?? 0);
119:             if ($discount > $subtotal) {
120:                 throw new BusinessException('الخصم يتجاوز إجمالي العرض.');
121:             }
122:             $quotation->update(['status' => 'priced_by_admin', 'valid_until' => $data['valid_until'],
123:                 'admin_notes' => $data['admin_notes'] ?? null, 'subtotal' => $subtotal, 'discount_amount' => $discount,
124:                 'tax_amount' => $data['tax_amount'] ?? 0, 'grand_total' => round($subtotal - $discount + ($data['tax_amount'] ?? 0), 2)]);
125: 
126:             return $quotation->fresh('items');
127:         });
128:     }
129: 
130:     public function acceptQuotation(Customer $customer, Quotation $quotation): Order
131:     {
132:         return DB::transaction(function () use ($customer, $quotation): Order {
133:             $customer = Customer::query()->lockForUpdate()->findOrFail($customer->id);
134:             $quotation = Quotation::query()->where('customer_id', $customer->id)->lockForUpdate()->findOrFail($quotation->id);
135:             if ($quotation->status === 'converted_to_order') {
136:                 return Order::findOrFail($quotation->order_id);
137:             }
138:             if ($quotation->status !== 'priced_by_admin' || $quotation->valid_until?->endOfDay()->isPast()) {
139:                 throw new BusinessException('عرض السعر غير مسعر أو انتهت صلاحيته.');
140:             }
141:             if ($this->usedCredit($customer) + (float) $quotation->grand_total > (float) $customer->credit_limit) {
142:                 throw new BusinessException('الرصيد الائتماني المتاح غير كافٍ.');
143:             }
144:             $order = Order::create([
145:                 'order_number' => app(SettingService::class)->generateNextNumber('order'), 'customer_id' => $customer->id,
146:                 'channel' => 'wholesale', 'status' => OrderStatus::Pending, 'payment_method' => 'credit', 'payment_status' => 'unpaid',
147:                 'subtotal' => $quotation->subtotal, 'discount_amount' => $quotation->discount_amount,
148:                 'tax_amount' => $quotation->tax_amount, 'grand_total' => $quotation->grand_total,
149:             ]);
150:             $runningSubtotal = $allocatedDiscount = $allocatedTax = 0.0;
151:             foreach ($quotation->items()->with('variant.product')->orderBy('id')->get() as $item) {
152:                 if (! $item->variant?->is_active || ! $item->variant->product?->is_active || ! $item->variant->product->sales_channel->allowsWholesale()) {
153:                     throw new BusinessException('أحد أصناف العرض لم يعد متاحًا للبيع.');
154:                 }
155:                 $runningSubtotal += (float) $item->line_total;
156:                 $targetDiscount = round((float) $quotation->discount_amount * $runningSubtotal / (float) $quotation->subtotal, 2);
157:                 $targetTax = round((float) $quotation->tax_amount * $runningSubtotal / (float) $quotation->subtotal, 2);
158:                 $discountShare = round($targetDiscount - $allocatedDiscount, 2);
159:                 $taxShare = round($targetTax - $allocatedTax, 2);
160:                 $allocatedDiscount = $targetDiscount;
161:                 $allocatedTax = $targetTax;
162:                 $order->items()->create([
163:                     'product_variant_id' => $item->product_variant_id, 'qty' => $item->qty,
164:                     'product_name_snapshot' => $item->variant->product->name_ar, 'sku_snapshot' => $item->variant->sku,
165:                     'unit_price' => $item->offered_unit_price, 'line_total' => (float) $item->line_total - $discountShare,
166:                     'discount_amount' => $discountShare, 'tax_amount' => $taxShare,
167:                 ]);
168:             }
169:             $actor = User::query()->where('email', config('orders.system_user_email', 'system@alfarid.local'))->value('id');
170:             app(OrderAllocationService::class)->allocate($order->load('items'), performedBy: (int) $actor);
171:             $this->recordCreditPurchase($order);
172:             $order = app(OrderService::class)->changeStatus($order, OrderStatus::Confirmed, $customer, 'قبول عرض سعر '.$quotation->quotation_number);
173:             $quotation->update(['status' => 'converted_to_order', 'order_id' => $order->id]);
174: 
175:             return $order->load('items');
176:         });
177:     }
178: 
179:     public function reviewPayment(WholesalePaymentNotice $notice, array $data, User $reviewer): WholesalePaymentNotice
180:     {
181:         return DB::transaction(function () use ($notice, $data, $reviewer): WholesalePaymentNotice {
182:             Customer::query()->lockForUpdate()->findOrFail($notice->customer_id);
183:             $notice = WholesalePaymentNotice::query()->lockForUpdate()->findOrFail($notice->id);
184:             if ($notice->status !== 'pending_review') {
185:                 throw new BusinessException('تمت مراجعة إشعار السداد بالفعل.');
186:             }
187:             if ($data['status'] === 'approved') {
188:                 $customer = Customer::findOrFail($notice->customer_id);
189:                 if ((float) $notice->amount > $this->usedCredit($customer)) {
190:                     throw new BusinessException('السداد يتجاوز مديونية العميل.');
191:                 }
192:                 $this->allocatePayment($notice, $customer);
193:                 $bank = Treasury::query()->where('type', 'bank_account')->where('is_active', true)->findOrFail($data['treasury_id']);
194:                 app(TreasuryService::class)->record([
195:                     'treasury_id' => $bank->id, 'type' => TreasuryTransactionType::CustomerReceipt, 'amount' => $notice->amount,
196:                     'reference_type' => WholesalePaymentNotice::class, 'reference_id' => $notice->id, 'created_by' => $reviewer->id,
197:                 ]);
198:                 DB::table('customer_credit_transactions')->insert([
199:                     'customer_id' => $customer->id, 'order_id' => $notice->order_id, 'payment_notice_id' => $notice->id,
200:                     'type' => 'payment', 'amount' => -(float) $notice->amount, 'created_at' => now(), 'updated_at' => now(),
201:                 ]);
202:             }
203:             $notice->update(['status' => $data['status'], 'reviewed_by' => $reviewer->id,
204:                 'treasury_id' => $data['treasury_id'] ?? null, 'admin_notes' => $data['admin_notes'] ?? null]);
205: 
206:             return $notice->fresh();
207:         });
208:     }
209: 
210:     private function allocatePayment(WholesalePaymentNotice $notice, Customer $customer): void
211:     {
212:         $orders = Order::query()->where('customer_id', $customer->id)->where('payment_method', 'credit')
213:             ->whereNotIn('status', ['cancelled', 'returned'])
214:             ->when($notice->order_id, fn ($q, $id) => $q->whereKey($id))->orderBy('id')->lockForUpdate()->get();
215:         $remaining = (int) round((float) $notice->amount * 100);
216:         foreach ($orders as $order) {
217:             $debits = (float) DB::table('customer_credit_transactions')->where('order_id', $order->id)->where('type', '!=', 'payment')->sum('amount');
218:             $paid = (float) DB::table('wholesale_payment_allocations')->where('order_id', $order->id)->sum('amount');
219:             $due = max(0, (int) round(($debits - $paid) * 100));
220:             $applied = min($remaining, $due);
221:             if ($applied > 0) {
222:                 DB::table('wholesale_payment_allocations')->insert(['payment_notice_id' => $notice->id, 'order_id' => $order->id, 'amount' => $applied / 100]);
223:                 if ($applied === $due) {
224:                     $order->update(['payment_status' => 'paid']);
225:                 }
226:                 $remaining -= $applied;
227:             }
228:             if ($remaining === 0) {
229:                 break;
230:             }
231:         }
232:         if ($remaining > 0) {
233:             throw new BusinessException('السداد يتجاوز المتبقي على الفاتورة أو الفواتير الآجلة.');
234:         }
235:     }
