31:     public function test_order_event_is_queued_only_after_commit_and_never_after_rollback(): void
32:     {
33:         Queue::fake();
34:         DB::beginTransaction();
35:         Order::factory()->create();
36:         Queue::assertNothingPushed();
37:         DB::rollBack();
38:         Queue::assertNothingPushed();
39:         DB::transaction(fn () => Order::factory()->create());
40:         Queue::assertPushed(CallQueuedListener::class, fn ($job) => $job->class === SendBusinessNotifications::class
41:             && $job->data[0] instanceof OrderCreated);
42:         Queue::assertPushed(CallQueuedListener::class, 1);
43:     }
