45:     public function test_listeners_notify_customer_supplier_and_only_matching_branch_managers(): void
46:     {
47:         Notification::fake();
48:         Queue::fake();
49:         $branch = Branch::factory()->create();
50:         $manager = User::factory()->create(['branch_id' => $branch->id, 'is_active' => true]);
51:         $other = User::factory()->create(['branch_id' => Branch::factory()->create()->id, 'is_active' => true]);
52:         $permission = Permission::findOrCreate('inventory.view', 'staff');
53:         $manager->givePermissionTo($permission);
54:         $other->givePermissionTo($permission);
55:         $listener = new SendBusinessNotifications;
56:         $listener->handle(new StockLowDetected(['branch_id' => $branch->id, 'product_variant_id' => 1]));
57:         Notification::assertSentTo($manager, LowStockAlertNotification::class);
58:         Notification::assertNotSentTo($other, LowStockAlertNotification::class);
59:         $customer = Customer::factory()->create();
60:         $listener->handle(new OrderCreated(['customer_id' => $customer->id, 'order_id' => 1]));
61:         Notification::assertSentTo($customer, OrderConfirmationNotification::class);
62:         $listener->handle(new WholesaleApplicationReviewed(['customer_id' => $customer->id, 'status' => 'approved']));
63:         Notification::assertSentTo($customer, WholesaleApplicationReviewedNotification::class);
64:         $supplier = SupplierUser::factory()->create(['is_active' => true]);
65:         $listener->handle(new PurchaseOrderSentToSupplier(['supplier_id' => $supplier->supplier_id, 'purchase_order_id' => 1]));
66:         Notification::assertSentTo($supplier, PurchaseOrderSentToSupplierNotification::class);
67:     }
