 25: class ExpenseController extends Controller implements HasMiddleware
 26: {
 27:     public static function middleware(): array
 28:     {
 29:         return [
 30:             new Middleware('can:expenses.view', only: ['index', 'show', 'attachment']),
 31:             new Middleware('can:expenses.create', only: ['store']),
 32:             new Middleware('can:expenses.update', only: ['update']),
 33:             new Middleware('can:expenses.delete', only: ['destroy']),
 34:         ];
 35:     }
 36: 
 37:     public function __construct(
 38:         private readonly TreasuryService $treasury,
 39:         private readonly SettingService $settings,
 40:     ) {}
 41: 
 42:     public function index(Request $request): JsonResponse
 43:     {
 44:         $filters = $request->validate([
 45:             'branch_id' => ['nullable', 'integer', 'min:1'],
 46:             'treasury_id' => ['nullable', 'integer', 'min:1'],
 47:             'shift_id' => ['nullable', 'integer', 'min:1'],
 48:             'category' => ['nullable', 'string', 'max:100'],
 49:             'from_date' => ['nullable', 'date_format:Y-m-d'],
 50:             'to_date' => ['nullable', 'date_format:Y-m-d'],
 51:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
 52:         ]);
 53: 
 54:         $expenses = Expense::query()
 55:             ->with(['branch', 'treasury', 'creator'])
 56:             ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
 57:             ->when($filters['treasury_id'] ?? null, fn ($q, $v) => $q->where('treasury_id', $v))
 58:             ->when($filters['shift_id'] ?? null, fn ($q, $v) => $q->where('shift_id', $v))
 59:             ->when($filters['category'] ?? null, fn ($q, $v) => $q->where('category', 'like', "%$v%"))
 60:             ->when($filters['from_date'] ?? null, fn ($q, $v) => $q->where('expense_date', '>=', $v))
 61:             ->when($filters['to_date'] ?? null, fn ($q, $v) => $q->where('expense_date', '<=', $v))
 62:             ->orderByDesc('id')
 63:             ->paginate($filters['per_page'] ?? 15);
 64: 
 65:         return response()->json($expenses);
 66:     }
 67: 
 68:     public function store(Request $request): JsonResponse
 69:     {
 70:         $data = $request->validate([
 71:             'branch_id' => ['required', 'integer', 'min:1', 'exists:branches,id'],
 72:             'treasury_id' => ['required', 'integer', 'min:1', 'exists:treasuries,id'],
 73:             'category' => ['required', 'string', 'max:191'],
 74:             'amount' => ['required', 'numeric', 'min:0.01', 'max:99999999'],
 75:             'expense_date' => ['required', 'date_format:Y-m-d'],
 76:             'attachment' => ['nullable', 'file', 'mimes:jpg,jpeg,png,pdf', 'max:5120'],
 77:             'notes' => ['nullable', 'string', 'max:500'],
 78:         ]);
 79: 
 80:         $expense = PrivateAttachments::transaction(function ($files) use ($data, $request): Expense {
 81:             if ($request->hasFile('attachment')) {
 82:                 $data['attachment_path'] = $files->store($request->file('attachment'), 'expenses');
 83:             }
 84:             unset($data['attachment']);
 85:             $treasury = Treasury::query()->lockForUpdate()->findOrFail($data['treasury_id']);
 86:             abort_unless((int) $treasury->branch_id === (int) $data['branch_id'], 422, 'الخزينة لا تتبع الفرع.');
 87:             if ($treasury->type === TreasuryType::PosDrawer) {
 88:                 $shift = PosShift::query()->where('treasury_id', $treasury->id)->where('status', 'open')->firstOrFail();
 89: 
 90:                 return app(PosService::class)->recordExpense($shift, $data, $request->user()->id);
 91:             }
 92:             $expenseNumber = $this->settings->generateNextNumber('expense');
 93: 
 94:             $expense = Expense::create([
 95:                 ...$data,
 96:                 'expense_number' => $expenseNumber,
 97:                 'created_by' => $request->user()->id,
 98:             ]);
 99: 
100:             // خصم من الخزينة
101:             $this->treasury->record([
102:                 'treasury_id' => $data['treasury_id'],
103:                 'type' => TreasuryTransactionType::Expense,
104:                 'amount' => -(float) $data['amount'],
105:                 'reference_type' => Expense::class,
106:                 'reference_id' => $expense->id,
107:                 'created_by' => $request->user()->id,
108:                 'notes' => "مصروف إداري: {$data['category']} #{$expenseNumber}",
109:             ]);
110: 
111:             return $expense;
112:         });
113: 
114:         return response()->json([
115:             'message' => 'تم تسجيل المصروف بنجاح.',
116:             'data' => $expense->load(['branch', 'treasury', 'creator']),
117:         ], 201);
118:     }
119: 
120:     public function show(Expense $expense): JsonResponse
121:     {
122:         return response()->json(['data' => $expense->load(['branch', 'treasury', 'shift', 'creator'])]);
123:     }
124: 
125:     public function update(Request $request, Expense $expense): JsonResponse
126:     {
127:         $data = $request->validate([
128:             'category' => ['sometimes', 'string', 'max:191'], 'notes' => ['nullable', 'string', 'max:500'],
129:             'amount' => ['sometimes', 'numeric', 'min:0.01', 'max:99999999'],
130:             'expense_date' => ['sometimes', 'date_format:Y-m-d'],
131:             'attachment' => ['nullable', 'file', 'mimes:jpg,jpeg,png,pdf', 'max:5120'],
132:         ]);
133:         $expense = PrivateAttachments::transaction(function ($files) use ($expense, $data, $request) {
134:             $expense = Expense::query()->lockForUpdate()->findOrFail($expense->id);
135:             $shift = $expense->shift_id ? PosShift::query()->lockForUpdate()->findOrFail($expense->shift_id) : null;
136:             abort_if($shift && $shift->status !== PosShiftStatus::Open, 422, 'مصروف الوردية المغلقة لا يمكن تعديله.');
137:             if ($request->hasFile('attachment')) {
138:                 $data['attachment_path'] = $files->store($request->file('attachment'), 'expenses');
139:             }
140:             unset($data['attachment']);
141:             $delta = round((float) ($data['amount'] ?? $expense->amount) - (float) $expense->amount, 2);
142:             if ($delta != 0) {
143:                 $this->treasury->record([
144:                     'treasury_id' => $expense->treasury_id, 'shift_id' => $expense->shift_id,
145:                     'type' => $delta > 0 ? TreasuryTransactionType::Expense : TreasuryTransactionType::CustomerReceipt,
146:                     'amount' => -$delta, 'reference_type' => Expense::class, 'reference_id' => $expense->id,
147:                     'created_by' => $request->user()->id, 'notes' => 'تعديل مبلغ المصروف '.$expense->expense_number,
148:                 ]);
149:                 $shift?->increment('cash_expenses_total', $delta);
150:             }
151:             $expense->update($data);
152: 
153:             return $expense;
154:         });
155: 
156:         return response()->json(['message' => 'تم تحديث المصروف.', 'data' => $expense]);
157:     }
158: 
159:     public function attachment(Expense $expense)
160:     {
161:         abort_unless($expense->attachment_path, 404);
162: 
163:         return Storage::disk('local')->download($expense->attachment_path);
164:     }
165: 
166:     public function destroy(Expense $expense): JsonResponse
167:     {
168:         DB::transaction(function () use ($expense): void {
169:             $expense = Expense::query()->lockForUpdate()->findOrFail($expense->id);
170:             if ($expense->shift_id !== null) {
171:                 $shift = PosShift::query()->lockForUpdate()->findOrFail($expense->shift_id);
172:                 abort_unless($shift->status === PosShiftStatus::Open, 422, 'لا يمكن حذف مصروف وردية مغلقة.');
173:                 $shift->decrement('cash_expenses_total', $expense->amount);
174:             }
175:             $this->treasury->record([
176:                 'treasury_id' => $expense->treasury_id, 'shift_id' => $expense->shift_id,
177:                 'type' => TreasuryTransactionType::CustomerReceipt, 'amount' => $expense->amount,
178:                 'reference_type' => Expense::class, 'reference_id' => $expense->id,
179:                 'created_by' => auth()->id(), 'notes' => 'عكس مصروف محذوف '.$expense->expense_number,
180:             ]);
181:             $expense->delete();
182:         });
183: 
184:         return response()->json(['message' => 'تم حذف المصروف.']);
185:     }
