18: /**
19:  * متحكم مراجعة واعتماد الورديات من لوحة الإدارة.
20:  */
21: class PosShiftAdminController extends Controller implements HasMiddleware
22: {
23:     public static function middleware(): array
24:     {
25:         return [
26:             new Middleware('can:pos_shifts.view',    only: ['index', 'show']),
27:             new Middleware('can:pos_shifts.approve', only: ['approve']),
28:         ];
29:     }
30: 
31:     public function __construct(private readonly PosService $pos) {}
32: 
33:     /**
34:      * GET /admin/shifts — قائمة الورديات للمراجعة الإدارية.
35:      */
36:     public function index(Request $request): JsonResponse
37:     {
38:         $filters = $request->validate([
39:             'branch_id' => ['nullable', 'integer', 'min:1'],
40:             'user_id'   => ['nullable', 'integer', 'min:1'],
41:             'status'    => ['nullable', Rule::in(array_column(PosShiftStatus::cases(), 'value'))],
42:             'from_date' => ['nullable', 'date_format:Y-m-d'],
43:             'to_date'   => ['nullable', 'date_format:Y-m-d'],
44:             'per_page'  => ['nullable', 'integer', 'min:1', 'max:100'],
45:         ]);
46: 
47:         $shifts = PosShift::query()
48:             ->with(['cashier', 'treasury', 'branch', 'approver'])
49:             ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
50:             ->when($filters['user_id'] ?? null, fn ($q, $v) => $q->where('user_id', $v))
51:             ->when($filters['status'] ?? null, fn ($q, $v) => $q->where('status', $v))
52:             ->when($filters['from_date'] ?? null, fn ($q, $v) => $q->where('opened_at', '>=', $v))
53:             ->when($filters['to_date'] ?? null, fn ($q, $v) => $q->where('opened_at', '<=', $v.' 23:59:59'))
54:             ->orderByDesc('id')
55:             ->paginate($filters['per_page'] ?? 15);
56: 
57:         return response()->json($shifts);
58:     }
59: 
60:     /**
61:      * GET /admin/shifts/{id}
62:      */
63:     public function show(PosShift $shift): JsonResponse
64:     {
