 18: class TreasuryController extends Controller implements HasMiddleware
 19: {
 20:     public static function middleware(): array
 21:     {
 22:         return [
 23:             new Middleware('can:treasuries.view', only: ['index', 'show']),
 24:             new Middleware('can:treasuries.create', only: ['store']),
 25:             new Middleware('can:treasuries.update', only: ['update']),
 26:             new Middleware('can:treasuries.delete', only: ['destroy']),
 27:         ];
 28:     }
 29: 
 30:     public function index(Request $request): JsonResponse
 31:     {
 32:         $filters = $request->validate([
 33:             'branch_id' => ['nullable', 'integer', 'min:1'],
 34:             'type' => ['nullable', Rule::in(array_column(TreasuryType::cases(), 'value'))],
 35:             'is_active' => ['nullable', 'boolean'],
 36:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
 37:         ]);
 38: 
 39:         $treasuries = Treasury::query()
 40:             ->with('branch')
 41:             ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
 42:             ->when($filters['type'] ?? null, fn ($q, $v) => $q->where('type', $v))
 43:             ->when(isset($filters['is_active']), fn ($q) => $q->where('is_active', $filters['is_active']))
 44:             ->orderBy('branch_id')
 45:             ->orderBy('id')
 46:             ->paginate($filters['per_page'] ?? 15);
 47: 
 48:         return response()->json($treasuries);
