 51:     public function store(Request $request): JsonResponse
 52:     {
 53:         $data = $request->validate([
 54:             'name' => ['required', 'string', 'max:191'],
 55:             'code' => ['required', 'string', 'max:50', 'unique:treasuries,code'],
 56:             'branch_id' => ['nullable', 'integer', 'min:1', 'exists:branches,id'],
 57:             'type' => ['required', Rule::in(array_column(TreasuryType::cases(), 'value'))],
 58:             'is_active' => ['nullable', 'boolean'],
 59:         ]);
 60: 
 61:         $treasury = Treasury::create($data + ['current_balance' => 0]);
