 77:             'name' => ['sometimes', 'string', 'max:191'],
 78:             'code' => ['sometimes', 'string', 'max:50', Rule::unique('treasuries', 'code')->ignore($treasury->id)],
 79:             'branch_id' => ['nullable', 'integer', 'min:1', 'exists:branches,id'],
 80:             'type' => ['sometimes', Rule::in(array_column(TreasuryType::cases(), 'value'))],
 81:             'is_active' => ['nullable', 'boolean'],
 82:         ]);
 83: 
 84:         if ((array_key_exists('branch_id', $data) && $data['branch_id'] != $treasury->branch_id)
 85:             || (isset($data['type']) && $data['type'] !== $treasury->type->value)) {
 86:             abort_if($treasury->transactions()->exists() || PosShift::where('treasury_id', $treasury->id)->exists(), 422, 'لا يمكن تغيير نوع أو فرع خزينة لها حركات.');
 87:         }
