15: use Illuminate\Support\Facades\Hash;
16: use Illuminate\Support\Facades\RateLimiter;
17: use Illuminate\Support\Str;
18: 
19: /**
20:  * مصادقة الكاشير على نقطة البيع.
21:  * تختلف عن تسجيل دخول الإدارة بقيد الفرع الإلزامي.
22:  */
23: class PosAuthController extends Controller
24: {
25:     private const DUMMY_PASSWORD_HASH = '$2y$12$dRibbzvWAKqkXBRPna4QCuri7dR8TKHRGDIt.RsplFZRfRcJzmPlq';
26: 
27:     public function login(Request $request): JsonResource|JsonResponse
28:     {
29:         $data = $request->validate([
30:             'email' => ['required', 'string', 'email:rfc', 'max:191'],
31:             'password' => ['required', 'string', 'max:72'],
32:             'branch_id' => ['required', 'integer', 'min:1'],
33:         ]);
34: 
35:         $user = User::query()
36:             ->whereRaw('LOWER(email) = ?', [mb_strtolower(trim($data['email']))])
37:             ->first();
38: 
39:         $storedHash = $user instanceof User ? $user->password : self::DUMMY_PASSWORD_HASH;
40:         $passwordOk = Hash::check($data['password'], $storedHash);
41: 
42:         // التحقق من صلاحية الدخول إلى هذا الفرع تحديداً
43:         $branchAllowed = $user instanceof User
44:             && $user->is_active
45:             && $user->branch_id === (int) $data['branch_id'];
46: 
47:         if (! $user instanceof User || ! $passwordOk || ! $branchAllowed) {
48:             return response()->json([
49:                 'message' => 'بيانات تسجيل الدخول غير صحيحة أو الحساب غير مصرح له على هذا الفرع.',
50:             ], 401);
51:         }
52: 
53:         // التحقق من وجود الفرع ونشاطه
54:         Branch::query()->where('id', $data['branch_id'])->where('is_active', true)->firstOrFail();
55: 
56:         $emailKey = hash('sha256', Str::lower(trim($data['email'])));
57:         RateLimiter::clear('pos-login:'.$emailKey);
58: 
59:         $user->load(['branch', 'roles.permissions', 'permissions']);
60:         $token = $user->createToken('pos-token', ['pos', 'branch:'.$user->branch_id])->plainTextToken;
61: 
62:         return UserResource::make($user)->additional(['token' => $token]);
63:     }
64: 
65:     public function logout(Request $request): Response
66:     {
67:         $request->user('staff')?->currentAccessToken()?->delete();
68: 
69:         return response()->noContent();
70:     }
71: } 1: <?php
