 23: 
 24:     /**
 25:      * POST /pos/sales — إنشاء فاتورة بيع مباشر.
 26:      */
 27:     public function store(Request $request): JsonResponse
 28:     {
 29:         $data = $request->validate([
 30:             'items' => ['required', 'array', 'min:1', 'max:100'],
 31:             'items.*.product_variant_id' => ['required', 'integer', 'min:1', 'distinct'],
 32:             'items.*.qty' => ['required', 'integer', 'min:1', 'max:9999'],
 33:             'items.*.unit_price' => ['nullable', 'numeric', 'min:0'],
 34:             'items.*.discount_amount' => ['nullable', 'numeric', 'min:0'],
 35:             'customer_id' => ['nullable', 'integer', 'min:1'],
 36:             'payment_method' => ['nullable', 'string', 'in:cash,card,mixed'],
 37:             'cash_amount' => ['nullable', 'numeric', 'min:0'],
 38:             'card_amount' => ['nullable', 'numeric', 'min:0'],
 39:             'override_price' => ['nullable', 'boolean'],
 40:             'notes' => ['nullable', 'string', 'max:500'],
 41:         ]);
 42: 
 43:         /** @var PosShift|null $shift */
 44:         $shift = $request->attributes->get('pos_shift') ?? PosShift::query()
 45:             ->where('user_id', $request->user('staff')?->id)
 46:             ->where('branch_id', $request->user('staff')?->branch_id)
 47:             ->where('status', 'open')
 48:             ->first();
 49: 
 50:         if (! $shift) {
 51:             return response()->json(['message' => 'يجب فتح وردية أولاً قبل إجراء أي عملية بيع أو مرتجع أو استبدال.'], 403);
 52:         }
 53: 
 54:         // التحقق من صلاحية تجاوز السعر
 55:         if (! empty($data['override_price'])) {
 56:             $user = $request->user('staff');
 57:             if (! $user->can('pos.override_price')) {
 58:                 return response()->json(['message' => 'لا تملك صلاحية تجاوز سعر البيع.'], 403);
 59:             }
 60:         }
 61: 
 62:         $order = $this->pos->createSale($shift, $data);
 63: 
 64:         return response()->json([
 65:             'message' => 'تم تسجيل البيع بنجاح.',
 66:             'data' => $this->formatOrder($order),
 67:         ], 201);
