154:     /**
155:      * POST /pos/sales/{id}/exchange — استبدال من فاتورة POS.
156:      */
157:     public function processExchange(Request $request, Order $sale): JsonResponse
158:     {
159:         $data = $request->validate([
160:             'returned_items' => ['required', 'array', 'min:1'],
161:             'returned_items.*.product_variant_id' => ['required', 'integer', 'min:1', 'distinct'],
162:             'returned_items.*.qty' => ['required', 'integer', 'min:1'],
163:             'returned_items.*.return_to' => ['nullable', 'string', 'in:on_hand,damaged'],
164:             'exchange_items' => ['required', 'array', 'min:1'],
165:             'exchange_items.*.product_variant_id' => ['required', 'integer', 'min:1', 'distinct'],
166:             'exchange_items.*.qty' => ['required', 'integer', 'min:1'],
167:             'exchange_items.*.unit_price' => ['nullable', 'numeric', 'min:0'],
168:         ]);
169: 
170:         /** @var PosShift|null $shift */
171:         $shift = $request->attributes->get('pos_shift') ?? PosShift::query()
172:             ->where('user_id', $request->user('staff')?->id)
173:             ->where('branch_id', $request->user('staff')?->branch_id)
174:             ->where('status', 'open')
175:             ->first();
176: 
177:         if (! $shift) {
178:             return response()->json(['message' => 'يجب فتح وردية أولاً قبل إجراء أي عملية بيع أو مرتجع أو استبدال.'], 403);
179:         }
180: 
181:         $sale->load('items');
182: 
183:         $result = $this->pos->processReturn(
184:             $shift,
185:             $sale,
186:             $data['returned_items'],
187:             $data['exchange_items'],
188:         );
189: 
190:         return response()->json([
191:             'message' => 'تم تسجيل الاستبدال بنجاح.',
192:             'data' => $result,
193:         ]);
194:     }
195: 
196:     // ===================================================================
197:     //  Helper
198:     // ===================================================================
199: 
200:     private function formatOrder(Order $order): array
201:     {
202:         return [
203:             'id' => $order->id,
204:             'order_number' => $order->order_number,
205:             'channel' => $order->channel,
206:             'status' => $order->status->value,
207:             'grand_total' => $order->grand_total,
208:             'cash_amount' => $order->cash_amount,
209:             'card_amount' => $order->card_amount,
210:             'customer' => $order->relationLoaded('customer') ? [
211:                 'id' => $order->customer?->id,
212:                 'name' => $order->customer?->name,
213:             ] : null,
214:             'items' => $order->relationLoaded('items') ? $order->items->map(fn ($i) => [
215:                 'product_variant_id' => $i->product_variant_id,
216:                 'sku' => $i->relationLoaded('variant') ? $i->variant?->sku : null,
217:                 'qty' => $i->qty,
218:                 'unit_price' => $i->unit_price,
219:                 'discount_amount' => $i->discount_amount,
220:                 'line_total' => $i->line_total,
221:             ])->all() : [],
222:         ];
223:     }
