 13: use Illuminate\Http\JsonResponse;
 14: use Illuminate\Http\Request;
 15: 
 16: class PosShiftController extends Controller
 17: {
 18:     public function __construct(private readonly PosService $pos) {}
 19: 
 20:     /**
 21:      * فتح وردية جديدة.
 22:      */
 23:     public function open(Request $request): JsonResponse
 24:     {
 25:         $data = $request->validate([
 26:             'treasury_id'  => ['required', 'integer', 'min:1'],
 27:             'opening_cash' => ['required', 'numeric', 'min:0', 'max:9999999'],
 28:         ]);
 29: 
 30:         /** @var User $user */
 31:         $user = $request->user('staff');
 32: 
 33:         $shift = $this->pos->openShift(
 34:             user: $user,
 35:             branchId: (int) $user->branch_id,
 36:             treasuryId: (int) $data['treasury_id'],
 37:             openingCash: (float) $data['opening_cash'],
 38:         );
 39: 
 40:         return response()->json([
 41:             'message' => 'تم فتح الوردية بنجاح.',
 42:             'data'    => $this->formatShift($shift->load(['cashier', 'treasury', 'branch'])),
 43:         ], 201);
 44:     }
 45: 
 46:     /**
 47:      * عرض الوردية المفتوحة للكاشير الحالي.
 48:      */
 49:     public function current(Request $request): JsonResponse
 50:     {
 51:         /** @var User $user */
 52:         $user = $request->user('staff');
 53: 
 54:         $shift = PosShift::query()
 55:             ->where('user_id', $user->id)
 56:             ->where('branch_id', $user->branch_id)
 57:             ->where('status', PosShiftStatus::Open)
 58:             ->with(['cashier', 'treasury', 'branch'])
 59:             ->latest('id')
 60:             ->first();
 61: 
 62:         if ($shift === null) {
 63:             return response()->json(['data' => null, 'has_open_shift' => false]);
 64:         }
 65: 
 66:         return response()->json([
 67:             'data'           => $this->formatShift($shift),
 68:             'has_open_shift' => true,
 69:         ]);
 70:     }
 71: 
 72:     /**
 73:      * إغلاق الوردية.
 74:      */
 75:     public function close(Request $request): JsonResponse
 76:     {
 77:         $data = $request->validate([
 78:             'actual_closing_cash' => ['required', 'numeric', 'min:0', 'max:9999999'],
 79:             'notes'               => ['nullable', 'string', 'max:500'],
 80:         ]);
 81: 
 82:         /** @var PosShift|null $shift */
 83:         $shift = $request->attributes->get('pos_shift') ?? PosShift::query()
 84:             ->where('user_id', $request->user('staff')?->id)
 85:             ->where('branch_id', $request->user('staff')?->branch_id)
 86:             ->where('status', PosShiftStatus::Open)
 87:             ->first();
 88: 
 89:         if (! $shift) {
 90:             return response()->json(['message' => 'لا توجد وردية مفتوحة لإغلاقها.'], 403);
 91:         }
 92: 
 93:         $shift = $this->pos->closeShift(
 94:             shift: $shift,
 95:             actualCash: (float) $data['actual_closing_cash'],
 96:             notes: $data['notes'] ?? null,
 97:         );
 98: 
 99:         return response()->json([
100:             'message' => 'تم إغلاق الوردية وهي بانتظار اعتماد المدير.',
101:             'data'    => $this->formatShift($shift),
102:         ]);
103:     }
104: 
105:     // ===================================================================
106:     //  Helper
107:     // ===================================================================
108: 
109:     private function formatShift(PosShift $shift): array
110:     {
111:         return [
112:             'id'                    => $shift->id,
113:             'shift_number'          => $shift->shift_number,
114:             'status'                => $shift->status->value,
115:             'opened_at'             => $shift->opened_at,
116:             'closed_at'             => $shift->closed_at,
117:             'approved_at'           => $shift->approved_at,
118:             'opening_cash'          => $shift->opening_cash,
119:             'cash_sales_total'      => $shift->cash_sales_total,
120:             'card_sales_total'      => $shift->card_sales_total,
121:             'cash_returns_total'    => $shift->cash_returns_total,
122:             'cash_expenses_total'   => $shift->cash_expenses_total,
123:             'expected_closing_cash' => $shift->expected_closing_cash,
124:             'actual_closing_cash'   => $shift->actual_closing_cash,
125:             'cash_difference'       => $shift->cash_difference,
126:             'notes'                 => $shift->notes,
127:             'cashier'               => $shift->relationLoaded('cashier') ? [
128:                 'id'   => $shift->cashier->id,
129:                 'name' => $shift->cashier->name,
130:             ] : null,
131:             'treasury'              => $shift->relationLoaded('treasury') ? [
132:                 'id'   => $shift->treasury->id,
133:                 'name' => $shift->treasury->name,
134:                 'code' => $shift->treasury->code,
135:             ] : null,
136:             'branch'                => $shift->relationLoaded('branch') ? [
137:                 'id'   => $shift->branch->id,
138:                 'name' => $shift->branch->name,
139:             ] : null,
140:         ];
141:     }
142: }  1: <?php
