  5: namespace App\Http\Controllers\Api\V1\Pos;
  6: 
  7: use App\Enums\StocktakeStatus;
  8: use App\Http\Controllers\Controller;
  9: use App\Http\Resources\Admin\StockLevelResource;
 10: use App\Models\ProductVariant;
 11: use App\Models\StockLevel;
 12: use App\Models\Stocktake;
 13: use App\Models\StockTransfer;
 14: use App\Models\User;
 15: use App\Services\StocktakeService;
 16: use App\Services\TransferService;
 17: use Illuminate\Http\JsonResponse;
 18: use Illuminate\Http\Request;
 19: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
 20: 
 21: /**
 22:  * عمليات المخزون من شاشة الـ POS:
 23:  * - عرض أرصدة الفرع
 24:  * - طلب تحويل بضاعة
 25:  * - تأكيد استلام تحويلة
 26:  * - مسح الباركود في جلسة الجرد
 27:  */
 28: class PosStockController extends Controller
 29: {
 30:     public function __construct(
 31:         private readonly TransferService $transfers,
 32:         private readonly StocktakeService $stocktakes,
 33:     ) {}
 34: 
 35:     /**
 36:      * GET /pos/stock — أرصدة مخزون الفرع الحالي.
 37:      */
 38:     public function index(Request $request): AnonymousResourceCollection
 39:     {
 40:         $filters = $request->validate([
 41:             'product_variant_id' => ['nullable', 'integer', 'min:1'],
 42:             'q' => ['nullable', 'string', 'max:100'],
 43:             'low_stock' => ['nullable', 'boolean'],
 44:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
 45:         ]);
 46: 
 47:         /** @var User $user */
 48:         $user = $request->user('staff');
 49: 
 50:         $levels = StockLevel::query()
 51:             ->where('branch_id', $user->branch_id)
 52:             ->with(['variant.product', 'location'])
 53:             ->when($filters['product_variant_id'] ?? null, fn ($q, $v) => $q->where('product_variant_id', $v))
 54:             ->when($filters['q'] ?? null, fn ($q, $v) => $q->whereHas('variant', fn ($vq) => $vq->where('sku', $v)
 55:                 ->orWhere('barcode', $v)
 56:                 ->orWhereHas('product', fn ($pq) => $pq->whereRaw('LOWER(name_ar) LIKE ?', ['%'.mb_strtolower($v).'%']))
 57:             ))
 58:             ->when($filters['low_stock'] ?? null, fn ($q) => $q
 59:                 ->join('product_variants', 'product_variants.id', '=', 'stock_levels.product_variant_id')
 60:                 ->whereRaw('stock_levels.available <= COALESCE(NULLIF(stock_levels.reorder_level, 0), product_variants.reorder_level, 0)')
 61:                 ->whereRaw('COALESCE(NULLIF(stock_levels.reorder_level, 0), product_variants.reorder_level, 0) > 0')
 62:                 ->select('stock_levels.*')
 63:             )
 64:             ->orderBy('product_variant_id')
 65:             ->paginate($filters['per_page'] ?? 15);
 66: 
 67:         return StockLevelResource::collection($levels);
 68:     }
 69: 
 70:     /**
 71:      * POST /pos/transfer-requests — طلب تحويل بضاعة إلى الفرع الحالي.
 72:      */
 73:     public function requestTransfer(Request $request): JsonResponse
 74:     {
 75:         /** @var User $user */
 76:         $user = $request->user('staff');
 77: 
 78:         $data = $request->validate([
 79:             'from_branch_id' => ['required', 'integer', 'min:1', 'exists:branches,id', 'different:to_branch_id'],
 80:             'items' => ['required', 'array', 'min:1', 'max:100'],
 81:             'items.*.product_variant_id' => ['required', 'integer', 'min:1', 'distinct', 'exists:product_variants,id'],
 82:             'items.*.requested_qty' => ['required', 'numeric', 'min:0.0001'],
 83:             'notes' => ['nullable', 'string', 'max:500'],
 84:         ]);
 85: 
 86:         $data['to_branch_id'] = $user->branch_id;
 87: 
 88:         $transfer = $this->transfers->requestIncoming($data, $user->id);
 89: 
 90:         return response()->json([
 91:             'message' => 'تم إرسال طلب التحويل بنجاح وهو في انتظار الاعتماد.',
 92:             'transfer_number' => $transfer->transfer_number,
 93:             'id' => $transfer->id,
 94:         ], 201);
 95:     }
 96: 
 97:     /**
 98:      * POST /pos/transfers/{transfer}/receive — تأكيد استلام تحويلة واردة للفرع.
 99:      */
100:     public function receiveTransfer(Request $request, StockTransfer $transfer): JsonResponse
101:     {
102:         /** @var User $user */
103:         $user = $request->user('staff');
104: 
105:         // التحقق أن الفرع المستقبل هو فرع الكاشير
106:         if ((int) $transfer->to_branch_id !== (int) $user->branch_id) {
107:             return response()->json(['message' => 'هذه التحويلة ليست موجهة لفرعك.'], 403);
108:         }
109: 
110:         $data = $request->validate([
111:             'items' => ['required', 'array', 'min:1'],
112:             'items.*.id' => ['required', 'integer', 'min:1', 'distinct'],
113:             'items.*.received_qty' => ['required', 'numeric', 'min:0'],
114:             'items.*.to_location_id' => ['nullable', 'integer', 'min:1'],
115:         ]);
116: 
117:         $transfer = $this->transfers->receive($transfer, collect($data['items'])->pluck('received_qty', 'id')->all(), $user->id);
118: 
119:         return response()->json([
120:             'message' => 'تم تأكيد استلام التحويلة بنجاح وتم رفع المخزون.',
121:             'id' => $transfer->id,
122:             'status' => $transfer->status->value,
123:         ]);
124:     }
125: 
126:     /**
127:      * POST /pos/stocktakes/{stocktake}/scan — مسح باركود في جلسة جرد مفتوحة.
128:      *
129:      * يزيد counted_qty بمقدار 1 (أو بالكمية الممررة) للعنصر الموافق للباركود.
130:      * إذا لم يوجد العنصر في الجلسة يُنشئه.
131:      */
132:     public function scan(Request $request, Stocktake $stocktake): JsonResponse
133:     {
134:         /** @var User $user */
135:         $user = $request->user('staff');
136: 
137:         // التحقق أن جلسة الجرد تتبع الفرع الحالي
138:         if ((int) $stocktake->branch_id !== (int) $user->branch_id) {
139:             return response()->json(['message' => 'جلسة الجرد لا تتبع فرعك.'], 403);
140:         }
141: 
142:         if ($stocktake->status !== StocktakeStatus::InProgress) {
143:             return response()->json(['message' => 'جلسة الجرد ليست مفتوحة.'], 422);
144:         }
145: 
146:         $data = $request->validate([
147:             'barcode' => ['required', 'string', 'max:100'],
148:             'qty' => ['nullable', 'integer', 'min:1', 'max:99999'],
149:         ]);
150: 
151:         $qty = (float) ($data['qty'] ?? 1);
152: 
153:         // البحث عن المتغير بالباركود
154:         $variant = ProductVariant::query()
155:             ->where('barcode', $data['barcode'])
156:             ->first();
157: 
158:         if ($variant === null) {
159:             return response()->json([
160:                 'message' => 'لم يُعثر على صنف بهذا الباركود.',
161:                 'barcode' => $data['barcode'],
162:             ], 404);
163:         }
164: 
165:         $item = $this->stocktakes->scan($stocktake, $variant->id, (int) $qty, $user->id);
166: 
167:         return response()->json([
168:             'message' => 'تم تسجيل المسح بنجاح.',
169:             'product_variant_id' => $variant->id,
170:             'sku' => $variant->sku,
171:             'counted_qty' => $item->counted_qty,
172:             'system_qty' => $item->system_qty,
173:         ]);
174:     }
175: } 1: <?php
