 29: /**
 30:  * محرك نقطة البيع — كل عملية POS تمر من هنا.
 31:  *
 32:  * القاعدة الذهبية: الكاشير لا يُنفذ أي عملية بلا وردية مفتوحة في فرعه.
 33:  * البيع يخصم من on_hand فوراً (لا حجز مؤقت كالأونلاين).
 34:  */
 35: class PosService
 36: {
 37:     public function __construct(
 38:         private readonly InventoryService $inventory,
 39:         private readonly PricingService $pricing,
 40:         private readonly TreasuryService $treasury,
 41:         private readonly SettingService $settings,
 42:     ) {}
 43: 
 44:     // ===================================================================
 45:     //  الورديات
 46:     // ===================================================================
 47: 
 48:     /**
 49:      * فتح وردية جديدة للكاشير.
 50:      */
 51:     public function openShift(User $user, int $branchId, int $treasuryId, float $openingCash): PosShift
 52:     {
 53:         return DB::transaction(function () use ($user, $branchId, $treasuryId, $openingCash): PosShift {
 54:             $user = User::query()->lockForUpdate()->findOrFail($user->id);
 55:             Treasury::query()->lockForUpdate()->findOrFail($treasuryId);
 56:             if ((int) $user->branch_id !== $branchId || ! $user->is_active || $openingCash < 0) {
 57:                 throw new BusinessException('الفرع أو عهدة الوردية غير صالحة.');
 58:             }
 59:             // التحقق من عدم وجود وردية مفتوحة لنفس الكاشير
 60:             $existingUserShift = PosShift::query()
 61:                 ->where('user_id', $user->id)
 62:                 ->where('status', PosShiftStatus::Open)
 63:                 ->lockForUpdate()
 64:                 ->exists();
 65: 
 66:             if ($existingUserShift) {
 67:                 throw new BusinessException('لديك وردية مفتوحة بالفعل. أغلقها أولًا قبل فتح وردية جديدة.');
 68:             }
 69: 
 70:             // التحقق من عدم وجود وردية مفتوحة على نفس الدرج
 71:             $existingDrawerShift = PosShift::query()
 72:                 ->where('treasury_id', $treasuryId)
 73:                 ->whereIn('status', [PosShiftStatus::Open, PosShiftStatus::ClosedPendingApproval])
 74:                 ->lockForUpdate()
 75:                 ->exists();
 76: 
 77:             if ($existingDrawerShift) {
 78:                 throw new BusinessException('درج النقدية المحدد مفتوح على وردية أخرى.');
 79:             }
 80: 
 81:             // التحقق أن الخزينة تتبع الفرع وهي من نوع درج
 82:             $treasury = Treasury::query()
 83:                 ->where('id', $treasuryId)
 84:                 ->where('branch_id', $branchId)
 85:                 ->where('type', 'pos_drawer')
 86:                 ->where('is_active', true)
 87:                 ->firstOrFail();
 88: 
 89:             $shiftNumber = $this->settings->generateNextNumber('shift');
 90: 
 91:             $shift = PosShift::create([
 92:                 'shift_number' => $shiftNumber,
 93:                 'user_id' => $user->id,
 94:                 'branch_id' => $branchId,
 95:                 'treasury_id' => $treasuryId,
 96:                 'status' => PosShiftStatus::Open,
 97:                 'opened_at' => now(),
 98:                 'opening_cash' => $openingCash,
 99:                 'cash_sales_total' => 0,
100:                 'card_sales_total' => 0,
101:                 'cash_returns_total' => 0,
102:                 'cash_expenses_total' => 0,
103:                 'expected_closing_cash' => $openingCash,
104:             ]);
105: 
106:             // تسجيل رصيد الفتح في دفتر الخزينة
107:             $this->treasury->record([
108:                 'treasury_id' => $treasury->id,
109:                 'shift_id' => $shift->id,
110:                 'type' => TreasuryTransactionType::OpeningBalance,
111:                 'amount' => round($openingCash - (float) $treasury->current_balance, 2),
112:                 'reference_type' => PosShift::class,
113:                 'reference_id' => $shift->id,
114:                 'created_by' => $user->id,
115:                 'notes' => "رصيد فتح وردية #{$shiftNumber}",
116:             ]);
117: 
118:             return $shift;
119:         });
120:     }
121: 
122:     /**
123:      * إغلاق الوردية بعد عدّ الكاشير للنقدية.
124:      *
125:      * expected_closing_cash = opening_cash + cash_sales - cash_returns - cash_expenses
126:      * cash_difference = actual - expected
127:      */
128:     public function closeShift(PosShift $shift, float $actualCash, ?string $notes): PosShift
129:     {
130:         if ($shift->status !== PosShiftStatus::Open) {
131:             throw new BusinessException('يمكن إغلاق الورديات المفتوحة فقط.');
132:         }
133: 
134:         return DB::transaction(function () use ($shift, $actualCash, $notes): PosShift {
135:             $shift = $this->lockedOpenShift($shift);
136:             if ($actualCash < 0) {
137:                 throw new BusinessException('النقدية الفعلية لا يمكن أن تكون سالبة.');
138:             }
139:             // إعادة حساب مجاميع الوردية من بيانات الطلبات الفعلية
140:             $salesStats = Order::query()
141:                 ->where('pos_shift_id', $shift->id)
142:                 ->where('status', OrderStatus::Delivered)
143:                 ->selectRaw('
144:                     COALESCE(SUM(cash_amount), 0) AS cash_sales,
145:                     COALESCE(SUM(card_amount), 0) AS card_sales
146:                 ')
147:                 ->first();
148: 
149:             $cashSales = (float) ($salesStats?->cash_sales ?? 0);
150:             $cardSales = (float) ($salesStats?->card_sales ?? 0);
151: 
152:             $cashReturns = (float) Order::query()
153:                 ->where('pos_shift_id', $shift->id)
154:                 ->where('status', OrderStatus::Returned)
155:                 ->sum('cash_amount');
156: 
157:             $cashExpenses = (float) Expense::query()
158:                 ->where('shift_id', $shift->id)
159:                 ->sum('amount');
160: 
161:             $expectedClosingCash = (float) $shift->opening_cash
162:                 + $cashSales
163:                 - $cashReturns
164:                 - $cashExpenses;
165: 
166:             $cashDifference = $actualCash - $expectedClosingCash;
167: 
168:             $shift->update([
169:                 'status' => PosShiftStatus::ClosedPendingApproval,
170:                 'closed_at' => now(),
171:                 'cash_sales_total' => $cashSales,
172:                 'card_sales_total' => $cardSales,
173:                 'cash_returns_total' => $cashReturns,
174:                 'cash_expenses_total' => $cashExpenses,
175:                 'expected_closing_cash' => $expectedClosingCash,
176:                 'actual_closing_cash' => $actualCash,
177:                 'cash_difference' => $cashDifference,
178:                 'notes' => $notes,
179:             ]);
180: 
181:             return $shift->fresh();
182:         });
183:     }
184: 
185:     /**
186:      * الاعتماد الإداري للوردية المغلقة وترحيل النقدية للخزنة الرئيسية.
187:      */
188:     public function approveShift(PosShift $shift, User $approver): PosShift
189:     {
190:         if ($shift->status !== PosShiftStatus::ClosedPendingApproval) {
191:             throw new BusinessException('يمكن اعتماد الورديات المغلقة المنتظرة للاعتماد فقط.');
192:         }
193: 
194:         return DB::transaction(function () use ($shift, $approver): PosShift {
195:             $shift = PosShift::query()->lockForUpdate()->findOrFail($shift->id);
196:             if ($shift->status !== PosShiftStatus::ClosedPendingApproval) {
197:                 throw new BusinessException('الوردية ليست في انتظار الاعتماد.');
198:             }
199:             $shift->update([
200:                 'status' => PosShiftStatus::Approved,
201:                 'approved_at' => now(),
202:                 'approved_by' => $approver->id,
203:             ]);
204: 
205:             // ترحيل النقدية من الدرج إلى الخزنة الرئيسية
206:             $this->treasury->settleShiftToMainSafe($shift, $approver->id);
207: 
208:             return $shift->fresh();
209:         });
210:     }
