213:     //  البيع
214:     // ===================================================================
215: 
216:     /**
217:      * إنشاء فاتورة بيع POS مع الخصم الفوري من المخزن.
218:      *
219:      * @param  array{
220:      *     items: array<array{product_variant_id: int, qty: int, unit_price?: float|null, discount_amount?: float}>,
221:      *     customer_id?: int|null,
222:      *     payment_method?: string,
223:      *     cash_amount?: float,
224:      *     card_amount?: float,
225:      *     notes?: string|null,
226:      *     override_price?: bool,
227:      * }  $payload
228:      */
229:     public function createSale(PosShift $shift, array $payload): Order
230:     {
231:         if ($shift->status !== PosShiftStatus::Open) {
232:             throw new BusinessException('الوردية غير مفتوحة — لا يمكن إجراء أي بيع.');
233:         }
234: 
235:         return DB::transaction(function () use ($shift, $payload): Order {
236:             $shift = $this->lockedOpenShift($shift);
237:             $customer = isset($payload['customer_id'])
238:                 ? Customer::find($payload['customer_id'])
239:                 : null;
240: 
241:             if (empty($payload['items']) || count(array_unique(array_column($payload['items'], 'product_variant_id'))) !== count($payload['items'])) {
242:                 throw new BusinessException('يجب إدخال أصناف مختلفة وكميات موجبة.');
243:             }
244:             $overridePrice = (bool) ($payload['override_price'] ?? false);
245:             $items = $this->resolveItems($shift, $payload['items'], $customer, $overridePrice);
246: 
247:             $subtotal = $items->sum(fn ($item) => $item['unit_price'] * $item['qty']);
248:             $discountTotal = $items->sum('discount_amount');
249:             $grandTotal = round($subtotal - $discountTotal, 2);
250:             if ($grandTotal < 0 || $grandTotal > 9999999999.99) {
251:                 throw new BusinessException('إجمالي الفاتورة يتجاوز الحد المسموح.');
252:             }
253: 
254:             // التحقق من الدفع المختلط
255:             $cardAmount = (float) ($payload['card_amount'] ?? (($payload['payment_method'] ?? null) === 'card' ? $grandTotal - (float) ($payload['cash_amount'] ?? 0) : 0));
256:             $cashAmount = (float) ($payload['cash_amount'] ?? ($grandTotal - $cardAmount));
257: 
258:             if ($cashAmount < 0 || $cardAmount < 0 || abs(($cashAmount + $cardAmount) - $grandTotal) > 0.001) {
259:                 throw new BusinessException('مجموع المبالغ (نقدي + بطاقة) لا يساوي إجمالي الفاتورة.');
260:             }
261: 
262:             // توليد رقم الطلب بنفس آلية الـ order_next_number
263:             $orderNumber = $this->settings->generateNextNumber('order');
264: 
265:             // إنشاء الطلب بحالة delivered مباشرة (POS = تسليم فوري)
266:             $order = Order::create([
267:                 'order_number' => $orderNumber,
268:                 'channel' => 'pos',
269:                 'customer_id' => $customer?->id,
270:                 'allocated_branch_id' => $shift->branch_id,
271:                 'pos_shift_id' => $shift->id,
272:                 'status' => OrderStatus::Delivered,
273:                 'payment_method' => $cashAmount > 0 && $cardAmount > 0 ? 'mixed' : ($cardAmount > 0 ? 'card' : 'cash'),
274:                 'payment_status' => 'paid',
275:                 'subtotal' => $subtotal,
276:                 'discount_amount' => $discountTotal,
277:                 'shipping_cost' => 0,
278:                 'tax_amount' => 0,
279:                 'grand_total' => $grandTotal,
280:                 'cash_amount' => $cashAmount,
281:                 'card_amount' => $cardAmount,
282:             ]);
283: 
284:             // إنشاء عناصر الطلب وخصم المخزون فوراً
285:             foreach ($items as $item) {
286:                 OrderItem::create([
287:                     'order_id' => $order->id,
288:                     'product_variant_id' => $item['product_variant_id'],
289:                     'product_name_snapshot' => $item['product_name_snapshot'],
290:                     'sku_snapshot' => $item['sku_snapshot'],
291:                     'allocated_branch_id' => $shift->branch_id,
292:                     'qty' => $item['qty'],
293:                     'unit_price' => $item['unit_price'],
294:                     'discount_amount' => $item['discount_amount'],
295:                     'line_total' => $item['line_total'],
296:                 ]);
297: 
298:                 $this->consumeStock($shift, $order, $item);
299: 
300:             }
301: 
302:             // تسجيل تاريخ الحالة
303:             OrderStatusHistory::create([
304:                 'order_id' => $order->id,
305:                 'from_status' => null,
306:                 'to_status' => OrderStatus::Delivered,
307:                 'changed_by_type' => User::class,
308:                 'changed_by_id' => $shift->user_id,
309:                 'notes' => 'بيع POS مباشر',
310:             ]);
311: 
312:             // تسجيل المقبوضة النقدية في الخزينة
313:             if ($cashAmount > 0) {
314:                 $this->treasury->record([
315:                     'treasury_id' => $shift->treasury_id,
316:                     'shift_id' => $shift->id,
317:                     'type' => TreasuryTransactionType::PosSale,
318:                     'amount' => $cashAmount,
319:                     'reference_type' => Order::class,
320:                     'reference_id' => $order->id,
321:                     'created_by' => $shift->user_id,
322:                     'notes' => "مبيعات نقدية POS #{$orderNumber}",
323:                 ]);
324:             }
325: 
326:             $shift->increment('cash_sales_total', $cashAmount);
327:             $shift->increment('card_sales_total', $cardAmount);
328: 
329:             return $order->load(['items.variant', 'customer']);
330:         });
331:     }
332: 
333:     /**
334:      * مرتجع كلي أو جزئي من فاتورة POS.
335:      * يُعيد البضاعة إلى on_hand ويرد النقدية من الدرج إن كانت مدفوعة نقداً.
336:      *
337:      * @param  array<array{product_variant_id: int, qty: int, return_to?: string}>  $returnedItems
338:      * @param  array<array{product_variant_id: int, qty: int}>  $exchangeItems  (للاستبدال)
339:      */
340:     public function processReturn(
341:         PosShift $shift,
342:         Order $originalOrder,
343:         array $returnedItems,
344:         array $exchangeItems = []
345:     ): array {
346:         if ($shift->status !== PosShiftStatus::Open) {
347:             throw new BusinessException('الوردية غير مفتوحة — لا يمكن إجراء أي مرتجع.');
348:         }
349: 
350:         if ($originalOrder->channel !== 'pos') {
351:             throw new BusinessException('يمكن مرتجع طلبات POS فقط من شاشة الـ POS.');
352:         }
353: 
354:         return DB::transaction(function () use ($shift, $originalOrder, $returnedItems, $exchangeItems): array {
355:             $shift = $this->lockedOpenShift($shift);
356:             $originalOrder = Order::query()->lockForUpdate()->findOrFail($originalOrder->id);
357:             if ($originalOrder->status !== OrderStatus::Delivered || (int) $originalOrder->allocated_branch_id !== (int) $shift->branch_id) {
358:                 throw new BusinessException('الطلب لا يتبع هذا الفرع أو ليس فاتورة بيع مسلمة.');
359:             }
360:             $originalOrder->load('items');
361:             if ($originalOrder->returnRequests()->whereNotIn('status', ['rejected', 'cancelled'])->exists()) {
362:                 throw new BusinessException('لهذه الفاتورة مرتجع مسجل بالفعل خارج نقطة البيع؛ راجع الحساب قبل المتابعة.');
363:             }
364:             if (count(array_unique(array_column($returnedItems, 'product_variant_id'))) !== count($returnedItems)) {
365:                 throw new BusinessException('لا يمكن تكرار الصنف في المرتجع.');
366:             }
367:             $exchangeOrder = null;
368:             $refundValues = [];
369:             $returnValue = 0.0;
370:             $returnOrderId = null;
371: 
372:             // ===== معالجة الأصناف المرتجعة =====
373:             if (! empty($returnedItems)) {
374:                 foreach ($returnedItems as $ret) {
375:                     $originalItem = $originalOrder->items
376:                         ->firstWhere('product_variant_id', $ret['product_variant_id']);
377: 
378:                     if ($originalItem === null) {
379:                         throw new BusinessException("الصنف {$ret['product_variant_id']} غير موجود في الطلب الأصلي.");
380:                     }
381: 
382:                     $alreadyReturned = OrderItem::query()->where('product_variant_id', $ret['product_variant_id'])
383:                         ->whereHas('order', fn ($q) => $q->where('original_pos_order_id', $originalOrder->id))->sum('qty');
384:                     if ($ret['qty'] <= 0 || $originalItem->qty < $ret['qty'] + $alreadyReturned) {
385:                         throw new BusinessException("كمية المرتجع ({$ret['qty']}) أكبر من الكمية المباعة ({$originalItem->qty}).");
386:                     }
387: 
388:                     $refundValues[$ret['product_variant_id']] = round((float) $originalItem->line_total * ($alreadyReturned + $ret['qty']) / (float) $originalItem->qty, 2)
389:                         - round((float) $originalItem->line_total * $alreadyReturned / (float) $originalItem->qty, 2);
390:                     $returnValue += $refundValues[$ret['product_variant_id']];
391:                     $bucket = ($ret['return_to'] ?? 'on_hand') === 'damaged'
392:                         ? StockBucket::Damaged
393:                         : StockBucket::OnHand;
394: 
395:                     // إعادة الكمية للمخزون
396:                     $this->inventory->recordMovement([
397:                         'product_variant_id' => $ret['product_variant_id'],
398:                         'branch_id' => $shift->branch_id,
399:                         'type' => StockMovementType::SaleReturn,
400:                         'affected_bucket' => StockBucket::OnHand,
401:                         'quantity' => $ret['qty'],
402:                         'reference_type' => Order::class,
403:                         'reference_id' => $originalOrder->id,
404:                         'created_by' => $shift->user_id,
405:                         'notes' => "مرتجع POS من #{$originalOrder->order_number}",
406:                     ]);
407:                     if ($bucket === StockBucket::Damaged) {
408:                         $this->inventory->recordMovement([
409:                             'product_variant_id' => $ret['product_variant_id'], 'branch_id' => $shift->branch_id,
410:                             'type' => StockMovementType::Damage, 'affected_bucket' => StockBucket::Damaged,
411:                             'quantity' => $ret['qty'], 'reference_type' => Order::class,
412:                             'reference_id' => $originalOrder->id, 'created_by' => $shift->user_id,
413:                         ]);
414:                     }
415:                 }
416: 
417:                 // إنشاء طلب مرتجع
418:                 $returnOrderNumber = $this->settings->generateNextNumber('order');
419:                 $returnOrder = Order::create([
420:                     'order_number' => $returnOrderNumber,
421:                     'original_pos_order_id' => $originalOrder->id,
422:                     'channel' => 'pos',
423:                     'customer_id' => $originalOrder->customer_id,
424:                     'allocated_branch_id' => $shift->branch_id,
425:                     'pos_shift_id' => $shift->id,
426:                     'status' => OrderStatus::Returned,
427:                     'payment_method' => $originalOrder->payment_method,
428:                     'payment_status' => 'refunded',
429:                     'subtotal' => $returnValue,
430:                     'discount_amount' => 0,
431:                     'shipping_cost' => 0,
432:                     'tax_amount' => 0,
433:                     'grand_total' => $returnValue,
434:                     'cash_amount' => $returnValue, // يُرد نقدًا من الدرج
435:                     'card_amount' => 0,
436:                 ]);
437: 
438:                 foreach ($returnedItems as $ret) {
439:                     $originalItem = $originalOrder->items->firstWhere('product_variant_id', $ret['product_variant_id']);
440:                     OrderItem::create([
441:                         'order_id' => $returnOrder->id,
442:                         'product_variant_id' => $ret['product_variant_id'],
443:                         'product_name_snapshot' => $originalItem->product_name_snapshot,
444:                         'sku_snapshot' => $originalItem->sku_snapshot,
445:                         'allocated_branch_id' => $shift->branch_id,
446:                         'qty' => $ret['qty'],
447:                         'unit_price' => $originalItem->unit_price,
448:                         'discount_amount' => 0,
449:                         'line_total' => $refundValues[$ret['product_variant_id']],
450:                     ]);
451:                 }
452: 
453:                 OrderStatusHistory::create([
454:                     'order_id' => $returnOrder->id,
455:                     'from_status' => null,
456:                     'to_status' => OrderStatus::Returned,
457:                     'changed_by_type' => User::class,
458:                     'changed_by_id' => $shift->user_id,
459:                     'notes' => "مرتجع من #{$originalOrder->order_number}",
460:                 ]);
461: 
462:                 if (! empty($exchangeItems)) {
463:                     $exchangeOrder = $this->createSale($shift, [
464:                         'items' => $exchangeItems, 'customer_id' => $originalOrder->customer_id,
465:                     ]);
466:                 }
467: 
468:                 // رد النقدية للعميل من الدرج
469:                 $this->treasury->record([
470:                     'treasury_id' => $shift->treasury_id,
471:                     'shift_id' => $shift->id,
472:                     'type' => TreasuryTransactionType::PosReturn,
473:                     'amount' => -$returnValue,
474:                     'reference_type' => Order::class,
475:                     'reference_id' => $returnOrder->id,
476:                     'created_by' => $shift->user_id,
477:                     'notes' => "رد مرتجع #{$returnOrderNumber}",
478:                 ]);
479: 
480:                 $returnOrderId = $returnOrder->id;
481:             }
482: 
483:             if ($exchangeOrder === null && ! empty($exchangeItems)) {
484:                 $exchangeOrder = $this->createSale($shift, ['items' => $exchangeItems, 'customer_id' => $originalOrder->customer_id]);
485:             }
486:             $exchangeOrderId = $exchangeOrder?->id;
487:             $shift->increment('cash_returns_total', $returnValue);
488: 
489:             return [
490:                 'return_order_id' => $returnOrderId,
491:                 'exchange_order_id' => $exchangeOrderId,
492:                 'refund_amount' => max(0, $returnValue - (float) ($exchangeOrder?->grand_total ?? 0)),
493:                 'amount_due' => max(0, (float) ($exchangeOrder?->grand_total ?? 0) - $returnValue),
494:             ];
495:         });
496:     }
