519:     /**
520:      * بحث فائق السرعة بالباركود أو SKU أو جزء من الاسم.
521:      * يرجع المتغير مع رصيده في الفرع الحالي فقط وسعره.
522:      *
523:      * @return array<int, array<string, mixed>>
524:      */
525:     public function lookupProducts(string $query, int $branchId, ?Customer $customer = null): array
526:     {
527:         $variants = ProductVariant::query()
528:             ->with(['product', 'media'])
529:             ->whereHas('product', fn ($q) => $q->where('is_active', true)->whereNotNull('published_at'))
530:             ->where('is_active', true)
531:             ->where(function ($q) use ($query): void {
532:                 $q->where('barcode', $query)
533:                     ->orWhere('sku', $query)
534:                     ->orWhereHas('product', fn ($pq) => $pq->whereRaw('LOWER(name_ar) LIKE ? OR LOWER(name_en) LIKE ?', ['%'.mb_strtolower($query).'%', '%'.mb_strtolower($query).'%']));
535:             })
536:             ->limit(20)
537:             ->get();
538: 
539:         $result = [];
540:         foreach ($variants as $variant) {
541:             $stock = StockLevel::query()
542:                 ->where('product_variant_id', $variant->id)
543:                 ->where('branch_id', $branchId)
544:                 ->selectRaw('SUM(on_hand) AS on_hand, SUM(available) AS available')
545:                 ->first();
546: 
547:             try {
548:                 $priceData = $this->pricing->resolve($variant, $customer, 1, $branchId);
549:             } catch (\Throwable) {
550:                 $priceData = ['unit_price' => null, 'source' => 'unpriced', 'price_list_id' => null];
551:             }
552: 
553:             $result[] = [
554:                 'id' => $variant->id,
555:                 'sku' => $variant->sku,
556:                 'barcode' => $variant->barcode,
557:                 'product_name' => $variant->product->name_ar ?? $variant->product->name_en,
558:                 'variant_name' => $variant->color_name_ar ?? $variant->color_name_en,
559:                 'on_hand' => (float) ($stock?->on_hand ?? 0),
560:                 'available' => (float) ($stock?->available ?? 0),
561:                 'unit_price' => $priceData['unit_price'],
562:                 'price_source' => $priceData['source'],
563:                 'price_list_id' => $priceData['price_list_id'],
564:             ];
565:         }
566: 
567:         return $result;
568:     }
