570:     // ===================================================================
571:     //  المساعدات الداخلية
572:     // ===================================================================
573: 
574:     /**
575:      * تجهيز عناصر الفاتورة مع حل الأسعار.
576:      *
577:      * @param  array<array{product_variant_id: int, qty: int, unit_price?: float|null, discount_amount?: float}>  $rawItems
578:      * @return Collection<int, array<string, mixed>>
579:      */
580:     private function resolveItems(
581:         PosShift $shift,
582:         array $rawItems,
583:         ?Customer $customer,
584:         bool $overridePrice
585:     ): Collection {
586:         return collect($rawItems)->map(function (array $item) use ($shift, $customer, $overridePrice): array {
587:             if (! is_numeric($item['qty']) || (int) $item['qty'] != $item['qty'] || $item['qty'] < 1) {
588:                 throw new BusinessException('الكمية يجب أن تكون عددًا صحيحًا موجبًا.');
589:             }
590:             /** @var ProductVariant $variant */
591:             $variant = ProductVariant::query()
592:                 ->where('id', $item['product_variant_id'])
593:                 ->where('is_active', true)
594:                 ->firstOrFail();
595: 
596:             // التحقق من المخزون المتاح في الفرع
597:             $stock = StockLevel::query()
598:                 ->where('product_variant_id', $variant->id)
599:                 ->where('branch_id', $shift->branch_id)
600:                 ->selectRaw('SUM(on_hand) AS on_hand, SUM(available) AS available')
601:                 ->first();
602: 
603:             $available = (float) ($stock?->available ?? 0);
604: 
605:             if ($available < $item['qty']) {
606:                 throw new BusinessException(
607:                     "الكمية المتاحة للصنف [{$variant->sku}] في الفرع هي {$available} فقط.",
608:                     status: 422,
609:                 );
610:             }
611: 
612:             // السعر: يدوي (بشرط الصلاحية) أو محسوب
613:             if ($overridePrice && isset($item['unit_price'])) {
614:                 $unitPrice = (float) $item['unit_price'];
615:             } else {
616:                 $priceData = $this->pricing->resolve($variant, $customer, (float) $item['qty'], $shift->branch_id);
617:                 $unitPrice = (float) $priceData['unit_price'];
618:             }
619: 
620:             $discount = (float) ($item['discount_amount'] ?? 0);
621:             if (($overridePrice || $discount > 0) && ! $shift->cashier->can('pos.override_price')) {
622:                 throw new AuthorizationException('لا تملك صلاحية تعديل السعر أو الخصم.');
623:             }
624:             $lineTotal = round($unitPrice * $item['qty'] - $discount, 2);
625: 
626:             if ($lineTotal < 0) {
627:                 throw new BusinessException("إجمالي السطر للصنف [{$variant->sku}] لا يمكن أن يكون سالبًا.");
628:             }
629: 
630:             return [
631:                 'product_variant_id' => $variant->id,
632:                 'product_name_snapshot' => $variant->product->name_ar ?? $variant->product->name_en ?? 'POS Item',
633:                 'sku_snapshot' => $variant->sku,
634:                 'qty' => $item['qty'],
635:                 'unit_price' => $unitPrice,
636:                 'discount_amount' => $discount,
637:                 'line_total' => $lineTotal,
638:             ];
639:         });
640:     }
