642:     /**
643:      * تسجيل مصروف من درج الوردية الحالية.
644:      */
645:     public function recordExpense(PosShift $shift, array $data, int $userId): Expense
646:     {
647:         if ($shift->status !== PosShiftStatus::Open) {
648:             throw new BusinessException('الوردية غير مفتوحة — لا يمكن تسجيل مصاريف.');
649:         }
650: 
651:         return DB::transaction(function () use ($shift, $data, $userId): Expense {
652:             $shift = $this->lockedOpenShift($shift);
653:             $expenseNumber = $this->settings->generateNextNumber('expense');
654: 
655:             $expense = Expense::create([
656:                 'expense_number' => $expenseNumber,
657:                 'branch_id' => $shift->branch_id,
658:                 'treasury_id' => $shift->treasury_id,
659:                 'shift_id' => $shift->id,
660:                 'category' => $data['category'],
661:                 'amount' => $data['amount'],
662:                 'expense_date' => $data['expense_date'] ?? today(),
663:                 'attachment_path' => $data['attachment_path'] ?? null,
664:                 'notes' => $data['notes'] ?? null,
665:                 'created_by' => $userId,
666:             ]);
667: 
668:             // خصم من الخزينة
669:             $this->treasury->record([
670:                 'treasury_id' => $shift->treasury_id,
671:                 'shift_id' => $shift->id,
672:                 'type' => TreasuryTransactionType::Expense,
673:                 'amount' => -(float) $data['amount'],
674:                 'reference_type' => Expense::class,
675:                 'reference_id' => $expense->id,
676:                 'created_by' => $userId,
677:                 'notes' => "مصروف: {$data['category']} #{$expenseNumber}",
678:             ]);
679: 
680:             $shift->increment('cash_expenses_total', $data['amount']);
681: 
682:             return $expense;
683:         });
684:     }
