686:     private function consumeStock(PosShift $shift, Order $order, array $item): void
687:     {
688:         $levels = StockLevel::query()->where('product_variant_id', $item['product_variant_id'])
689:             ->where('branch_id', $shift->branch_id)->where('available', '>', 0)->orderBy('id')->lockForUpdate()->get();
690:         $remaining = (float) $item['qty'];
691:         foreach ($levels as $level) {
692:             $qty = min($remaining, (float) $level->available);
693:             if ($qty <= 0) {
694:                 continue;
695:             }
696:             $this->inventory->recordMovement([
697:                 'product_variant_id' => $item['product_variant_id'], 'branch_id' => $shift->branch_id,
698:                 'location_id' => $level->location_id, 'type' => StockMovementType::Sale,
699:                 'affected_bucket' => StockBucket::OnHand, 'quantity' => -$qty,
700:                 'reference_type' => Order::class, 'reference_id' => $order->id, 'created_by' => $shift->user_id,
701:                 'notes' => 'بيع POS #'.$order->order_number,
702:             ], $level);
703:             $remaining = round($remaining - $qty, 4);
704:             if ($remaining <= 0) {
705:                 break;
706:             }
707:         }
708:         if ($remaining > 0) {
709:             throw new BusinessException('المخزون المتاح في الفرع لم يعد كافيًا لإتمام البيع.');
710:         }
711:     }
712: 
713:     private function lockedOpenShift(PosShift $shift): PosShift
714:     {
715:         $shift = PosShift::query()->lockForUpdate()->findOrFail($shift->id);
716:         if ($shift->status !== PosShiftStatus::Open) {
717:             throw new BusinessException('الوردية مغلقة.');
718:         }
719: 
720:         return $shift;
721:     }
