 17: 
 18: /**
 19:  * خدمة الخزائن — المدخل الوحيد لأي حركة مالية في الخزائن.
 20:  * قاعدة صارمة: ممنوع تعديل current_balance مباشرة من أي مكان آخر.
 21:  * كل قبض أو صرف يمر من هنا: يسجل حركة في treasury_transactions أولًا،
 22:  * ثم يحدث الرصيد — داخل نفس الـ transaction ومع قفل الصف.
 23:  */
 24: class TreasuryService
 25: {
 26:     public function __construct(private readonly SettingService $settings) {}
 27: 
 28:     /**
 29:      * تسجيل حركة مالية في خزينة مع قفل الصف وتحديث الرصيد.
 30:      *
 31:      * @param  array{
 32:      *     treasury_id: int,
 33:      *     shift_id?: int|null,
 34:      *     type: TreasuryTransactionType,
 35:      *     amount: float|string,
 36:      *     reference_type?: string|null,
 37:      *     reference_id?: int|null,
 38:      *     created_by: int,
 39:      *     notes?: string|null,
 40:      * }  $data
 41:      */
 42:     public function record(array $data): TreasuryTransaction
 43:     {
 44:         return DB::transaction(function () use ($data): TreasuryTransaction {
 45:             /** @var Treasury $treasury */
 46:             $treasury = Treasury::query()->lockForUpdate()->findOrFail($data['treasury_id']);
 47: 
 48:             if (! $treasury->is_active) {
 49:                 throw new BusinessException('الخزينة غير نشطة.');
 50:             }
 51: 
 52:             $amount = (float) (string) BigDecimal::of((string) $data['amount'])->toScale(2, RoundingMode::HalfUp);
 53:             $balanceAfter = round((float) $treasury->current_balance + $amount, 2);
 54: 
 55:             // منع الرصيد السالب على أدراج نقطة البيع والخزائن الرئيسية
 56:             if ($balanceAfter < 0 && in_array($treasury->type->value, ['main_safe', 'pos_drawer'], true)) {
 57:                 throw new BusinessException('رصيد الخزينة غير كافٍ لإتمام العملية.');
 58:             }
 59: 
 60:             $transaction = TreasuryTransaction::create([
 61:                 'treasury_id' => $treasury->id,
 62:                 'shift_id' => $data['shift_id'] ?? null,
 63:                 'type' => $data['type'],
 64:                 'amount' => $amount,
 65:                 'balance_after' => $balanceAfter,
 66:                 'reference_type' => $data['reference_type'] ?? null,
 67:                 'reference_id' => $data['reference_id'] ?? null,
 68:                 'created_by' => $data['created_by'],
 69:                 'notes' => $data['notes'] ?? null,
 70:                 'created_at' => now(),
 71:             ]);
 72: 
 73:             $treasury->current_balance = $balanceAfter;
 74:             $treasury->save();
 75: 
 76:             return $transaction;
 77:         });
 78:     }
 79: 
 80:     /**
 81:      * تحويل مبلغ من خزينة إلى خزينة أخرى بعد الاعتماد.
 82:      */
 83:     public function approveTransfer(TreasuryTransfer $transfer, int $approverId): TreasuryTransfer
 84:     {
 85:         if ($transfer->status !== TreasuryTransferStatus::Pending) {
 86:             throw new BusinessException('يمكن اعتماد التحويلات المعلقة فقط.');
 87:         }
 88: 
 89:         return DB::transaction(function () use ($transfer, $approverId): TreasuryTransfer {
 90:             $transfer = TreasuryTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
 91:             if ($transfer->status !== TreasuryTransferStatus::Pending) {
 92:                 throw new BusinessException('التحويل ليس معلقًا.');
 93:             }
 94:             Treasury::query()->whereIn('id', [$transfer->from_treasury_id, $transfer->to_treasury_id])->orderBy('id')->lockForUpdate()->get();
 95:             if (PosShift::whereIn('treasury_id', [$transfer->from_treasury_id, $transfer->to_treasury_id])
 96:                 ->whereIn('status', ['open', 'closed_pending_approval'])->exists()) {
 97:                 throw new BusinessException('لا يمكن تحويل نقدية درج مرتبط بوردية لم تتم تسويتها.');
 98:             }
 99:             // خصم من المصدر
100:             $this->record([
101:                 'treasury_id' => $transfer->from_treasury_id,
102:                 'type' => TreasuryTransactionType::TransferOut,
103:                 'amount' => -abs((float) $transfer->amount),
104:                 'reference_type' => TreasuryTransfer::class,
105:                 'reference_id' => $transfer->id,
106:                 'created_by' => $approverId,
107:                 'notes' => "تحويل #{$transfer->transfer_number} صادر",
108:             ]);
109: 
110:             // إضافة إلى الوجهة
111:             $this->record([
112:                 'treasury_id' => $transfer->to_treasury_id,
113:                 'type' => TreasuryTransactionType::TransferIn,
114:                 'amount' => abs((float) $transfer->amount),
115:                 'reference_type' => TreasuryTransfer::class,
116:                 'reference_id' => $transfer->id,
117:                 'created_by' => $approverId,
118:                 'notes' => "تحويل #{$transfer->transfer_number} وارد",
119:             ]);
120: 
121:             $transfer->update([
122:                 'status' => TreasuryTransferStatus::Approved,
123:                 'approved_by' => $approverId,
124:             ]);
125: 
126:             return $transfer->fresh();
127:         });
128:     }
