130:     /**
131:      * ترحيل نقدية الوردية المعتمدة إلى الخزنة الرئيسية للفرع.
132:      */
133:     public function settleShiftToMainSafe(PosShift $shift, int $approverId): void
134:     {
135:         // الخزنة الرئيسية للفرع
136:         $mainSafe = Treasury::query()
137:             ->where('branch_id', $shift->branch_id)
138:             ->where('type', 'main_safe')
139:             ->where('is_active', true)
140:             ->first();
141: 
142:         if ($mainSafe === null) {
143:             throw new BusinessException('يجب إنشاء خزنة رئيسية نشطة للفرع قبل اعتماد الوردية.');
144:         }
145: 
146:         // الرصيد الفعلي الحالي في الدرج
147:         $drawer = Treasury::query()->lockForUpdate()->findOrFail($shift->treasury_id);
148:         $drawerBalance = (float) $drawer->current_balance;
149: 
150:         // المبلغ المطلوب ترحيله هو المبلغ الفعلي المعدود، ولكن لا يتجاوز رصيد الدرج المتاح
151:         $requestedAmount = (float) ($shift->actual_closing_cash ?? $shift->expected_closing_cash);
152:         $amount = $requestedAmount;
153:         $variance = round($amount - $drawerBalance, 2);
154:         if ($variance != 0) {
155:             $this->record([
156:                 'treasury_id' => $drawer->id, 'shift_id' => $shift->id,
157:                 'type' => $variance < 0 ? TreasuryTransactionType::Expense : TreasuryTransactionType::CustomerReceipt,
158:                 'amount' => $variance, 'reference_type' => PosShift::class, 'reference_id' => $shift->id,
159:                 'created_by' => $approverId, 'notes' => 'تسوية عجز أو زيادة الوردية '.$shift->shift_number,
160:             ]);
161:         }
162: 
163:         if ($amount <= 0) {
164:             return;
165:         }
166: 
167:         // خصم من درج الكاشير
168:         $this->record([
169:             'treasury_id' => $shift->treasury_id,
170:             'type' => TreasuryTransactionType::TransferOut,
171:             'amount' => -$amount,
172:             'reference_type' => PosShift::class,
173:             'reference_id' => $shift->id,
174:             'created_by' => $approverId,
175:             'notes' => "ترحيل إغلاق وردية #{$shift->shift_number}",
176:         ]);
177: 
178:         // إضافة للخزنة الرئيسية
179:         $this->record([
180:             'treasury_id' => $mainSafe->id,
181:             'type' => TreasuryTransactionType::TransferIn,
182:             'amount' => $amount,
183:             'reference_type' => PosShift::class,
184:             'reference_id' => $shift->id,
185:             'created_by' => $approverId,
186:             'notes' => "ترحيل إغلاق وردية #{$shift->shift_number}",
187:         ]);
188:     }
