190:     /**
191:      * إنشاء تحويل خزينة جديد (معلق حتى الاعتماد).
192:      */
193:     public function createTransfer(array $data, int $userId): TreasuryTransfer
194:     {
195:         if ((float) $data['amount'] <= 0) {
196:             throw new BusinessException('مبلغ التحويل يجب أن يكون موجبًا.');
197:         }
198:         if ($data['from_treasury_id'] === $data['to_treasury_id']) {
199:             throw new BusinessException('لا يمكن التحويل من خزينة إلى نفسها.');
200:         }
201: 
202:         $number = $this->settings->generateNextNumber('treasury_transfer');
203: 
204:         return TreasuryTransfer::create([
205:             'transfer_number' => $number,
206:             'from_treasury_id' => $data['from_treasury_id'],
207:             'to_treasury_id' => $data['to_treasury_id'],
208:             'amount' => $data['amount'],
209:             'status' => TreasuryTransferStatus::Pending,
210:             'created_by' => $userId,
211:             'notes' => $data['notes'] ?? null,
212:         ]);
213:     }
