  5: namespace App\Services;
  6: 
  7: use App\Enums\OrderStatus;
  8: use App\Enums\RefundMethod;
  9: use App\Enums\ReturnStatus;
 10: use App\Enums\StockBucket;
 11: use App\Enums\StockMovementType;
 12: use App\Exceptions\BusinessException;
 13: use App\Models\Branch;
 14: use App\Models\Customer;
 15: use App\Models\Order;
 16: use App\Models\OrderItem;
 17: use App\Models\Product;
 18: use App\Models\ReturnRequest;
 19: use App\Models\ReturnRequestItem;
 20: use App\Models\User;
 21: use Illuminate\Http\UploadedFile;
 22: use Illuminate\Support\Facades\DB;
 23: use Illuminate\Support\Facades\Storage;
 24: 
 25: /**
 26:  * خدمة المرتجعات (RMA) — دورة حياة طلب الإرجاع في أربع خطوات:
 27:  * create ← تقديم الطلب (تحقق من التسليم ونافذة الاسترجاع وسقف الكميات)،
 28:  * approve ← موافقة مبدئية (فرع مستلم وكميات معتمدة)،
 29:  * receive ← استلام وفحص فعلي، refund ← رد مالي للعميل.
 30:  *
 31:  * القاعدة الذهبية: الإنشاء والاعتماد لا يضيفان أي رصيد للمخزون. الإضافة
 32:  * الفعلية تتم حصريًا في receive عبر InventoryService::recordMovement:
 33:  * السليم يعود إلى on_hand بحركة sale_return، والتالف يُسجل في وعاء
 34:  * damaged بحركة damage (بعد عودته فيزيائيًا إلى on_hand بنفس الكمية،
 35:  * لأن وعاء التالف شريحة من الرصيد الفعلي لا رصيد مستقل).
 36:  */
 37: class ReturnService
 38: {
 39:     public function __construct(
 40:         protected SettingService $settings,
 41:         protected InventoryService $inventory,
 42:         protected OrderService $orders,
 43:     ) {}
 44: 
 45:     /**
 46:      * تقديم طلب إرجاع لطلب مُسلَّم داخل نافذة الاسترجاع.
 47:      * $customer عند الإنشاء من المتجر (يفرض ملكية الطلب)؛ null عند إنشاء
 48:      * الأدمن اليدوي لطلب أي عميل/زائر.
 49:      *
 50:      * @param  array{reason: string, refund_method?: string|null, items: list<array{order_item_id: int, requested_qty: float|int|string, item_reason?: string|null, attachments?: list<UploadedFile>}>}  $data
 51:      */
 52:     public function createReturnRequest(Order $order, array $data, ?Customer $customer = null): ReturnRequest
 53:     {
 54:         $return = PrivateAttachments::transaction(function (PrivateAttachments $files) use ($order, $data, $customer): ReturnRequest {
 55:             // قفل صف الطلب: طلبا إرجاع متزامنان لنفس البند لا يتجاوزا سقفه معًا
 56:             $order = Order::query()->lockForUpdate()->findOrFail($order->id);
 57:             if ($order->channel === 'pos') {
 58:                 throw new BusinessException('استخدم مرتجعات نقطة البيع من وردية مفتوحة لهذه الفاتورة.');
 59:             }
 60: 
 61:             if ($customer !== null && (int) $order->customer_id !== (int) $customer->id) {
 62:                 throw new BusinessException('هذا الطلب لا يخص حسابك.', [], 403);
 63:             }
 64: 
 65:             if ($order->status !== OrderStatus::Delivered) {
 66:                 throw new BusinessException('لا يمكن إنشاء طلب إرجاع إلا لطلب تم تسليمه فعليًا.');
 67:             }
 68: 
 69:             $this->assertWithinReturnWindow($order);
 70: 
 71:             // تجميع البنود المكررة لنفس سطر الطلب قبل فحص السقف
 72:             $lines = [];
 73:             foreach ($data['items'] as $line) {
 74:                 DiscreteQuantity::assert($line['requested_qty']);
 75:                 $orderItemId = (int) $line['order_item_id'];
 76:                 $lines[$orderItemId] ??= ['qty' => 0.0, 'reason' => null, 'files' => []];
 77:                 $lines[$orderItemId]['qty'] += (float) $line['requested_qty'];
 78:                 $lines[$orderItemId]['reason'] = $line['item_reason'] ?? $lines[$orderItemId]['reason'];
 79:                 $lines[$orderItemId]['files'] = array_merge($lines[$orderItemId]['files'], $line['attachments'] ?? []);
 80:             }
 81: 
 82:             $orderItems = $order->items()->whereIn('id', array_keys($lines))->get()->keyBy('id');
 83:             if ($orderItems->count() !== count($lines)) {
 84:                 throw new BusinessException('أحد البنود المطلوب إرجاعها لا يتبع هذا الطلب.');
 85:             }
 86: 
 87:             foreach ($lines as $orderItemId => $line) {
 88:                 $orderItem = $orderItems->get($orderItemId);
 89:                 // ما سبق طلبه للإرجاع في طلبات قائمة (غير المرفوض/الملغي)
 90:                 // يحجز من سقف البند حتى لا يُرجع أكثر مما اشتراه العميل
 91:                 $previouslyRequested = (float) ReturnRequestItem::query()
 92:                     ->where('order_item_id', $orderItemId)
 93:                     ->join('return_requests', 'return_requests.id', '=', 'return_request_items.return_request_id')
 94:                     ->whereNotIn('return_requests.status', [ReturnStatus::Rejected->value, ReturnStatus::Cancelled->value])
 95:                     ->selectRaw("COALESCE(SUM(CASE WHEN return_requests.status IN ('received', 'refunded') THEN received_good_qty + received_damaged_qty WHEN return_requests.status = 'approved' THEN approved_qty ELSE requested_qty END), 0) as total")
 96:                     ->value('total');
 97:                 if (round($previouslyRequested + $line['qty'], 4) > round((float) $orderItem->qty, 4)) {
 98:                     throw new BusinessException("كمية الإرجاع للصنف ({$orderItem->sku_snapshot}) تتجاوز الكمية المشتراة بعد احتساب مرتجعات سابقة.");
 99:                 }
100:             }
101: 
102:             $return = ReturnRequest::create([
103:                 'return_number' => $this->settings->generateNextNumber('return'),
104:                 'order_id' => $order->id,
105:                 'customer_id' => $order->customer_id,
106:                 'status' => ReturnStatus::Pending,
107:                 'refund_method' => $data['refund_method'] ?? null,
108:                 'total_refund_amount' => 0,
109:                 'reason' => $data['reason'],
110:             ]);
111: 
112:             foreach ($lines as $orderItemId => $line) {
113:                 $orderItem = $orderItems->get($orderItemId);
114:                 $return->items()->create([
115:                     'order_item_id' => $orderItem->id,
116:                     'product_variant_id' => $orderItem->product_variant_id,
117:                     'requested_qty' => $line['qty'],
118:                     'unit_refund_price' => $this->netUnitRefundPrice($orderItem),
119:                     'item_reason' => $line['reason'],
120:                 ]);
121:             }
122: 
123:             $this->storeAttachments($return, $data['items'], $files);
124: 
125:             return $return;
126:         });
127: 
128:         return $return->fresh(['items']);
129:     }
130: 
131:     /**
132:      * الموافقة المبدئية: تحديد الفرع المستلم والكميات المعتمدة لكل بند.
133:      * لا تلمس المخزون بأي شكل — الاستلام الفعلي لاحقًا هو ما يحرّكه.
134:      *
135:      * @param  array{branch_id: int, admin_notes?: string|null, items?: list<array{id: int, approved_qty: float|int|string}>}  $data
136:      */
137:     public function approve(ReturnRequest $return, User $admin, array $data): ReturnRequest
138:     {
139:         return DB::transaction(function () use ($return, $admin, $data): ReturnRequest {
140:             Order::query()->lockForUpdate()->findOrFail($return->order_id);
141:             $return = ReturnRequest::query()->lockForUpdate()->findOrFail($return->id);
142:             if ($return->status !== ReturnStatus::Pending) {
143:                 throw new BusinessException('لا يمكن اعتماد طلب مرتجع إلا وهو قيد المراجعة.');
144:             }
145: 
146:             if (! Branch::query()->whereKey($data['branch_id'])->where('is_active', true)->exists()) {
147:                 throw new BusinessException('فرع الاستلام غير نشط.');
148:             }
149:             $return->load(['items.orderItem', 'items.variant.product']);
150:             $approved = collect($data['items'] ?? [])->keyBy(fn (array $line): int => (int) $line['id']);
151:             foreach ($approved->keys() as $itemId) {
152:                 if (! $return->items->contains('id', $itemId)) {
153:                     throw new BusinessException('أحد البنود المعتمدة لا يتبع طلب المرتجع هذا.');
154:                 }
155:             }
156: 
157:             $totalApproved = 0.0;
158:             foreach ($return->items as $item) {
159:                 // بند غير مذكور في الحمولة يُعتمد بكامل كميته المطلوبة
160:                 $qty = $approved->has($item->id)
161:                     ? (float) $approved->get($item->id)['approved_qty']
162:                     : (float) $item->requested_qty;
163:                 DiscreteQuantity::assert($qty, true);
164:                 if ($qty < 0 || round($qty, 4) > round((float) $item->requested_qty, 4)) {
165:                     throw new BusinessException("الكمية المعتمدة للصنف ({$item->orderItem?->sku_snapshot}) يجب أن تكون بين صفر والمطلوب.");
166:                 }
167:                 $item->update(['approved_qty' => $qty]);
168:                 $totalApproved += $qty;
169:             }
170:             if ($totalApproved <= 0) {
171:                 throw new BusinessException('لا توجد كميات معتمدة؛ ارفض الطلب بدلًا من اعتماده إن لم يُقبل أي بند.');
172:             }
173: 
174:             $return->update([
175:                 'branch_id' => (int) $data['branch_id'],
176:                 'status' => ReturnStatus::Approved,
177:                 'approved_by' => $admin->id,
178:                 'approved_at' => now(),
179:                 'admin_notes' => $data['admin_notes'] ?? $return->admin_notes,
180:             ]);
181: 
182:             return $return->fresh(['items']);
183:         });
184:     }
185: 
186:     /**
187:      * الاستلام والفحص المخزني — الخطوة الوحيدة التي تحرّك المخزون:
188:      * السليم sale_return إلى on_hand، والتالف damage إلى وعاء damaged،
189:      * داخل معاملة واحدة عبر InventoryService حصرًا.
190:      *
191:      * @param  array{items: list<array{id: int, received_good_qty: float|int|string, received_damaged_qty: float|int|string}>}  $data
192:      */
193:     public function receive(ReturnRequest $return, User $admin, array $data): ReturnRequest
194:     {
195:         return DB::transaction(function () use ($return, $admin, $data): ReturnRequest {
196:             Order::query()->lockForUpdate()->findOrFail($return->order_id);
197:             $return = ReturnRequest::query()->lockForUpdate()->findOrFail($return->id);
198:             if ($return->status !== ReturnStatus::Approved) {
199:                 throw new BusinessException('لا يمكن استلام مرتجع إلا بعد الموافقة المبدئية عليه.');
200:             }
201:             if ($return->branch_id === null) {
202:                 throw new BusinessException('لم يُحدد فرع الاستلام عند اعتماد هذا المرتجع.');
203:             }
204:             if (! Branch::query()->whereKey($return->branch_id)->where('is_active', true)->exists()) {
205:                 throw new BusinessException('فرع الاستلام غير نشط.');
206:             }
207: 
208:             $return->load(['items.orderItem', 'items.variant.product']);
209:             $lines = collect($data['items'])->keyBy(fn (array $line): int => (int) $line['id']);
210:             foreach ($lines->keys() as $itemId) {
211:                 if (! $return->items->contains('id', $itemId)) {
212:                     throw new BusinessException('أحد البنود المستلمة لا يتبع طلب المرتجع هذا.');
213:                 }
214:             }
215:             foreach ($return->items as $item) {
216:                 if (! $lines->has($item->id)) {
217:                     throw new BusinessException('بيانات الاستلام يجب أن تغطي كل بنود المرتجع (بند بلا استلام فعلي يُرسل بصفر).');
218:                 }
219:             }
220: 
221:             // تجميعات المرتجعات السابقة (مستلمة/مردودة) لكل بنود الطلب في
222:             // استعلام واحد مجمّع بدل استعلام لكل بند داخل الحلقة (L5). بنود
223:             // هذا المرتجع نفسه مستبعدة ضمنيًا لأن حالته ما زالت Approved.
224:             $previousByOrderItem = ReturnRequestItem::query()
225:                 ->whereIn('order_item_id', $return->items->pluck('order_item_id')->all())
226:                 ->whereHas('returnRequest', fn ($q) => $q->whereIn('status', [ReturnStatus::Received, ReturnStatus::Refunded]))
227:                 ->selectRaw('order_item_id, COALESCE(SUM(received_good_qty + received_damaged_qty), 0) as qty, COALESCE(SUM(refund_amount), 0) as refunded')
228:                 ->groupBy('order_item_id')
229:                 ->get()
230:                 ->keyBy('order_item_id');
231: 
232:             $refundTotal = 0.0;
233:             foreach ($return->items as $item) {
234:                 $line = $lines->get($item->id);
235:                 DiscreteQuantity::assert($line['received_good_qty'], true);
236:                 DiscreteQuantity::assert($line['received_damaged_qty'], true);
237:                 $good = (float) $line['received_good_qty'];
238:                 $damaged = (float) $line['received_damaged_qty'];
239:                 if (round($good + $damaged, 4) > round((float) $item->approved_qty, 4)) {
240:                     throw new BusinessException("المستلم للصنف ({$item->orderItem?->sku_snapshot}) يتجاوز الكمية المعتمدة.");
241:                 }
242: 
243:                 $base = [
244:                     'product_variant_id' => $item->product_variant_id,
245:                     'branch_id' => (int) $return->branch_id,
246:                     'location_id' => null,
247:                     'reference_type' => ReturnRequest::class,
248:                     'reference_id' => $return->id,
249:                     'created_by' => $admin->id,
250:                 ];
251:                 if ($good > 0) {
252:                     $this->inventory->recordMovement([...$base,
253:                         'type' => StockMovementType::SaleReturn,
254:                         'affected_bucket' => StockBucket::OnHand,
255:                         'quantity' => $good,
256:                         'notes' => "مرتجع سليم — طلب {$return->return_number}",
257:                     ]);
258:                 }
259:                 if ($damaged > 0) {
260:                     // القطعة التالفة عادت فيزيائيًا للمخزن فتدخل on_hand أولًا،
261:                     // ثم تُحجز في وعاء التالف — المتاح للبيع لا يزيد بها
262:                     $this->inventory->recordMovement([...$base,
263:                         'type' => StockMovementType::SaleReturn,
264:                         'affected_bucket' => StockBucket::OnHand,
265:                         'quantity' => $damaged,
266:                         'notes' => "مرتجع تالف (عودة فيزيائية) — طلب {$return->return_number}",
267:                     ]);
268:                     $this->inventory->recordMovement([...$base,
269:                         'type' => StockMovementType::Damage,
270:                         'affected_bucket' => StockBucket::Damaged,
271:                         'quantity' => $damaged,
272:                         'notes' => "مرتجع تالف بعد الفحص — طلب {$return->return_number}",
273:                     ]);
274:                 }
275: 
276:                 $receivedTotal = $good + $damaged;
277:                 if ($receivedTotal > 0 && $item->variant?->product_id) {
278:                     Product::query()->whereKey($item->variant->product_id)
279:                         ->update(['sales_count' => DB::raw('GREATEST(sales_count - '.(int) round($receivedTotal).', 0)')]);
280:                 }
281: 
282:                 $previous = $previousByOrderItem->get($item->order_item_id);
283:                 $previousQty = (float) ($previous->qty ?? 0);
284:                 $previousRefunded = (float) ($previous->refunded ?? 0);
285:                 $orderItem = $item->orderItem;
286:                 $netCents = $this->netLineRefundCents($orderItem);
287:                 $cumulativeQty = $previousQty + $receivedTotal;
288:                 $targetCents = $cumulativeQty >= (float) $orderItem->qty
289:                     ? $netCents
290:                     : min($netCents, (int) round($cumulativeQty * (float) $item->unit_refund_price * 100));
291:                 $refundAmount = max(0, $targetCents - (int) round($previousRefunded * 100)) / 100;
292:                 $item->update([
293:                     'refund_amount' => $refundAmount,
294:                     'received_good_qty' => $good,
295:                     'received_damaged_qty' => $damaged,
296:                 ]);
297:                 $refundTotal += $refundAmount;
298:             }
299: 
300:             $return->update([
301:                 'total_refund_amount' => round($refundTotal, 2),
302:                 'status' => ReturnStatus::Received,
303:                 'received_by' => $admin->id,
304:                 'received_at' => now(),
305:             ]);
306: 
307:             return $return->fresh(['items']);
308:         });
309:     }
310: 
311:     /**
312:      * رد المبلغ للعميل بعد الاستلام: محفظة (تُضاف لرصيد العميل) أو تسجيل
313:      * مرجع تحويل/بوابة. اكتمال إرجاع كل بنود الطلب ينقل الطلب نفسه إلى
314:      * Returned عبر بوابة الحالة بلا آثار مخزون/استرداد مكررة.
315:      *
316:      * @param  array{refund_method?: string|null, refund_reference?: string|null}  $data
317:      */
318:     public function refund(ReturnRequest $return, User $admin, array $data): ReturnRequest
319:     {
320:         return DB::transaction(function () use ($return, $admin, $data): ReturnRequest {
321:             $order = Order::query()->lockForUpdate()->findOrFail($return->order_id);
322:             if ($order->channel === 'pos') {
323:                 throw new BusinessException('مرتجع نقطة البيع النقدي يتطلب وردية مفتوحة.');
324:             }
325:             $return = ReturnRequest::query()->lockForUpdate()->findOrFail($return->id);
326:             if ($return->status !== ReturnStatus::Received) {
327:                 throw new BusinessException('لا يمكن رد مبلغ مرتجع إلا بعد استلامه وفحصه.');
328:             }
329: 
330:             $method = $data['refund_method'] ?? $return->refund_method?->value;
331:             if ($order->payment_method === 'credit') {
332:                 $method ??= RefundMethod::OriginalPayment->value;
333:                 if ($method !== RefundMethod::OriginalPayment->value) {
334:                     throw new BusinessException('الفاتورة الآجلة غير المدفوعة ترد إلى المديونية فقط.');
335:                 }
336:                 if (! DB::table('customer_credit_transactions')->where('order_id', $order->id)->where('type', 'purchase')->exists()) {
337:                     throw new BusinessException('الفاتورة الآجلة غير مسجلة في دفتر المديونية؛ راجع الحساب أولًا.');
338:                 }
339:             }
340:             if ($method === null) {
341:                 throw new BusinessException('حدد طريقة رد المبلغ قبل إتمام الاسترداد.');
342:             }
343:             $reference = $data['refund_reference'] ?? $return->refund_reference;
344:             if ($order->payment_method === 'credit') {
345:                 $reference ??= 'CREDIT-RETURN-'.$return->id;
346:             }
347:             if (in_array($method, [RefundMethod::OriginalPayment->value, RefundMethod::BankTransfer->value], true)
348:                 && trim((string) $reference) === '') {
349:                 throw new BusinessException('مرجع التحويل أو بوابة الدفع مطلوب لإتمام الاسترداد.');
350:             }
351: 
352:             if ($order->payment_method === 'credit') {
353:                 if ($method !== RefundMethod::OriginalPayment->value) {
354:                     throw new BusinessException('مرتجع الفاتورة الآجلة يرد إلى حساب المديونية.');
355:                 }
356:                 app(WholesaleService::class)->reverseCredit($order, $return);
357:             } elseif (! in_array($order->payment_status, ['paid', 'partially_refunded', 'refunded'], true)) {
358:                 throw new BusinessException('لا يمكن رد مبلغ نقدي أو إلى المحفظة لطلب غير مدفوع. يُقيَّد المرتجع كتخفيض للمستحق حتى يُبنى مسار إشعار دائن.');
359:             }
360:             if ($order->payment_method === 'wallet' && $method !== RefundMethod::Wallet->value) {
361:                 throw new BusinessException('طلب مدفوع بالمحفظة يُرد إلى المحفظة فقط.');
362:             }
363:             $reference = $reference !== null ? trim((string) $reference) : $reference;
364:             if ($reference !== null && $reference !== '' && ReturnRequest::query()
365:                 ->where('id', '!=', $return->id)
366:                 ->whereNotIn('status', [ReturnStatus::Rejected, ReturnStatus::Cancelled])
367:                 ->whereRaw('lower(btrim(refund_reference)) = ?', [mb_strtolower($reference)])
368:                 ->exists()) {
369:                 throw new BusinessException('مرجع الرد مسجّل سابقًا.', [], 409);
370:             }
371: 
372:             if ($method === RefundMethod::Wallet->value) {
373:                 if ($return->customer_id === null) {
374:                     throw new BusinessException('الاسترداد إلى المحفظة يتطلب حساب عميل مسجل؛ اختر طريقة أخرى لطلبات الزوار.');
375:                 }
376:                 app(WalletService::class)->record($return->customer_id, (float) $return->total_refund_amount,
377:                     'return_refund', 'return_request', $return->id, $admin->id);
378:             }
379: 
380:             $return->update([
381:                 'refund_method' => $method,
382:                 'refund_reference' => $reference,
383:                 'status' => ReturnStatus::Refunded,
384:                 'refunded_by' => $admin->id,
385:                 'refunded_at' => now(),
386:             ]);
387: 
388:             $this->syncOrderPaymentStatusAfterRefund($order);
389:             if ($this->isOrderFullyReturned($order)) {
390:                 $this->orders->changeStatus(
391:                     $order,
392:                     OrderStatus::Returned,
393:                     $admin,
394:                     "إرجاع كامل لبنود الطلب عبر طلب المرتجع {$return->return_number}",
395:                     null,
396:                     false,
397:                 );
398:             }
399: 
400:             return $return->fresh(['items']);
401:         });
402:     }
