407:             $return = ReturnRequest::query()->lockForUpdate()->findOrFail($return->id);
408:             if ($return->status !== ReturnStatus::Pending) {
409:                 throw new BusinessException('يمكن حذف المرتجعات قيد المراجعة فقط؛ استخدم الإلغاء للحالات الأخرى.');
