454:     /**
455:      * تعديلات إدارية بلا آثار جانبية: ملاحظات وطريقة رد (قبل اكتمال الرد)،
456:      * وتوجيه حالتي rejected/cancelled لمساريهما في الخدمة.
457:      *
458:      * @param  array{admin_notes?: string|null, refund_method?: string|null, status?: string|null}  $data
459:      */
460:     public function updateDetails(ReturnRequest $return, User $admin, array $data): ReturnRequest
461:     {
462:         if (($data['status'] ?? null) === ReturnStatus::Rejected->value) {
463:             return $this->reject($return, $admin, $data['admin_notes'] ?? null);
464:         }
465:         if (($data['status'] ?? null) === ReturnStatus::Cancelled->value) {
466:             return $this->cancel($return, $data['admin_notes'] ?? null);
467:         }
468: 
469:         return DB::transaction(function () use ($return, $data): ReturnRequest {
470:             $return = ReturnRequest::query()->lockForUpdate()->findOrFail($return->id);
471:             if (! in_array($return->status, [ReturnStatus::Pending, ReturnStatus::Approved, ReturnStatus::Received], true)
472:                 && array_key_exists('refund_method', $data)) {
473:                 throw new BusinessException('لا يمكن تغيير طريقة الرد بعد اكتمال الاسترداد.');
474:             }
475: 
476:             $updates = [];
477:             if (array_key_exists('admin_notes', $data)) {
478:                 $updates['admin_notes'] = $data['admin_notes'];
479:             }
480:             if (array_key_exists('refund_method', $data)) {
481:                 $updates['refund_method'] = $data['refund_method'];
482:             }
483:             if ($updates !== []) {
484:                 $return->update($updates);
485:             }
486: 
487:             return $return->fresh(['items']);
488:         });
489:     }
