491:     /**
492:      * نافذة الاسترجاع من الإعدادات (أيام من لحظة انتقال الطلب إلى delivered).
493:      * 0 = الإرجاع متوقف، قيمة سالبة (مثل -1) = بلا حد زمني.
494:      */
495:     private function assertWithinReturnWindow(Order $order): void
496:     {
497:         $windowDays = (int) $this->settings->get('return_window_days', 14);
498:         if ($windowDays === 0) {
499:             throw new BusinessException('الإرجاع متوقف من إعدادات المتجر.');
500:         }
501:         if ($windowDays < 0) {
502:             return;
503:         }
504: 
505:         $deliveredAt = $order->statusHistories()
506:             ->where('to_status', OrderStatus::Delivered->value)
507:             ->latest('id')
508:             ->value('created_at');
509: 
510:         if ($deliveredAt === null) {
511:             throw new BusinessException('لا يوجد سجل تسليم موثوق لحساب فترة الاسترجاع.');
512:         }
513: 
514:         if ($deliveredAt !== null && $deliveredAt->copy()->addDays($windowDays)->isPast()) {
515:             throw new BusinessException("انتهت فترة الاسترجاع المسموحة ({$windowDays} يومًا من التسليم) لهذا الطلب.");
516:         }
517:     }
