519:     /** سعر وحدة الرد الصافي: ما دفعه العميل فعليًا للبند ÷ كميته (بعد خصومات الأسعار وحصة الكوبون والضريبة غير المشمولة). */
520:     private function netUnitRefundPrice(OrderItem $orderItem): float
521:     {
522:         $qty = (float) $orderItem->qty;
523:         if ($qty <= 0) {
524:             return (float) $orderItem->unit_price;
525:         }
526: 
527:         return round($this->netLineRefundCents($orderItem) / 100 / $qty, 4);
528:     }
529: 
530:     /** صافي البند بالسنت: السعر × الكمية − الخصم + ضريبة البند (صفر عندما تكون الأسعار شاملة الضريبة). */
531:     private function netLineRefundCents(OrderItem $orderItem): int
532:     {
533:         $net = (float) $orderItem->unit_price * (float) $orderItem->qty
534:             - (float) $orderItem->discount_amount
535:             + (float) $orderItem->tax_amount;
536: 
537:         return (int) round(max(0.0, $net) * 100);
538:     }
