540:     private function syncOrderPaymentStatusAfterRefund(Order $order): void
541:     {
542:         if (! in_array($order->payment_status, ['paid', 'partially_refunded', 'refunded'], true)) {
543:             return;
544:         }
545:         $refundedCents = (int) round((float) $order->returnRequests()->where('status', ReturnStatus::Refunded)->sum('total_refund_amount') * 100);
546:         $refundableCents = (int) $order->items()->get()->sum(fn (OrderItem $item): int => $this->netLineRefundCents($item));
547:         if ($refundableCents > 0 && $refundedCents >= $refundableCents) {
548:             $order->update(['payment_status' => 'refunded', 'requires_refund' => false]);
549:         } elseif ($refundedCents > 0) {
550:             $order->update(['payment_status' => 'partially_refunded']);
551:         }
552:     }
