554:     /**
555:      * حفظ صور العيوب على القرص الخاص داخل معاملة إنشاء المرتجع،
556:      * وتسجيل مساراتها في attachments البند.
557:      *
558:      * @param  list<array{order_item_id: int, attachments?: list<UploadedFile>}>  $rawItems
559:      */
560:     private function storeAttachments(ReturnRequest $return, array $rawItems, PrivateAttachments $files): void
561:     {
562:         $filesByOrderItem = [];
563:         foreach ($rawItems as $line) {
564:             foreach ($line['attachments'] ?? [] as $file) {
565:                 if ($file instanceof UploadedFile) {
566:                     $filesByOrderItem[(int) $line['order_item_id']][] = $file;
567:                 }
568:             }
569:         }
570:         if ($filesByOrderItem === []) {
571:             return;
572:         }
573: 
574:         $return->load('items');
575:         foreach ($return->items as $item) {
576:             $itemFiles = $filesByOrderItem[(int) $item->order_item_id] ?? [];
577:             if ($itemFiles === []) {
578:                 continue;
579:             }
580:             $paths = [];
581:             foreach ($itemFiles as $file) {
582:                 $paths[] = $files->store($file, "return_requests/{$return->id}");
583:             }
584:             $item->update(['attachments' => array_merge($item->attachments ?? [], $paths)]);
585:         }
586:     }
