588:     /** هل اكتمل استلام ورد قيمة كل بنود الطلب عبر المرتجعات؟ */
589:     private function isOrderFullyReturned(Order $order): bool
590:     {
591:         $items = $order->items()->get();
592:         if ($items->isEmpty()) {
593:             return false;
594:         }
595: 
596:         $receivedByItem = ReturnRequestItem::query()
597:             ->whereIn('order_item_id', $items->pluck('id'))
598:             ->whereHas('returnRequest', fn ($q) => $q->where('status', ReturnStatus::Refunded->value))
599:             ->selectRaw('order_item_id, COALESCE(SUM(received_good_qty + received_damaged_qty), 0) as total')
600:             ->groupBy('order_item_id')
601:             ->pluck('total', 'order_item_id');
602:         foreach ($items as $orderItem) {
603:             $received = (float) ($receivedByItem[$orderItem->id] ?? 0);
604:             if (round($received, 4) < round((float) $orderItem->qty, 4)) {
605:                 return false;
606:             }
607:         }
608: 
609:         return true;
610:     }
