 23: /**
 24:  * القلب النابض للمخزون — الطريق الوحيد لتغيير أي رصيد في النظام.
 25:  *
 26:  * قاعدة صارمة: ممنوع تعديل stock_levels من أي Controller أو Model آخر.
 27:  * كل تغيير يمر من هنا: تسجيل حركة في دفتر الأستاذ (stock_movements) أولًا،
 28:  * ثم تحديث الرصيد — داخل نفس الـ transaction ومع قفل الصف.
 29:  */
 30: class InventoryService
 31: {
 32:     public function __construct(private readonly SettingService $settings) {}
 33: 
 34:     /**
 35:      * الدالة المركزية الوحيدة لتغيير أي رصيد في النظام.
 36:      *
 37:      * @param  array{product_variant_id: int, branch_id: int, location_id?: int|null, type: StockMovementType|string, affected_bucket: StockBucket|string, quantity: float|int|string, unit_cost?: float|null, reference_type?: string|null, reference_id?: int|null, created_by?: int|null, notes?: string|null}  $data
 38:      */
 39:     public function recordMovement(array $data, ?StockLevel $prelockedLevel = null): StockMovement
 40:     {
 41:         $apply = function () use ($data, $prelockedLevel): StockMovement {
 42:             $rawQty = $data['quantity'];
 43:             if (! is_numeric($rawQty) || ! is_finite((float) $rawQty) || abs((float) $rawQty) > 99999999.9999) {
 44:                 throw new BusinessException('كمية الحركة غير صالحة.');
 45:             }
 46:             // Work in ten-thousandths to avoid floating point residues at zero.
 47:             $units = (int) round((float) $rawQty * 10000);
 48:             $qty = $units / 10000;
 49: 
 50:             if ($units === 0) {
 51:                 throw new BusinessException('كمية الحركة يجب ألا تساوي صفرًا.');
 52:             }
 53: 
 54:             $type = $data['type'] instanceof StockMovementType ? $data['type'] : StockMovementType::from($data['type']);
 55:             $bucket = $data['affected_bucket'] instanceof StockBucket ? $data['affected_bucket'] : StockBucket::from($data['affected_bucket']);
 56:             $this->assertValidMovementSemantics($type, $bucket, $units);
 57:             $locationId = $data['location_id'] ?? null;
 58: 
 59:             // صف مقفول مسبقًا من المستدعي (lockLevels): لا إعادة قفل ولا فحص موقع —
 60:             // المستدعي ضمن الصف والموقع عند القفل. خلاف ذلك نقفل هنا ونتحقق.
 61:             if ($prelockedLevel !== null) {
 62:                 if ((int) $prelockedLevel->product_variant_id !== (int) $data['product_variant_id']
 63:                     || (int) $prelockedLevel->branch_id !== (int) $data['branch_id']
 64:                     || ($prelockedLevel->location_id === null ? null : (int) $prelockedLevel->location_id) !== ($locationId === null ? null : (int) $locationId)) {
 65:                     throw new \LogicException('الصف المقفول مسبقًا لا يطابق مفتاح الحركة.');
 66:                 }
 67:                 $stock = $prelockedLevel;
 68:             } else {
 69:                 if ($locationId !== null && ! Location::query()->whereKey($locationId)->where('branch_id', $data['branch_id'])->exists()) {
 70:                     throw new BusinessException('الموقع لا يتبع الفرع المحدد.');
 71:                 }
 72: 
 73:                 $stock = $this->lockLevels([[
 74:                     'product_variant_id' => $data['product_variant_id'],
 75:                     'branch_id' => $data['branch_id'],
 76:                     'location_id' => $locationId,
 77:                 ]])->first();
 78:             }
 79: 
 80:             if ($bucket === StockBucket::OnHand && $units > 0) {
 81:                 $variant = $stock->variant;
 82:                 if ($variant === null || $variant->trashed() || ! $variant->is_active
 83:                     || ($stock->location_id !== null && ! $stock->location?->is_active)) {
 84:                     throw new BusinessException('الإدخال يتطلب متغيرًا وموقعًا نشطين.');
 85:                 }
 86:             }
 87: 
 88:             $bucketKey = $bucket->value;
 89:             $before = (float) $stock->{$bucketKey};
 90:             $afterUnits = (int) round($before * 10000) + $units;
 91:             $after = $afterUnits / 10000;
 92:             if ($afterUnits > 999999999999) {
 93:                 throw new BusinessException('الرصيد يتجاوز الحد المسموح.');
 94:             }
 95: 
 96:             // 2. التحقق: الرصيد المستهدف لا ينزل تحت الصفر
 97:             if ($after < 0) {
 98:                 throw new BusinessException("الرصيد غير كافٍ في ({$bucketKey}) لإتمام العملية.");
 99:             }
100: 
101:             // 3. التحقق: الكمية المتاحة للبيع لا تصبح سالبة بعد الحركة
102:             //    (يغطي حجز/تالف جديد أكبر من المتاح، وسحب فعلي يبتلع محجوزًا أو تالفًا)
103:             $onHand = $bucket === StockBucket::OnHand ? $after : (float) $stock->on_hand;
104:             $reserved = $bucket === StockBucket::Reserved ? $after : (float) $stock->reserved;
105:             $damaged = $bucket === StockBucket::Damaged ? $after : (float) $stock->damaged;
106:             $availableAfter = (int) round($onHand * 10000) - (int) round($reserved * 10000) - (int) round($damaged * 10000);
107: 
108:             if ($availableAfter < 0) {
109:                 $availableNow = (float) $stock->on_hand - (float) $stock->reserved - (float) $stock->damaged;
110: 
111:                 throw new BusinessException("الكمية المتاحة للبيع ({$availableNow}) غير كافية لإتمام العملية.");
112:             }
113: 
114:             // منفّذ الحركة إلزامي: من console/queue بلا مستخدم مصادق وبلا created_by
115:             // صريح، الفشل الواضح أفضل من QueryException على قيد NOT NULL.
116:             $createdBy = $data['created_by'] ?? auth()->id();
117:             if ($createdBy === null) {
118:                 throw new \LogicException('recordMovement يتطلب created_by صريحًا عند غياب مستخدم مصادق.');
119:             }
120: 
121:             // مرجع الدفتر يُخزن بالاسم القصير من morph map إن وُجد (stock_transfer/stocktake)
122:             // حتى لا تكسر إعادة تسمية الكلاسات أثر التدقيق؛ الأسماء الكاملة القديمة تظل مقروءة.
123:             $referenceType = $data['reference_type'] ?? null;
124:             if (is_string($referenceType) && class_exists($referenceType)) {
125:                 $referenceType = (new $referenceType)->getMorphClass();
126:             }
127: 
128:             // 4. تسجيل الحركة في دفتر الأستاذ (Ledger)
129:             $movement = StockMovement::query()->create([
130:                 'reference_number' => $this->settings->generateNextNumber('movement'),
131:                 'product_variant_id' => $data['product_variant_id'],
132:                 'branch_id' => $data['branch_id'],
133:                 'location_id' => $locationId,
134:                 'type' => $type,
135:                 'affected_bucket' => $bucket,
136:                 'quantity' => $qty,
137:                 'balance_before' => $before,
138:                 'balance_after' => $after,
139:                 'unit_cost' => $data['unit_cost'] ?? $this->movementCost($type, $referenceType, $data['reference_id'] ?? null, $stock),
140:                 'reference_type' => $referenceType,
141:                 'reference_id' => $data['reference_id'] ?? null,
142:                 'created_by' => $createdBy,
143:                 'notes' => $data['notes'] ?? null,
144:             ]);
145: 
146:             // 5. تحديث جدول الأرصدة من واقع الحركة
147:             $availableBefore = (float) $stock->on_hand - (float) $stock->reserved - (float) $stock->damaged;
148:             $stock->{$bucketKey} = $after;
149:             $stock->save();
150: 
151:             $reorder = (float) ($stock->reorder_level ?: $stock->variant?->reorder_level ?: 0);
152:             if ($availableAfter / 10000 <= $reorder && $availableBefore > $reorder) {
153:                 StockLowDetected::dispatch([
154:                     'product_variant_id' => $stock->product_variant_id, 'branch_id' => $stock->branch_id,
155:                     'available' => $availableAfter / 10000, 'reorder_level' => $reorder,
156:                 ]);
157:             }
158: 
159:             return $movement;
160:         };
161: 
162:         if ($prelockedLevel !== null) {
163:             if (DB::transactionLevel() === 0) {
164:                 throw new \LogicException('Prelocked stock requires an active transaction.');
165:             }
166: 
167:             return $apply();
168:         }
169: 
170:         return DB::transaction($apply);
171:     }
172: 
173:     private function movementCost(StockMovementType $type, ?string $referenceType, ?int $referenceId, StockLevel $stock): ?string
174:     {
175:         if ($type === StockMovementType::Sale) {
176:             return $stock->variant?->cost_price;
177:         }
178:         if ($type !== StockMovementType::SaleReturn) {
179:             return null;
180:         }
181:         $orderId = match ($referenceType) {
182:             'order', Order::class => $referenceId,
183:             'return_request', ReturnRequest::class => ReturnRequest::find($referenceId)?->order_id,
184:             default => null,
185:         };
186:         if ($orderId === null) {
187:             return null;
188:         }
189:         $orderId = Order::find($orderId)?->original_pos_order_id ?? $orderId;
190:         $cost = StockMovement::query()->whereIn('reference_type', ['order', Order::class])
191:             ->where('reference_id', $orderId)->where('product_variant_id', $stock->product_variant_id)
192:             ->where('type', StockMovementType::Sale)->whereNotNull('unit_cost')
193:             ->selectRaw('SUM(quantity * unit_cost) / NULLIF(SUM(quantity), 0) AS original_cost')->value('original_cost');
194: 
195:         return $cost === null ? null : (string) $cost;
196:     }
197: 
198:     /**
199:      * تسوية يدوية متعددة العناصر داخل transaction واحدة (أي فشل يلغي الكل).
200:      *
201:      * مع مفتاح عدم تكرار (Idempotency-Key): يُدرج المفتاح داخل نفس الـ transaction،
202:      * فالتكرار المتزامن يصطدم بالقيد الفريد بعد commit الأول ويعيد الحركات المحفوظة،
203:      * ونفس المفتاح بحمولة مختلفة يُرفض 409، وفشل الطلب يلغي المفتاح معه.
204:      *
205:      * @param  array{branch_id: int, location_id?: int|null, items: list<array{product_variant_id: int, adjustment_type: string, quantity: float|int|string, reason?: string|null}>}  $payload
206:      * @return list<StockMovement>
207:      */
208:     public function applyAdjustments(array $payload, int $userId, ?string $idempotencyKey = null): array
209:     {
210:         app(BranchAccess::class)->assertBranch($userId, (int) $payload['branch_id']);
211:         if ($idempotencyKey === null) {
212:             return $this->executeAdjustments($payload, $userId);
213:         }
214: 
215:         $requestHash = IdempotencyFingerprint::hash($payload);
216: 
217:         try {
218:             return DB::transaction(function () use ($payload, $userId, $idempotencyKey, $requestHash): array {
219:                 $record = InventoryIdempotencyKey::query()->create([
220:                     'user_id' => $userId,
221:                     'key' => $idempotencyKey,
222:                     'request_hash' => $requestHash,
223:                 ]);
224: 
225:                 $movements = $this->executeAdjustments($payload, $userId);
226: 
227:                 $record->update([
228:                     'response' => array_map(fn (StockMovement $movement) => $movement->id, $movements),
229:                     'status_code' => 201,
230:                 ]);
231: 
232:                 return $movements;
233:             });
234:         } catch (UniqueConstraintViolationException $e) {
235:             // الالتقاط خاص بقيد مفتاح عدم التكرار وحده: أي انتهاك فريد آخر داخل
236:             // المعاملة خطأ حقيقي يجب أن يظهر، لا أن يُقنَّع كتعارض مفتاح (L-2).
237:             if (! str_contains($e->getMessage(), 'inventory_idempotency_keys_user_id_key_unique')) {
238:                 throw $e;
239:             }
240: 
241:             $record = InventoryIdempotencyKey::query()
242:                 ->where('user_id', $userId)->where('key', $idempotencyKey)->first();
243: 
244:             if ($record === null) {
245:                 throw new BusinessException('تعارض في مفتاح عدم التكرار؛ أعد المحاولة.', [], 409);
246:             }
247: 
248:             if (! hash_equals($record->request_hash, $requestHash)) {
249:                 throw new BusinessException('مفتاح عدم التكرار هذا مستخدم مسبقًا مع بيانات مختلفة.', [], 409);
250:             }
251: 
252:             $ids = $record->response ?? [];
253:             $byId = StockMovement::query()->whereIn('id', $ids)->get()->keyBy('id');
254: 
255:             return array_values(array_filter(array_map(fn ($id) => $byId->get($id), $ids)));
256:         }
257:     }
258: 
259:     /**
260:      * @param  array{branch_id: int, location_id?: int|null, items: list<array{product_variant_id: int, adjustment_type: string, quantity: float|int|string, reason?: string|null}>}  $payload
261:      * @return list<StockMovement>
262:      */
263:     private function executeAdjustments(array $payload, int $userId): array
264:     {
265:         return DB::transaction(function () use ($payload, $userId): array {
266:             app(BranchAccess::class)->assertBranch($userId, (int) $payload['branch_id']);
267: 
268:             // M5: التعطيل لا يحبس الرصيد — عمليات الإخراج (decrease/تالف/شطب) مسموحة على
269:             // متغير/موقع معطّل لتصفية رصيده، والإدخال (increase) وحده يتطلب النشاط.
270:             if (collect($payload['items'])->contains('adjustment_type', 'increase')) {
271:                 $variants = ProductVariant::query()->withTrashed()
272:                     ->whereIn('id', array_column($payload['items'], 'product_variant_id'))
273:                     ->get()->keyBy('id');
274:                 $location = ($payload['location_id'] ?? null) !== null ? Location::query()->find($payload['location_id']) : null;
275: 
276:                 foreach ($payload['items'] as $item) {
277:                     if ($item['adjustment_type'] !== 'increase') {
278:                         continue;
279:                     }
280:                     // المحذوف ناعمًا يعامل كمعطّل للإدخال، لكن إخراجه يظل مسموحًا
281:                     // حتى لا يُحبس رصيده للأبد (M-9).
282:                     $variant = $variants->get($item['product_variant_id']);
283:                     if ($variant === null || $variant->trashed() || ! $variant->is_active) {
284:                         throw new BusinessException('لا يمكن الإدخال على متغير معطّل؛ فعّله أولًا أو استخدم عمليات الإخراج لتصفية رصيده.');
285:                     }
286:                     if ($location !== null && ! $location->is_active) {
287:                         throw new BusinessException('لا يمكن الإدخال إلى موقع معطّل؛ فعّله أولًا.');
288:                     }
289:                 }
290:             }
291:             $levels = $this->lockLevels(array_map(fn ($item) => [
292:                 'product_variant_id' => $item['product_variant_id'],
293:                 'branch_id' => $payload['branch_id'],
294:                 'location_id' => $payload['location_id'] ?? null,
295:             ], $payload['items']));
296:             $movements = [];
297: 
298:             foreach ($payload['items'] as $item) {
299:                 // الصف مقفول مسبقًا أعلاه — تُمرَّر حركتا العنصر عليه مباشرة.
300:                 $level = $levels->get($this->levelKey([
301:                     'product_variant_id' => $item['product_variant_id'],
302:                     'branch_id' => $payload['branch_id'],
303:                     'location_id' => $payload['location_id'] ?? null,
304:                 ]));
305:                 if (in_array($item['adjustment_type'], ['write_off_damaged', 'restore_damaged'], true)) {
306:                     $base = [
307:                         'product_variant_id' => $item['product_variant_id'],
308:                         'branch_id' => $payload['branch_id'], 'location_id' => $payload['location_id'] ?? null,
309:                         'created_by' => $userId, 'notes' => $item['reason'] ?? null,
310:                         'quantity' => -abs((float) $item['quantity']),
311:                     ];
312:                     $movements[] = $this->recordMovement([...$base, 'type' => StockMovementType::DamageRelease, 'affected_bucket' => StockBucket::Damaged], $level);
313:                     if ($item['adjustment_type'] === 'write_off_damaged') {
314:                         $movements[] = $this->recordMovement([...$base, 'type' => StockMovementType::DamageWriteOff, 'affected_bucket' => StockBucket::OnHand], $level);
315:                     }
316: 
317:                     continue;
318:                 }
319:                 [$type, $bucket, $sign] = match ($item['adjustment_type']) {
320:                     'increase' => [StockMovementType::AdjustmentIn, StockBucket::OnHand, 1],
321:                     'decrease' => [StockMovementType::AdjustmentOut, StockBucket::OnHand, -1],
322:                     'mark_damaged' => [StockMovementType::Damage, StockBucket::Damaged, 1],
323:                     default => throw new BusinessException('نوع تسوية غير معروف: '.$item['adjustment_type']),
324:                 };
325: 
326:                 $movements[] = $this->recordMovement([
327:                     'product_variant_id' => $item['product_variant_id'],
328:                     'branch_id' => $payload['branch_id'],
329:                     'location_id' => $payload['location_id'] ?? null,
330:                     'type' => $type,
331:                     'affected_bucket' => $bucket,
332:                     'quantity' => $sign * abs((float) $item['quantity']),
333:                     'created_by' => $userId,
334:                     'notes' => $item['reason'] ?? null,
335:                 ], $level);
336:             }
337: 
338:             return $movements;
339:         });
340:     }
