342:     /** الرصيد الحالي لمتغير في فرع/موقع (للقطات الجرد ونحوها) — قراءة فقط. */
343:     public function levelFor(int $variantId, int $branchId, ?int $locationId): ?StockLevel
344:     {
345:         return StockLevel::query()
346:             ->where('product_variant_id', $variantId)
347:             ->where('branch_id', $branchId)
348:             ->where('location_id', $locationId)
349:             ->first();
350:     }
