352:     /** Acquire every stock key before a multi-item operation, in one global order. */
353:     public function lockLevels(array $keys): Collection
354:     {
355:         if (DB::transactionLevel() === 0) {
356:             throw new \LogicException('Stock locks require an active transaction.');
357:         }
358:         // انتظار محدود للأقفال داخل هذه المعاملة فقط؛ التنافس الطويل يتحول لرفض
359:         // واضح (409) بدل تعليق الطلب حتى مهلة PHP-FPM.
360:         DB::statement("SET LOCAL lock_timeout = '5s'");
361:         $keys = collect($keys)->unique(fn ($key) => $this->levelKey($key))
362:             ->sortBy(fn ($key) => [(int) $key['branch_id'], (int) ($key['location_id'] ?? 0), (int) $key['product_variant_id']]);
363:         if ($keys->isEmpty()) {
364:             return collect();
365:         }
366:         $now = now();
367: 
368:         try {
369:             // الإدخال نفسه قد ينتظر قفلًا: ON CONFLICT ينتظر معاملة أخرى أدخلت
370:             // نفس المفتاح ولم تعتمد بعد، فيخضع لنفس lock_timeout — لازم يكون
371:             // جوه الـ try حتى يتحول الانتظار الطويل لـ 409 لا 500 (M-2).
372:             DB::table('stock_levels')->insertOrIgnore($keys->map(fn ($key) => [
373:                 'product_variant_id' => $key['product_variant_id'], 'branch_id' => $key['branch_id'],
374:                 'location_id' => $key['location_id'] ?? null, 'created_at' => $now, 'updated_at' => $now,
375:             ])->values()->all());
376: 
377:             $levels = StockLevel::query()->with(['variant:id,is_active,deleted_at,cost_price,reorder_level', 'location:id,is_active'])->where(function ($query) use ($keys): void {
378:                 foreach ($keys->groupBy(fn ($key) => $key['branch_id'].':'.($key['location_id'] ?? 0)) as $group) {
379:                     $identity = $group->first();
380:                     $query->orWhere(fn ($scope) => $scope->where('branch_id', $identity['branch_id'])
381:                         ->where('location_id', $identity['location_id'] ?? null)
382:                         ->whereIn('product_variant_id', $group->pluck('product_variant_id')->all()));
383:                 }
384:             })->orderBy('branch_id')->orderByRaw('location_id ASC NULLS FIRST')->orderBy('product_variant_id')
385:                 ->lockForUpdate()->get()->keyBy(fn ($stock) => $this->levelKey($stock->getAttributes()));
386:         } catch (QueryException $e) {
387:             // 55P03 = lock_timeout، و40P01 = deadlock — كلاهما ازدحام مؤقت
388:             // على الأقفال، فيُرجع 409 قابلًا لإعادة المحاولة لا 500 (M-2).
389:             if (in_array($e->errorInfo[0] ?? $e->getCode(), ['55P03', '40P01'], true)) {
390:                 throw new BusinessException('المخزون مشغول بعملية أخرى الآن؛ أعد المحاولة بعد لحظات.', [], 409);
391:             }
392: 
393:             throw $e;
394:         }
395: 
396:         return $levels;
397:     }
398: 
399:     public function levelKey(array $key): string
400:     {
401:         return $key['branch_id'].':'.($key['location_id'] ?? 0).':'.$key['product_variant_id'];
402:     }
403: 
404:     private function assertValidMovementSemantics(StockMovementType $type, StockBucket $bucket, int $units): void
405:     {
406:         [$allowed, $positive] = match ($type) {
407:             StockMovementType::PurchaseReceipt, StockMovementType::SaleReturn,
408:             StockMovementType::AdjustmentIn, StockMovementType::StocktakeGain, StockMovementType::TransferIn => [[StockBucket::OnHand], true],
409:             StockMovementType::Sale, StockMovementType::AdjustmentOut,
410:             StockMovementType::StocktakeLoss, StockMovementType::TransferOut,
411:             StockMovementType::DamageWriteOff => [[StockBucket::OnHand], false],
412:             StockMovementType::Damage => [[StockBucket::Damaged], true],
413:             StockMovementType::DamageRelease => [[StockBucket::Damaged], false],
414:             StockMovementType::Reserve => [[StockBucket::Reserved], true],
415:             StockMovementType::ReleaseReserve => [[StockBucket::Reserved], false],
416:             StockMovementType::TransferInTransit => [[StockBucket::InTransit], true],
417:             StockMovementType::TransferTransitRelease, StockMovementType::TransferShortage => [[StockBucket::InTransit], false],
418:         };
419:         if (! in_array($bucket, $allowed, true) || ($units > 0) !== $positive) {
420:             throw new BusinessException('نوع الحركة لا يطابق وعاء المخزون أو اتجاه الكمية.');
421:         }
422:     }
