 19: /**
 20:  * محرك التسعير المركزي — يُستدعى من المتجر والجملة والـ POS ولوحة الإدارة.
 21:  *
 22:  * شجرة الأولويات:
 23:  * 1. سعر خاص بالعميل (customer_specific)
 24:  * 2. سعر مجموعة العميل (customer_group)
 25:  * 3. قائمة النوع (wholesale/distributor للمعتمدين فقط، وإلا retail)؛ وقناة
 26:  *    جملة/موزع بلا عنصر مطابق ترجع لقوائم retail النشطة قبل السعر الأساسي.
 27:  * 4. السعر الأساسي للمتغير (base_price، المتوافق مع retail_price من المرحلة 2).
 28:  *
 29:  * خصم مجموعة العميل (discount_percentage) لا يصنع مستوى مستقلًا: يُطبق فوق ناتج
 30:  * المستويين 3/4 (سعر القناة)، ولا يُخصم من سعر خاص بالعميل أو سعر قائمة المجموعة.
 31:  * متغير بلا retail_price ولا قائمة مطابقة = غير مُسعَّر، ويرمي BusinessException.
 32:  *
 33:  * داخل كل مستوى: القائمة المخصصة للفرع أولًا، ثم أعلى شريحة كمية محققة،
 34:  * ثم أولوية القائمة، ثم السعر الأقل.
 35:  */
 36: class PricingService
 37: {
 38:     public function tiers(ProductVariant $variant, Customer $customer): array
 39:     {
 40:         $group = $customer->customerGroup()->where('is_active', true)->first();
 41:         $channel = $this->channelFor($customer);
 42:         $thresholds = $this->eligibleItems($variant, PHP_FLOAT_MAX, null, Carbon::now())
 43:             ->where(function ($q) use ($customer, $group, $channel): void {
 44:                 $q->whereIn('price_lists.type', [$channel->value, PriceListType::Retail->value])
 45:                     ->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerSpecific)->where('price_lists.customer_id', $customer->id));
 46:                 if ($group) {
 47:                     $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerGroup)->where('price_lists.customer_group_id', $group->id));
 48:                 }
 49:             })->pluck('price_list_items.min_qty');
 50:         $result = [];
 51:         foreach (collect([1])->merge($thresholds)->map(fn ($qty) => max(1, (int) ceil((float) $qty)))->unique()->sort() as $qty) {
 52:             $price = $this->resolve($variant, $customer, $qty)['unit_price'];
 53:             if ($result !== [] && end($result)['unit_price'] === $price) {
 54:                 continue;
 55:             }
 56:             $result[] = ['min_qty' => $qty, 'unit_price' => $price];
 57:         }
 58: 
 59:         return $result;
 60:     }
 61: 
 62:     /** Resolve storefront prices in SQL using the same owner, tier and priority rules as resolve(). */
 63:     public function withStorePrice(Builder $variants, ?Customer $customer): Builder
 64:     {
 65:         $eligible = $customer !== null && $customer->status === CustomerStatus::Approved;
 66:         $channel = $this->channelFor($customer);
 67:         $group = $eligible ? $customer->customerGroup : null;
 68:         $group = $group?->is_active ? $group : null;
 69:         $factor = $this->discountFactor($group?->discount_percentage ?? '0');
 70:         $items = $this->eligibleItems(null, 1, null, Carbon::now())
 71:             ->where(function ($q) use ($eligible, $customer, $group, $channel): void {
 72:                 $q->whereIn('price_lists.type', array_unique([$channel->value, PriceListType::Retail->value]));
 73:                 if ($eligible) {
 74:                     $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerSpecific)
 75:                         ->where('price_lists.customer_id', $customer->id));
 76:                 }
 77:                 if ($group !== null) {
 78:                     $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerGroup)
 79:                         ->where('price_lists.customer_group_id', $group->id));
 80:                 }
 81:             })
 82:             ->select([])
 83:             ->selectRaw("price_list_items.price * CASE WHEN price_lists.type IN ('customer_specific', 'customer_group') THEN 1::numeric ELSE ?::numeric END", [$factor])
 84:             ->orderByRaw("CASE WHEN price_lists.type = 'customer_specific' THEN 0 WHEN price_lists.type = 'customer_group' THEN 1 WHEN price_lists.type = ? THEN 2 ELSE 3 END", [$channel->value]);
 85:         $items = $this->ordered($items)->limit(1);
 86: 
 87:         return $variants->select('product_variants.*')
 88:             ->selectRaw('ROUND(COALESCE(('.$items->toSql().'), product_variants.retail_price * ?)::numeric, 2) AS store_price', [...$items->getBindings(), $factor]);
 89:     }
 90: 
 91:     /**
 92:      * @return array{unit_price: float, base_price: float, source: string, price_list_id: int|null}
 93:      */
 94:     public function resolve(
 95:         ProductVariant $variant,
 96:         ?Customer $customer = null,
 97:         float $qty = 1,
 98:         ?int $branchId = null,
 99:     ): array {
100:         if (! is_finite($qty) || $qty <= 0) {
101:             throw new BusinessException('كمية التسعير يجب أن تكون موجبة.');
102:         }
103:         $now = Carbon::now();
104: 
105:         $baseQuery = $this->eligibleItems($variant, $qty, $branchId, $now);
106:         $channel = $this->channelFor($customer);
107:         $eligibleCustomer = $customer !== null && $customer->status === CustomerStatus::Approved;
108: 
109:         // الأولوية 1: سعر خاص بالعميل
110:         if ($eligibleCustomer) {
111:             $item = $this->ordered((clone $baseQuery)
112:                 ->where('price_lists.type', PriceListType::CustomerSpecific)
113:                 ->where('price_lists.customer_id', $customer->id)
114:             )->first();
115: 
116:             if ($item !== null) {
117:                 return $this->formatResponse($item->price, PriceListType::CustomerSpecific->value, (int) $item->price_list_id, $variant, $channel);
118:             }
119:         }
120: 
121:         // الأولوية 2: سعر مجموعة العميل
122:         $group = $eligibleCustomer ? $customer->customerGroup()->where('is_active', true)->first() : null;
123:         if ($group !== null) {
124:             $item = $this->ordered((clone $baseQuery)
125:                 ->where('price_lists.type', PriceListType::CustomerGroup)
126:                 ->where('price_lists.customer_group_id', $group->id)
127:             )->first();
128: 
129:             if ($item !== null) {
130:                 return $this->formatResponse($item->price, PriceListType::CustomerGroup->value, (int) $item->price_list_id, $variant, $channel);
131:             }
132:         }
133: 
134:         // الأولوية 3: قائمة نوع العميل (أو القطاعي افتراضيًا)
135:         $item = $this->ordered((clone $baseQuery)
136:             ->where('price_lists.type', $channel)
137:         )->first();
138: 
139:         // قناة جملة/موزع بلا عنصر في قائمتها ترجع لقوائم القطاعي النشطة قبل
140:         // السعر الأساسي — وإلا دفع عميل الجملة أكثر من عميل التجزئة (M-1).
141:         if ($item === null && $channel !== PriceListType::Retail) {
142:             $item = $this->ordered((clone $baseQuery)
143:                 ->where('price_lists.type', PriceListType::Retail)
144:             )->first();
145: 
146:             if ($item !== null) {
147:                 $channel = PriceListType::Retail;
148:             }
149:         }
150: 
151:         if ($item !== null) {
152:             $channelPrice = (string) $item->price;
153:             $channelListId = (int) $item->price_list_id;
154:             $channelSource = $channel->value;
155:         } elseif ($variant->retail_price === null) {
156:             // الأولوية 4 مستحيلة: لا قائمة مطابقة ولا سعر قطاعي — الصنف غير مُسعَّر
157:             // ولا يجوز أن يخرج بسعر صفر ليُباع مجانًا.
158:             throw new BusinessException('الصنف غير مُسعَّر: لا توجد قائمة أسعار مطابقة ولا سعر قطاعي للمتغير.');
159:         } else {
160:             // الأولوية 4: السعر الأساسي الموحد؛ أسعار الجملة والموزعين تأتي من القوائم.
161:             $channelPrice = $this->basePrice($variant, $channel);
162:             $channelListId = null;
163:             $channelSource = 'base_price';
164:         }
165: 
166:         // خصم مجموعة العميل يُطبق "فوق" سعر القناة المحسوب (قائمة القناة أو الأساسي)،
167:         // ولا يتجاوزه أبدًا — فلا يخسر العميل سعر جملة/موزع أفضل بسبب خصم مجموعته.
168:         if ($group !== null && (float) $group->discount_percentage > 0) {
169:             return $this->formatResponse(
170:                 (string) BigDecimal::of($channelPrice)->multipliedBy($this->discountFactor($group->discount_percentage)),
171:                 'customer_group_discount',
172:                 $channelListId,
173:                 $variant,
174:                 $channel,
175:             );
176:         }
177: 
178:         return $this->formatResponse($channelPrice, $channelSource, $channelListId, $variant, $channel);
179:     }
180: 
181:     /** قناة التسعير: الجملة/الموزع للحسابات المعتمدة فقط، وغير ذلك قطاعي. */
182:     private function channelFor(?Customer $customer): PriceListType
183:     {
184:         if ($customer !== null
185:             && in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true)
186:             && $customer->status === CustomerStatus::Approved) {
187:             return PriceListType::from($customer->type->value);
188:         }
189: 
190:         return PriceListType::Retail;
191:     }
192: 
193:     private function basePrice(ProductVariant $variant, PriceListType $channel): ?string
194:     {
195:         return $variant->retail_price === null ? null : $variant->base_price;
196:     }
197: 
198:     private function discountFactor(string $percentage): string
199:     {
200:         return (string) BigDecimal::of('100')->minus($percentage)->dividedBy('100', 8);
201:     }
202: 
203:     /** كل عناصر التسعير السارية لهذا المتغير والكمية والفرع والوقت. */
204:     private function eligibleItems(?ProductVariant $variant, float $qty, ?int $branchId, Carbon $now): Builder
205:     {
206:         return PriceListItem::query()
207:             ->select('price_list_items.*')
208:             ->join('price_lists', 'price_lists.id', '=', 'price_list_items.price_list_id')
209:             ->where('price_lists.is_active', true)
210:             ->when($variant !== null,
211:                 fn ($q) => $q->where('price_list_items.product_variant_id', $variant->id),
212:                 fn ($q) => $q->whereColumn('price_list_items.product_variant_id', 'product_variants.id'))
213:             ->where('price_list_items.min_qty', '<=', $qty)
214:             ->where(fn ($q) => $q->whereNull('price_lists.starts_at')->orWhere('price_lists.starts_at', '<=', $now))
215:             ->where(fn ($q) => $q->whereNull('price_lists.ends_at')->orWhere('price_lists.ends_at', '>=', $now))
216:             ->where(fn ($q) => $q->whereNull('price_list_items.starts_at')->orWhere('price_list_items.starts_at', '<=', $now))
217:             ->where(fn ($q) => $q->whereNull('price_list_items.ends_at')->orWhere('price_list_items.ends_at', '>=', $now))
218:             ->where(function ($q) use ($branchId): void {
219:                 $q->whereNull('price_lists.branch_id');
220:                 if ($branchId !== null) {
221:                     $q->orWhere('price_lists.branch_id', $branchId);
222:                 }
223:             });
224:     }
225: 
226:     /** ترتيب داخل المستوى الواحد: فرع مخصص أولًا، أعلى شريحة، أعلى أولوية، أقل سعر. */
227:     private function ordered(Builder $query): Builder
228:     {
229:         return $query
230:             ->orderByRaw('price_lists.branch_id IS NULL ASC')
231:             ->orderByDesc('price_list_items.min_qty')
232:             ->orderByDesc('price_lists.priority')
233:             ->orderBy('price_list_items.price');
234:     }
235: 
236:     /**
237:      * @return array{unit_price: float, base_price: float, source: string, price_list_id: int|null}
238:      */
239:     private function formatResponse(string|float $unitPrice, string $source, ?int $priceListId, ProductVariant $variant, PriceListType $channel): array
240:     {
241:         return [
242:             'unit_price' => (float) (string) BigDecimal::of((string) $unitPrice)->toScale(2, RoundingMode::HalfUp),
243:             'base_price' => (float) (string) BigDecimal::of($this->basePrice($variant, $channel) ?? (string) $unitPrice)->toScale(2, RoundingMode::HalfUp),
244:             'source' => $source,
245:             'price_list_id' => $priceListId,
246:         ];
247:     }
