  5: namespace App\Services;
  6: 
  7: use App\Enums\StockBucket;
  8: use App\Enums\StockMovementType;
  9: use App\Enums\StocktakeStatus;
 10: use App\Exceptions\BusinessException;
 11: use App\Models\Location;
 12: use App\Models\StockMovement;
 13: use App\Models\Stocktake;
 14: use App\Models\StocktakeItem;
 15: use App\Services\Concerns\HandlesIdempotentCreation;
 16: use Illuminate\Contracts\Pagination\LengthAwarePaginator;
 17: use Illuminate\Support\Collection;
 18: use Illuminate\Support\Facades\DB;
 19: 
 20: /**
 21:  * جلسات الجرد الفعلي. لقطة system_qty بتتاخد من stock_levels وقت إنشاء العنصر،
 22:  * والاعتماد بيحوّل الفروق لحركات دفتر (فائض/عجز) عبر InventoryService فقط،
 23:  * وبعد الاعتماد الجلسة بتتقفل نهائيًا.
 24:  */
 25: class StocktakeService
 26: {
 27:     use HandlesIdempotentCreation;
 28: 
 29:     public function __construct(
 30:         private readonly InventoryService $inventory,
 31:         private readonly SettingService $settings,
 32:     ) {}
 33: 
 34:     public function paginate(array $filters): LengthAwarePaginator
 35:     {
 36:         return Stocktake::query()
 37:             ->when($filters['staff_branch_id'] ?? null, fn ($q, $branch) => $q->where('branch_id', $branch))
 38:             ->with(['branch', 'location', 'creator'])
 39:             ->withCount('items')
 40:             ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
 41:             ->when($filters['status'] ?? null, fn ($q, $v) => $q->where('status', $v))
 42:             ->orderByDesc('id')
 43:             ->paginate($filters['per_page'] ?? 15);
 44:     }
 45: 
 46:     public function find(int $id): Stocktake
 47:     {
 48:         return Stocktake::query()
 49:             ->with(['items.variant', 'branch', 'location', 'creator', 'approver'])
 50:             ->findOrFail($id);
 51:     }
 52: 
 53:     public function create(array $data, int $userId, ?string $idempotencyKey = null): Stocktake
 54:     {
 55:         app(BranchAccess::class)->assertBranch($userId, (int) $data['branch_id']);
 56: 
 57:         /** @var Stocktake */
 58:         return $this->createIdempotently(
 59:             'stocktake_store',
 60:             $data,
 61:             $userId,
 62:             $idempotencyKey,
 63:             Stocktake::class,
 64:             ['items.variant', 'branch', 'location', 'creator'],
 65:             fn (): Stocktake => $this->doCreate($data, $userId),
 66:         );
 67:     }
 68: 
 69:     private function doCreate(array $data, int $userId): Stocktake
 70:     {
 71:         return DB::transaction(function () use ($data, $userId): Stocktake {
 72:             app(BranchAccess::class)->assertBranch($userId, (int) $data['branch_id']);
 73:             $stocktake = Stocktake::query()->create([
 74:                 'stocktake_number' => $this->settings->generateNextNumber('stocktake'),
 75:                 'branch_id' => $data['branch_id'],
 76:                 'location_id' => $data['location_id'] ?? null,
 77:                 'status' => StocktakeStatus::Draft,
 78:                 'created_by' => $userId,
 79:                 'notes' => $data['notes'] ?? null,
 80:             ]);
 81: 
 82:             $this->syncItems($stocktake, $data['items'] ?? []);
 83: 
 84:             return $stocktake->load(['items.variant', 'branch', 'location', 'creator']);
 85:         });
 86:     }
 87: 
 88:     public function update(Stocktake $stocktake, array $data, int $userId): Stocktake
 89:     {
 90:         return DB::transaction(function () use ($stocktake, $data, $userId): Stocktake {
 91:             $stocktake = Stocktake::query()->lockForUpdate()->findOrFail($stocktake->id);
 92:             $this->assertEditable($stocktake);
 93:             app(BranchAccess::class)->assertBranch($userId, $stocktake->branch_id);
 94:             app(BranchAccess::class)->assertBranch($userId, (int) ($data['branch_id'] ?? $stocktake->branch_id));
 95: 
 96:             $branchId = $data['branch_id'] ?? $stocktake->branch_id;
 97:             $locationId = array_key_exists('location_id', $data) ? $data['location_id'] : $stocktake->location_id;
 98:             if ($locationId !== null && ! Location::query()->whereKey($locationId)->where('branch_id', $branchId)->exists()) {
 99:                 throw new BusinessException('موقع الجرد لا يتبع الفرع المحدد.');
100:             }
101:             $scopeChanged = (int) $branchId !== $stocktake->branch_id || ($locationId === null ? null : (int) $locationId) !== $stocktake->location_id;
102:             if ($scopeChanged
103:                 && ! array_key_exists('items', $data) && $stocktake->items()->exists()) {
104:                 throw new BusinessException('تغيير نطاق الجرد يتطلب إعادة إرسال العناصر والعد الفعلي.');
105:             }
106: 
107:             if (isset($data['status'])) {
108:                 $target = StocktakeStatus::from($data['status']);
109:                 $allowed = match ($stocktake->status) {
110:                     StocktakeStatus::Draft => [StocktakeStatus::InProgress, StocktakeStatus::Cancelled],
111:                     StocktakeStatus::InProgress => [StocktakeStatus::Cancelled],
112:                     default => [],
113:                 };
114: 
115:                 if (! in_array($target, $allowed, true)) {
116:                     throw new BusinessException("لا يمكن نقل الجرد من حالة {$stocktake->status->value} إلى {$target->value}.");
117:                 }
118: 
119:                 $stocktake->status = $target;
120:             }
121: 
122:             $stocktake->fill([
123:                 'branch_id' => $data['branch_id'] ?? $stocktake->branch_id,
124:                 'location_id' => array_key_exists('location_id', $data) ? $data['location_id'] : $stocktake->location_id,
125:                 'notes' => array_key_exists('notes', $data) ? $data['notes'] : $stocktake->notes,
126:             ])->save();
127: 
128:             if (isset($data['items'])) {
129:                 if ($scopeChanged) {
130:                     $data['items'] = array_map(fn ($item) => [...$item, 'recount' => true], $data['items']);
131:                 }
132:                 $this->upsertItems($stocktake, $data['items']);
133:             }
134: 
135:             return $stocktake->load(['items.variant', 'branch', 'location', 'creator']);
136:         });
137:     }
138: 
139:     /**
140:      * الاعتماد: تحويل كل فارق غير صفري لحركة دفتر (stocktake_gain/stocktake_loss)
141:      * على on_hand في نطاق الجلسة (فرعها وموقعها)، ثم قفل الجلسة.
142:      */
143:     public function approve(Stocktake $stocktake, int $userId): Stocktake
144:     {
145:         return DB::transaction(function () use ($stocktake, $userId): Stocktake {
146:             $stocktake = Stocktake::query()->lockForUpdate()->findOrFail($stocktake->id);
147:             app(BranchAccess::class)->assertBranch($userId, $stocktake->branch_id);
148:             $stocktake->load('items.variant');
149: 
150:             if (! in_array($stocktake->status, [StocktakeStatus::Draft, StocktakeStatus::InProgress], true)) {
151:                 throw new BusinessException('لا يمكن اعتماد جرد بحالة '.$stocktake->status->value.'.');
152:             }
153: 
154:             $uncounted = $stocktake->items->filter(fn ($item) => $item->counted_qty === null);
155: 
156:             if ($stocktake->items->isEmpty()) {
157:                 throw new BusinessException('لا يمكن اعتماد جرد بلا عناصر.');
158:             }
159: 
160:             if ($uncounted->isNotEmpty()) {
161:                 throw new BusinessException('لا يمكن الاعتماد: توجد عناصر لم تُعدّ بعد.');
162:             }
163: 
164:             $levels = $this->inventory->lockLevels($stocktake->items->map(fn ($item) => [
165:                 'product_variant_id' => $item->product_variant_id,
166:                 'branch_id' => $stocktake->branch_id, 'location_id' => $stocktake->location_id,
167:             ])->all());
168: 
169:             // سياسة اللقطة القديمة قابلة للضبط (inventory.stocktake_stale_policy):
170:             // - reject (الافتراضي): أي حركة بعد العد ترفض الاعتماد وتعيد قائمة
171:             //   إعادة العد. يمنع أيضًا تطبيق نفس الفرق مرتين عند تداخل جلستين.
172:             // - apply_difference: تطبيق الفرق (counted − system_qty) على الرصيد
173:             //   الحالي يحفظ الحركات البينية حسابيًا (النهائي = المعدود + صافيها)
174:             //   فلا تُحبس جلسات الفروع النشطة. تسوية جرد أخرى بعد اللقطة تُرفض
175:             //   في الوضعين حتى لا يُطبّق نفس الفرق مرتين.
176:             // ولا تُحدَّث اللقطة بإعادة الحفظ في أي سياسة، بل بتغيير العدد أو recount.
177:             $rejectStale = config('inventory.stocktake_stale_policy', 'reject') !== 'apply_difference';
178:             $staleItemIds = [];
179:             $staleVariantIds = [];
180:             $latestMovements = StockMovement::query()->where('branch_id', $stocktake->branch_id)
181:                 ->where('location_id', $stocktake->location_id)->where('affected_bucket', StockBucket::OnHand->value)
182:                 ->whereIn('product_variant_id', $stocktake->items->pluck('product_variant_id'))
183:                 ->when(! $rejectStale, fn ($q) => $q->whereIn('type', [StockMovementType::StocktakeGain->value, StockMovementType::StocktakeLoss->value]))
184:                 ->selectRaw('product_variant_id, MAX(id) AS last_id')->groupBy('product_variant_id')
185:                 ->pluck('last_id', 'product_variant_id');
186:             foreach ($stocktake->items as $item) {
187:                 $key = $this->inventory->levelKey([
188:                     'product_variant_id' => $item->product_variant_id,
189:                     'branch_id' => $stocktake->branch_id, 'location_id' => $stocktake->location_id,
190:                 ]);
191:                 if ((int) ($latestMovements[$item->product_variant_id] ?? 0) > (int) $item->snapshot_movement_id
192:                     || ($rejectStale && (int) round((float) $levels[$key]->on_hand * 10000) !== (int) round((float) $item->system_qty * 10000))) {
193:                     $staleItemIds[] = $item->id;
194:                     $staleVariantIds[] = $item->product_variant_id;
195:                 }
196:                 $finalQty = (float) $levels[$key]->on_hand + (float) $item->difference;
197:                 if ((int) round($finalQty * 10000) < (int) round((float) $levels[$key]->reserved * 10000) + (int) round((float) $levels[$key]->damaged * 10000)) {
198:                     throw new BusinessException('العد الفعلي أقل من المحجوز والتالف؛ راجع الحجوزات وسوِّ التالف قبل إعادة العد والاعتماد.');
199:                 }
200:             }
201: 
202:             if ($staleItemIds !== []) {
203:                 throw new BusinessException(
204:                     'توجد أصناف تغيّر رصيدها بعد عدّها وتحتاج إعادة عد قبل الاعتماد.',
205:                     ['recount_item_ids' => $staleItemIds, 'recount_variant_ids' => $staleVariantIds],
206:                 );
207:             }
208: 
209:             foreach ($stocktake->items as $item) {
210:                 $difference = (float) $item->difference;
211: 
212:                 if ($difference === 0.0) {
213:                     continue;
214:                 }
215: 
216:                 $key = $this->inventory->levelKey([
217:                     'product_variant_id' => $item->product_variant_id,
218:                     'branch_id' => $stocktake->branch_id, 'location_id' => $stocktake->location_id,
219:                 ]);
220: 
221:                 $this->inventory->recordMovement([
222:                     'product_variant_id' => $item->product_variant_id,
223:                     'branch_id' => $stocktake->branch_id,
224:                     'location_id' => $stocktake->location_id,
225:                     'type' => $difference > 0 ? StockMovementType::StocktakeGain : StockMovementType::StocktakeLoss,
226:                     'affected_bucket' => StockBucket::OnHand,
227:                     'quantity' => $difference,
228:                     'unit_cost' => $item->variant?->cost_price,
229:                     'reference_type' => Stocktake::class,
230:                     'reference_id' => $stocktake->id,
231:                     'created_by' => $userId,
232:                     'notes' => 'تسوية جرد '.$stocktake->stocktake_number,
233:                 ], $levels[$key] ?? null);
234:             }
235: 
236:             $stocktake->update([
237:                 'status' => StocktakeStatus::Approved,
238:                 'approved_by' => $userId,
239:                 'approved_at' => now(),
240:             ]);
241: 
242:             return $stocktake->load(['items.variant', 'branch', 'location']);
243:         });
244:     }
