267:     /**
268:      * تسجيل العناصر مع لقطة system_qty من الرصيد الحالي في نطاق الجلسة.
269:      *
270:      * @param  list<array{product_variant_id: int, counted_qty?: float|int|string|null}>  $items
271:      */
272:     private function syncItems(Stocktake $stocktake, array $items): void
273:     {
274:         $levels = $this->snapshotLevels($stocktake, $items);
275:         $snapshotMovementId = (int) StockMovement::query()->max('id');
276:         foreach ($items as $item) {
277:             $level = $levels->get($item['product_variant_id']);
278: 
279:             $stocktake->items()->create([
280:                 'product_variant_id' => $item['product_variant_id'],
281:                 'system_qty' => $level ? (float) $level->on_hand : 0,
282:                 'snapshot_movement_id' => $snapshotMovementId,
283:                 'counted_qty' => $item['counted_qty'] ?? null,
284:             ]);
285:         }
286:     }
