288:     /**
289:      * تحديث جزئي لعناصر جرد قائم (M-4): upsert للعناصر المرسلة فقط دون حذف
290:      * الغائبين — تسجيل عدّ صنف واحد لا يتطلب إعادة إرسال قائمة الجلسة كاملة،
291:      * والجلسات الأكبر من حد الحمولة (500) تُبنى عبر دفعات متتالية هنا.
292:      *
293:      * @param  list<array{product_variant_id: int, counted_qty?: float|int|string|null, recount?: bool|null}>  $items
294:      */
295:     public function upsertSomeItems(Stocktake $stocktake, array $items, int $userId): Stocktake
296:     {
297:         return DB::transaction(function () use ($stocktake, $items, $userId): Stocktake {
298:             $stocktake = Stocktake::query()->lockForUpdate()->findOrFail($stocktake->id);
299:             $this->assertEditable($stocktake);
300:             app(BranchAccess::class)->assertBranch($userId, $stocktake->branch_id);
301: 
302:             $this->upsertItems($stocktake, $items, deleteAbsent: false);
303:             $stocktake->touch();
304: 
305:             return $stocktake->load(['items.variant', 'branch', 'location', 'creator']);
306:         });
307:     }
