309:     public function scan(Stocktake $stocktake, int $variantId, int $qty, int $userId): StocktakeItem
310:     {
311:         return DB::transaction(function () use ($stocktake, $variantId, $qty, $userId) {
312:             $stocktake = Stocktake::query()->lockForUpdate()->findOrFail($stocktake->id);
313:             app(BranchAccess::class)->assertBranch($userId, (int) $stocktake->branch_id);
314:             if ($stocktake->status !== StocktakeStatus::InProgress || $qty < 1) {
315:                 throw new BusinessException('جلسة الجرد ليست قيد التنفيذ أو الكمية غير صالحة.');
316:             }
317:             $item = $stocktake->items()->where('product_variant_id', $variantId)->first();
318:             $count = (float) ($item?->counted_qty ?? 0) + $qty;
319:             $this->upsertItems($stocktake, [['product_variant_id' => $variantId, 'counted_qty' => $count]], deleteAbsent: false);
320: 
321:             return $stocktake->items()->where('product_variant_id', $variantId)->firstOrFail();
322:         });
323:     }
