325:     /**
326:      * تحديث عناصر جرد قائم بدون كسر ربط اللقطة بلحظة العد:
327:      * - عنصر جديد يُنشأ بلقطة الآن.
328:      * - لقطة عنصر قائم لا تتجدد إلا إذا سُجّل counted_qty أو تغيّر، أو أُرسل recount=true.
329:      * - إعادة حفظ بنفس الأعداد (الواجهة ترسل المصفوفة كاملة) لا تلمس اللقطات.
330:      * - عنصر غائب من الحمولة يُحذف من الجرد (في الاستبدال الكامل فقط).
331:      *
332:      * @param  list<array{product_variant_id: int, counted_qty?: float|int|string|null, recount?: bool|null}>  $items
333:      */
334:     private function upsertItems(Stocktake $stocktake, array $items, bool $deleteAbsent = true): void
335:     {
336:         $existing = $stocktake->items()->get()->keyBy('product_variant_id');
337:         $levels = $this->snapshotLevels($stocktake, $items);
338:         $snapshotMovementId = (int) StockMovement::query()->max('id');
339: 
340:         $keepIds = [];
341:         foreach ($items as $item) {
342:             $variantId = (int) $item['product_variant_id'];
343:             $currentOnHand = $levels->get($variantId) ? (float) $levels->get($variantId)->on_hand : 0.0;
344:             $row = $existing->get($variantId);
345: 
346:             if ($row === null) {
347:                 $created = $stocktake->items()->create([
348:                     'product_variant_id' => $variantId,
349:                     'system_qty' => $currentOnHand,
350:                     'snapshot_movement_id' => $snapshotMovementId,
351:                     'counted_qty' => $item['counted_qty'] ?? null,
352:                 ]);
353:                 $keepIds[] = $created->id;
354: 
355:                 continue;
356:             }
357: 
358:             $keepIds[] = $row->id;
359:             $updates = [];
360: 
361:             if (array_key_exists('counted_qty', $item)) {
362:                 $updates['counted_qty'] = $item['counted_qty'];
363: 
364:                 $countChanged = $item['counted_qty'] !== null
365:                     && ($row->counted_qty === null || (float) $item['counted_qty'] !== (float) $row->counted_qty);
366: 
367:                 if ($countChanged || ! empty($item['recount'])) {
368:                     $updates['system_qty'] = $currentOnHand;
369:                     $updates['snapshot_movement_id'] = $snapshotMovementId;
370:                 }
371:             } elseif (! empty($item['recount'])) {
372:                 $updates['system_qty'] = $currentOnHand;
373:                 $updates['snapshot_movement_id'] = $snapshotMovementId;
374:             }
375: 
376:             if ($updates !== []) {
377:                 $row->update($updates);
378:             }
379:         }
380: 
381:         if ($deleteAbsent) {
382:             $stocktake->items()->whereNotIn('id', $keepIds)->delete();
383:         }
384:     }
385: 
386:     private function snapshotLevels(Stocktake $stocktake, array $items): Collection
387:     {
388:         return $this->inventory->lockLevels(array_map(fn ($item) => [
389:             'branch_id' => $stocktake->branch_id, 'location_id' => $stocktake->location_id,
390:             'product_variant_id' => $item['product_variant_id'],
391:         ], $items))->keyBy('product_variant_id');
392:     }
