 36:     public function paginate(array $filters): LengthAwarePaginator
 37:     {
 38:         return StockTransfer::query()
 39:             ->when($filters['staff_branch_id'] ?? null, fn ($q, $branch) => $q->where(fn ($scope) => $scope->where('from_branch_id', $branch)->orWhere('to_branch_id', $branch)))
 40:             ->with(['fromBranch', 'toBranch', 'creator'])
 41:             ->when($filters['from_branch_id'] ?? null, fn ($q, $v) => $q->where('from_branch_id', $v))
 42:             ->when($filters['to_branch_id'] ?? null, fn ($q, $v) => $q->where('to_branch_id', $v))
 43:             ->when($filters['status'] ?? null, fn ($q, $v) => $q->where('status', $v))
 44:             ->orderByDesc('id')
 45:             ->paginate($filters['per_page'] ?? 15);
