 81:     private function doCreate(array $data, int $userId, bool $incoming = false): StockTransfer
 82:     {
 83:         return DB::transaction(function () use ($data, $userId, $incoming): StockTransfer {
 84:             app(BranchAccess::class)->assertBranch($userId, (int) $data[$incoming ? 'to_branch_id' : 'from_branch_id']);
 85:             $transfer = StockTransfer::query()->create([
 86:                 'transfer_number' => $this->settings->generateNextNumber('transfer'),
 87:                 'from_branch_id' => $data['from_branch_id'],
