100:     public function update(StockTransfer $transfer, array $data, int $userId): StockTransfer
101:     {
102:         return DB::transaction(function () use ($transfer, $data, $userId): StockTransfer {
103:             $transfer = StockTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
104:             $this->assertStatus($transfer, TransferStatus::Draft, 'التعديل');
105:             app(BranchAccess::class)->assertBranch($userId, $transfer->from_branch_id);
106:             app(BranchAccess::class)->assertBranch($userId, (int) ($data['from_branch_id'] ?? $transfer->from_branch_id));
107: 
108:             $fromBranch = $data['from_branch_id'] ?? $transfer->from_branch_id;
109:             $toBranch = $data['to_branch_id'] ?? $transfer->to_branch_id;
110:             if ((int) $fromBranch === (int) $toBranch) {
111:                 throw new BusinessException('يجب اختلاف الفرع المرسل عن الفرع المستلم.');
112:             }
113:             $items = $data['items'] ?? $transfer->items->toArray();
114:             foreach ($items as $item) {
115:                 foreach (['from_location_id' => $fromBranch, 'to_location_id' => $toBranch] as $field => $branchId) {
116:                     if (isset($item[$field]) && ! Location::query()->whereKey($item[$field])->where('branch_id', $branchId)->exists()) {
117:                         throw new BusinessException('موقع التحويل لا يتبع الفرع المحدد.');
118:                     }
119:                 }
120:             }
121: 
122:             $transfer->update([
123:                 'from_branch_id' => $data['from_branch_id'] ?? $transfer->from_branch_id,
124:                 'to_branch_id' => $data['to_branch_id'] ?? $transfer->to_branch_id,
125:                 'notes' => array_key_exists('notes', $data) ? $data['notes'] : $transfer->notes,
126:             ]);
127: 
128:             if (isset($data['items'])) {
129:                 $transfer->items()->delete();
130:                 $this->syncItems($transfer, $data['items']);
131:             }
132: 
133:             return $transfer->load(['items.variant', 'fromBranch', 'toBranch', 'creator']);
134:         });
135:     }
