137:     /** الاعتماد: حجز الكميات المعتمدة في الفرع المرسل حتى لا تُباع قبل الشحن. */
138:     public function approve(StockTransfer $transfer, array $itemsPayload, int $userId, ?string $expectedUpdatedAt = null, ?int $expectedVersion = null): StockTransfer
139:     {
140:         return DB::transaction(function () use ($transfer, $itemsPayload, $userId, $expectedUpdatedAt, $expectedVersion): StockTransfer {
141:             $transfer = StockTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
142:             $transfer->load('items.variant');
143:             app(BranchAccess::class)->assertBranch($userId, $transfer->from_branch_id);
144:             $this->assertPayloadMatchesLockedItems($transfer, $itemsPayload, $expectedUpdatedAt, $expectedVersion);
145:             $this->assertStatus($transfer, TransferStatus::Draft, 'الاعتماد');
146:             if ($transfer->items->sum(fn ($item) => (float) ($itemsPayload[$item->id] ?? $item->requested_qty)) <= 0) {
147:                 throw new BusinessException('يجب اعتماد كمية موجبة واحدة على الأقل؛ يمكن إلغاء التحويل بدلًا من اعتماده بصفر.');
148:             }
149:             $levels = $this->lockTransferLevels($transfer, true, false);
150:             $qtyUpdates = [];
151: 
152:             foreach ($transfer->items as $item) {
153:                 $approvedQty = (float) ($itemsPayload[$item->id] ?? $item->requested_qty);
154: 
155:                 if ($approvedQty < 0 || $approvedQty > (float) $item->requested_qty) {
156:                     throw new BusinessException('الكمية المعتمدة يجب أن تكون بين صفر والكمية المطلوبة.');
157:                 }
158: 
159:                 // تحديثات البنود تتجمع في UPDATE واحد بعد الحلقة (M-6) — الأقفال
160:                 // مأخوذة طوال العملية، فتقليل الاستعلامات يقلل زمن احتجازها.
161:                 // الصف يُمرَّر كاملًا بحالته الحالية: PostgreSQL يتحقق من قيود
162:                 // NOT NULL وCHECK على الصف المقترح في upsert قبل حل التعارض.
163:                 $qtyUpdates[] = [...$item->only(['id', 'stock_transfer_id', 'product_variant_id', 'from_location_id', 'to_location_id', 'requested_qty', 'approved_qty', 'shipped_qty', 'received_qty', 'created_at']), 'approved_qty' => $approvedQty, 'updated_at' => now()];
164: 
165:                 if ($approvedQty > 0) {
166:                     $this->move([
167:                         'product_variant_id' => $item->product_variant_id,
168:                         'branch_id' => $transfer->from_branch_id,
169:                         'location_id' => $item->from_location_id,
170:                         'type' => StockMovementType::Reserve,
171:                         'affected_bucket' => StockBucket::Reserved,
172:                         'quantity' => $approvedQty,
173:                         'unit_cost' => $item->variant?->cost_price,
174:                         'reference_type' => StockTransfer::class,
175:                         'reference_id' => $transfer->id,
176:                         'created_by' => $userId,
177:                         'notes' => 'حجز لصالح تحويل '.$transfer->transfer_number,
178:                     ], $levels);
179:                 }
180:             }
181: 
182:             if ($qtyUpdates !== []) {
183:                 StockTransferItem::query()->upsert($qtyUpdates, ['id'], ['approved_qty', 'updated_at']);
184:             }
185: 
186:             $transfer->update(['status' => TransferStatus::Approved, 'approved_by' => $userId]);
187: 
188:             return $transfer->load(['items.variant', 'fromBranch', 'toBranch']);
189:         });
