240:                     'unit_cost' => $item->variant?->cost_price,
241:                     'reference_type' => StockTransfer::class,
242:                     'reference_id' => $transfer->id,
243:                     'created_by' => $userId,
244:                 ];
245: 
246:                 // المرسل: فك الحجز ثم إخراج فعلي
247:                 $this->move([...$base,
248:                     'branch_id' => $transfer->from_branch_id,
249:                     'location_id' => $item->from_location_id,
250:                     'type' => StockMovementType::ReleaseReserve,
251:                     'affected_bucket' => StockBucket::Reserved,
252:                     'quantity' => -$shippedQty,
253:                     'notes' => 'فك حجز عند شحن تحويل '.$transfer->transfer_number,
254:                 ], $levels);
255:                 $this->move([...$base,
256:                     'branch_id' => $transfer->from_branch_id,
257:                     'location_id' => $item->from_location_id,
258:                     'type' => StockMovementType::TransferOut,
259:                     'affected_bucket' => StockBucket::OnHand,
260:                     'quantity' => -$shippedQty,
261:                     'notes' => 'شحن تحويل '.$transfer->transfer_number,
262:                 ], $levels);
263: 
264:                 // الباقي المحجوز (معتمد ولم يُشحن) يرجع متاحًا للبيع
265:                 $unshipped = round((float) $item->approved_qty - $shippedQty, 4);
266:                 if ($unshipped > 0) {
267:                     $this->move([...$base,
268:                         'branch_id' => $transfer->from_branch_id,
269:                         'location_id' => $item->from_location_id,
270:                         'type' => StockMovementType::ReleaseReserve,
271:                         'affected_bucket' => StockBucket::Reserved,
272:                         'quantity' => -$unshipped,
273:                         'notes' => 'فك حجز الكمية المعتمدة غير المشحونة من تحويل '.$transfer->transfer_number,
274:                     ], $levels);
275:                 }
276: 
277:                 // المستلم: بضاعة في الطريق
278:                 $this->move([...$base,
279:                     'branch_id' => $transfer->to_branch_id,
280:                     'location_id' => $item->to_location_id,
281:                     'type' => StockMovementType::TransferInTransit,
282:                     'affected_bucket' => StockBucket::InTransit,
283:                     'quantity' => $shippedQty,
284:                     'notes' => 'بضاعة في الطريق من تحويل '.$transfer->transfer_number,
285:                 ], $levels);
286:             }
287: 
288:             if ($qtyUpdates !== []) {
289:                 StockTransferItem::query()->upsert($qtyUpdates, ['id'], ['shipped_qty', 'updated_at']);
290:             }
291: 
292:             $transfer->update(['status' => TransferStatus::Shipped, 'shipped_at' => now()]);
293: 
294:             return $transfer->load(['items.variant', 'fromBranch', 'toBranch']);
295:         });
296:     }
297: 
298:     /** الاستلام: تسوية in_transit بالكامل، وإضافة المستلم فعليًا، وتسوية أي عجز كحركة مستقلة. */
299:     public function receive(StockTransfer $transfer, array $itemsPayload, int $userId, ?string $expectedUpdatedAt = null, ?int $expectedVersion = null): StockTransfer
300:     {
301:         return DB::transaction(function () use ($transfer, $itemsPayload, $userId, $expectedUpdatedAt, $expectedVersion): StockTransfer {
302:             $transfer = StockTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
303:             $transfer->load('items.variant');
304:             app(BranchAccess::class)->assertBranch($userId, $transfer->to_branch_id);
305:             if ($transfer->status === TransferStatus::Received) {
306:                 return $this->replayCompletedStage($transfer, $itemsPayload, 'received_qty');
307:             }
308:             $this->assertPayloadMatchesLockedItems($transfer, $itemsPayload, $expectedUpdatedAt, $expectedVersion);
309:             $this->assertStatus($transfer, TransferStatus::Shipped, 'الاستلام');
310:             $levels = $this->lockTransferLevels($transfer, false, true);
311: 
312:             $shortageNotes = [];
313:             $qtyUpdates = [];
314: 
315:             foreach ($transfer->items as $item) {
316:                 $receivedQty = (float) ($itemsPayload[$item->id] ?? $item->shipped_qty);
317:                 $shippedQty = (float) $item->shipped_qty;
318: 
319:                 if ($receivedQty < 0 || $receivedQty > $shippedQty) {
320:                     throw new BusinessException('الكمية المستلمة يجب أن تكون بين صفر والكمية المشحونة.');
321:                 }
322: 
323:                 $qtyUpdates[] = [...$item->only(['id', 'stock_transfer_id', 'product_variant_id', 'from_location_id', 'to_location_id', 'requested_qty', 'approved_qty', 'shipped_qty', 'received_qty', 'created_at']), 'received_qty' => $receivedQty, 'updated_at' => now()];
324: 
325:                 if ($shippedQty <= 0) {
326:                     continue;
327:                 }
328: 
329:                 $base = [
330:                     'product_variant_id' => $item->product_variant_id,
331:                     'branch_id' => $transfer->to_branch_id,
332:                     'location_id' => $item->to_location_id,
333:                     'unit_cost' => $item->variant?->cost_price,
334:                     'reference_type' => StockTransfer::class,
335:                     'reference_id' => $transfer->id,
336:                     'created_by' => $userId,
337:                 ];
338: 
339:                 // خروج الجزء المستلم من "في الطريق" ودخوله الرصيد الفعلي
340:                 if ($receivedQty > 0) {
341:                     $this->move([...$base,
342:                         'type' => StockMovementType::TransferTransitRelease,
343:                         'affected_bucket' => StockBucket::InTransit,
344:                         'quantity' => -$receivedQty,
345:                         'notes' => 'استلام تحويل '.$transfer->transfer_number,
346:                     ], $levels);
347:                     $this->move([...$base,
348:                         'type' => StockMovementType::TransferIn,
349:                         'affected_bucket' => StockBucket::OnHand,
350:                         'quantity' => $receivedQty,
351:                         'notes' => 'استلام تحويل '.$transfer->transfer_number,
352:                     ], $levels);
353:                 }
354: 
355:                 // العجز بين المشحون والمستلم: تسوية مستقلة موثقة من رصيد "في الطريق"
356:                 $shortage = round($shippedQty - $receivedQty, 4);
357:                 if ($shortage > 0) {
358:                     $this->move([...$base,
359:                         'type' => StockMovementType::TransferShortage,
360:                         'affected_bucket' => StockBucket::InTransit,
361:                         'quantity' => -$shortage,
362:                         'notes' => 'عجز عند استلام تحويل '.$transfer->transfer_number,
363:                     ], $levels);
364:                     $shortageNotes[] = "عجز {$shortage} وحدة في المتغير #{$item->product_variant_id}";
365:                 }
366:             }
367: 
368:             if ($qtyUpdates !== []) {
369:                 StockTransferItem::query()->upsert($qtyUpdates, ['id'], ['received_qty', 'updated_at']);
370:             }
371: 
372:             $notes = $transfer->notes;
373:             if ($shortageNotes !== []) {
374:                 $notes = trim(($notes ? $notes.' | ' : '').implode('؛ ', $shortageNotes));
375:             }
376: 
377:             $transfer->update(['status' => TransferStatus::Received, 'received_at' => now(), 'notes' => $notes]);
378: 
379:             return $transfer->load(['items.variant', 'fromBranch', 'toBranch']);
380:         });
381:     }
382: 
383:     /** الإلغاء: من المسودة مباشرة، ومن المعتمد بعد فك الحجز. المشحون لا يُلغى (يُستلم). */
384:     public function cancel(StockTransfer $transfer, int $userId): StockTransfer
385:     {
386:         return DB::transaction(function () use ($transfer, $userId): StockTransfer {
387:             $transfer = StockTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
388:             $transfer->load('items.variant');
389:             app(BranchAccess::class)->assertBranch($userId, $transfer->from_branch_id);
390: 
391:             if ($transfer->status === TransferStatus::Approved) {
392:                 $levels = $this->lockTransferLevels($transfer, true, false);
393:                 foreach ($transfer->items as $item) {
394:                     if ((float) $item->approved_qty <= 0) {
395:                         continue;
396:                     }
397: 
398:                     $this->move([
399:                         'product_variant_id' => $item->product_variant_id,
400:                         'branch_id' => $transfer->from_branch_id,
401:                         'location_id' => $item->from_location_id,
402:                         'type' => StockMovementType::ReleaseReserve,
403:                         'affected_bucket' => StockBucket::Reserved,
404:                         'quantity' => -(float) $item->approved_qty,
405:                         'reference_type' => StockTransfer::class,
406:                         'reference_id' => $transfer->id,
407:                         'created_by' => $userId,
408:                         'notes' => 'فك حجز عند إلغاء تحويل '.$transfer->transfer_number,
409:                     ], $levels);
410:                 }
411:             } elseif ($transfer->status !== TransferStatus::Draft) {
412:                 throw new BusinessException('لا يمكن إلغاء تحويل بحالة '.$transfer->status->value.'.');
413:             }
414: 
415:             $transfer->update(['status' => TransferStatus::Cancelled]);
416: 
417:             return $transfer->load(['items.variant', 'fromBranch', 'toBranch']);
418:         });
419:     }
420: 
421:     public function delete(StockTransfer $transfer, int $userId): void
422:     {
423:         DB::transaction(function () use ($transfer, $userId): void {
424:             $transfer = StockTransfer::query()->lockForUpdate()->findOrFail($transfer->id);
425:             app(BranchAccess::class)->assertBranch($userId, $transfer->from_branch_id);
426: 
427:             if (! in_array($transfer->status, [TransferStatus::Draft, TransferStatus::Cancelled], true)) {
428:                 throw new BusinessException('لا يمكن حذف تحويل إلا في حالة المسودة أو الملغي.');
429:             }
430: 
431:             // تحويل اعتُمد ثم أُلغي له حركات دفتر (حجز/فك حجز) تشير إليه بلا FK؛
432:             // حذفه يترك مراجع يتيمة ويقطع أثر التدقيق — الإلغاء نفسه هو الحفظ الصحيح.
433:             if (StockMovement::query()->whereIn('reference_type', [StockTransfer::class, 'stock_transfer'])->where('reference_id', $transfer->id)->exists()) {
434:                 throw new BusinessException('لا يمكن حذف تحويل له حركات مخزون مسجلة في الدفتر؛ إلغاؤه يحفظ أثر التدقيق.');
435:             }
436: 
437:             $transfer->delete();
438:         });
439:     }
440: 
441:     /**
442:      * حماية من الحمولات القديمة: أي معرّف عنصر لا يتبع التحويل المقفول يُرفض بدل
443:      * تجاهله بصمت (التعديل بين تحقق الطلب والقفل كان يبدّل المعرّفات)، وطابع
444:      * expected_updated_at الاختياري يمنع اعتماد نسخة لم يراجعها المعتمد.
445:      */
446:     private function assertPayloadMatchesLockedItems(StockTransfer $transfer, array $itemsPayload, ?string $expectedUpdatedAt, ?int $expectedVersion = null): void
447:     {
448:         if ($expectedVersion !== null && $expectedVersion !== $transfer->version) {
449:             throw new BusinessException('تم تعديل التحويل؛ أعد تحميله وراجع الكميات.', ['current_version' => $transfer->version], 409);
450:         }
451: 
452:         $unknownIds = array_diff(array_map('intval', array_keys($itemsPayload)), $transfer->items->pluck('id')->map(fn ($id) => (int) $id)->all());
453: 
454:         if ($unknownIds !== []) {
455:             throw new BusinessException(
456:                 'توجد عناصر في الطلب لا تتبع هذا التحويل (المعرّفات: '.implode(', ', $unknownIds).'). أعد تحميل التحويل وراجع الكميات.',
457:                 ['unknown_item_ids' => array_values($unknownIds)],
458:                 409,
459:             );
460:         }
461: 
462:         if ($expectedUpdatedAt !== null
463:             && ! Carbon::parse($expectedUpdatedAt)->equalTo($transfer->updated_at)) {
464:             throw new BusinessException(
465:                 'تم تعديل هذا التحويل بعد تحميله. أعد تحميله وراجع الكميات قبل التنفيذ.',
466:                 ['current_updated_at' => $transfer->updated_at->toIso8601String()],
467:                 409,
468:             );
469:         }
470:     }
471: 
472:     private function replayCompletedStage(StockTransfer $transfer, array $itemsPayload, string $quantityField): StockTransfer
473:     {
474:         $this->assertPayloadMatchesLockedItems($transfer, $itemsPayload, null);
475:         foreach ($transfer->items as $item) {
476:             if (array_key_exists($item->id, $itemsPayload)
477:                 && (int) round((float) $itemsPayload[$item->id] * 10000) !== (int) round((float) $item->{$quantityField} * 10000)) {
478:                 throw new BusinessException('تم تنفيذ المرحلة بكميات مختلفة؛ أعد تحميل التحويل.', [], 409);
479:             }
480:         }
481: 
482:         return $transfer->load(['fromBranch', 'toBranch']);
483:     }
484: 
485:     private function assertStatus(StockTransfer $transfer, TransferStatus $expected, string $action): void
486:     {
487:         if ($transfer->status !== $expected) {
488:             throw new BusinessException("لا يمكن تنفيذ {$action} على تحويل بحالة {$transfer->status->value}.");
489:         }
490:     }
