492:     /**
493:      * @param  list<array{product_variant_id: int, from_location_id?: int|null, to_location_id?: int|null, requested_qty: float|int|string}>  $items
494:      */
495:     private function syncItems(StockTransfer $transfer, array $items): void
496:     {
497:         $this->assertDistinctItems($items);
498:         foreach ($items as $item) {
499:             $transfer->items()->create([
500:                 'product_variant_id' => $item['product_variant_id'],
501:                 'from_location_id' => $item['from_location_id'] ?? null,
502:                 'to_location_id' => $item['to_location_id'] ?? null,
503:                 'requested_qty' => $item['requested_qty'],
504:             ]);
505:         }
506:     }
507: 
508:     private function assertDistinctItems(array $items): void
509:     {
510:         $keys = array_map(fn ($item) => $item['product_variant_id'].':'.($item['from_location_id'] ?? 0).':'.($item['to_location_id'] ?? 0), $items);
511:         if (count(array_unique($keys)) !== count($keys)) {
512:             throw new BusinessException('لا يجوز تكرار نفس الصنف وموقعي الإرسال والاستلام داخل التحويل.');
513:         }
514:     }
515: 
516:     /** حركة على صف مقفول مسبقًا ضمن $levels — بلا إعادة قفل أو فحص موقع. */
517:     private function move(array $data, Collection $levels): void
518:     {
519:         $level = $levels->get($this->inventory->levelKey([
520:             'product_variant_id' => $data['product_variant_id'],
521:             'branch_id' => $data['branch_id'],
522:             'location_id' => $data['location_id'] ?? null,
523:         ]));
524: 
525:         $this->inventory->recordMovement($data, $level);
526:     }
527: 
528:     private function lockTransferLevels(StockTransfer $transfer, bool $source, bool $destination): Collection
529:     {
530:         $keys = [];
531:         foreach ($transfer->items as $item) {
532:             if ($source) {
533:                 $keys[] = ['branch_id' => $transfer->from_branch_id, 'location_id' => $item->from_location_id, 'product_variant_id' => $item->product_variant_id];
534:             }
535:             if ($destination) {
536:                 $keys[] = ['branch_id' => $transfer->to_branch_id, 'location_id' => $item->to_location_id, 'product_variant_id' => $item->product_variant_id];
537:             }
538:         }
539: 
540:         return $this->inventory->lockLevels($keys);
541:     }
