372: 
373:         return DB::transaction(function () use ($order, $to, $actor, $notes, $expectedFrom, $returnEffects): Order {
374:             // إعادة قراءة الطلب بقفل صف: النسخة الممرَّرة قد تكون قديمة،
375:             // وكل الانتقالات على نفس الطلب يجب أن تتسلسل (C1)
376:             $order = Order::query()->lockForUpdate()->findOrFail($order->id);
377:             $from = $order->status;
378: 
379:             if ($expectedFrom !== null && ! in_array($from, $expectedFrom, true)) {
380:                 throw new BusinessException("تغيّرت حالة الطلب أثناء العملية (أصبحت {$from->value})؛ أعد المحاولة.");
381:             }
382: 
383:             if ($from === $to) {
384:                 return $order;
385:             }
386: 
387:             if (! in_array($to->value, self::TRANSITIONS[$from->value] ?? [], true)) {
388:                 throw new BusinessException("انتقال حالة غير مسموح: من ({$from->value}) إلى ({$to->value}).");
389:             }
390: 
391:             $actorId = $this->inventoryActorId($actor);
392:             if ($order->channel === 'pos' && $to === OrderStatus::Returned) {
393:                 throw new BusinessException('مرتجع نقطة البيع يجب تنفيذه من وردية مفتوحة لضمان تسوية المخزون والخزينة.');
394:             }
395:             if ($order->payment_method === 'credit' && ($to === OrderStatus::Cancelled || ($to === OrderStatus::Returned && $returnEffects))) {
396:                 app(WholesaleService::class)->reverseCredit($order);
397:             }
398: 
399:             if ($to === OrderStatus::Returned && $returnEffects
400:                 && ReturnRequest::query()->where('order_id', $order->id)->whereNotIn('status', [
401:                     ReturnStatus::Rejected->value, ReturnStatus::Cancelled->value,
402:                 ])->exists()) {
403:                 throw new BusinessException('للطلب مرتجعات قائمة؛ أكمل الاستلام والاسترداد من إدارة المرتجعات لمنع تكرار المخزون.');
404:             }
405: 
406:             // آثار المخزون بحسب الانتقال
407:             $extraNote = null;
408:             if ($to === OrderStatus::Shipped) {
409:                 $this->shipOrder($order, $actorId);
410:             } elseif ($to === OrderStatus::Cancelled
411:                 && in_array($from, [OrderStatus::Pending, OrderStatus::Confirmed, OrderStatus::Processing], true)) {
412:                 // الحجز صار من لحظة الإنشاء (F-01) فيُفك من Pending أيضًا
413:                 $this->releaseReservations($order, $actorId, 'إلغاء الطلب');
414:             } elseif ($to === OrderStatus::Returned
415:                 && in_array($from, [OrderStatus::Shipped, OrderStatus::Delivered], true)
416:                 && $returnEffects) {
417:                 // إعادة البضاعة المشحونة للمخزون بحركات sale_return (M13) —
418:                 // تُتخطى في مسار RMA لأن الاستلام الفعلي سوّاها بالفعل (مرحلة 9)
419:                 if (! $this->returnSalesToStock($order, $actorId)) {
420:                     $extraNote = 'لا توجد حركات بيع مسجلة؛ يتطلب المرتجع استلامًا يدويًا في المستودع.';
421:                 }
422:             }
423: 
424:             if ($to === OrderStatus::Cancelled) {
425:                 // عكس استخدام الكوبون حتى لا يُحرم العميل منه بإلغاء (M13)
426:                 $this->reverseCouponUsage($order);
427:                 if ($order->payment_status === 'paid') {
428:                     $order->update(['requires_refund' => true]);
429:                 }
430:             }
431: 
432:             // مرتجع لطلب مدفوع يحتاج استردادًا أيضًا، لا الإلغاء فقط (F-14) —
433:             // في مسار RMA الاسترداد اكتمل داخل طلب المرتجع نفسه فلا علم هنا
434:             if ($to === OrderStatus::Returned && $order->payment_status === 'paid' && $returnEffects) {
435:                 $order->update(['requires_refund' => true]);
436:             }
437: 
438:             if ($order->payment_method === 'wallet' && $order->payment_status === 'paid'
439:                 && ($to === OrderStatus::Cancelled || ($to === OrderStatus::Returned && $returnEffects))) {
440:                 $payment = CustomerWalletTransaction::query()->where('reference_type', 'order')->where('reference_id', $order->id)
441:                     ->where('type', 'checkout_payment')->first();
442:                 if ($payment !== null) {
443:                     app(WalletService::class)->record($payment->customer_id, -(float) $payment->amount,
444:                         'order_reversal', 'order', $order->id, $actorId);
445:                     $order->update(['payment_status' => 'refunded', 'requires_refund' => false]);
446:                 }
447:             }
448: 
449:             $order->update(['status' => $to]);
450: 
451:             // تسوية COD عند التسليم من أي مسار (أدمن يدوي أو ويب هوك) —
452:             // الأثر هنا في بوابة الحالة لا في ويب هوك الشحن فقط (F-14)
453:             if ($to === OrderStatus::Delivered
454:                 && $order->payment_method === 'cod'
455:                 && $order->payment_status !== 'paid') {
456:                 $order->update(['payment_status' => 'paid']);
457:             }
458: 
459:             // notes عمود varchar(500): ملاحظة الأدمن (حتى 500) مع الملحق قد
460:             // تتجاوزه فتنفجر بحركة إرجاع بلا حركات بيع — تُقصّ على 500 (F-28)
461:             $historyNotes = trim(($notes ?? '').($extraNote !== null ? ' — '.$extraNote : '')) ?: $notes;
462: 
463:             $order->statusHistories()->create([
464:                 'from_status' => $from,
465:                 'to_status' => $to,
466:                 'changed_by_type' => $actor?->getMorphClass(),
467:                 'changed_by_id' => $actor?->getKey(),
468:                 'notes' => $historyNotes !== null ? mb_substr($historyNotes, 0, 500) : null,
469:             ]);
470: 
471:             // التوزيع ناقص إن غاب فرع الطلب أو بقي بند بلا فرع: الاعتماد على
472:             // allocated_branch_id وحده يفشل عندما تُوزَّع البنود في فروع
473:             // مختلفة فيبقى حقل الطلب فارغًا (F1)
474:             if ($to === OrderStatus::Confirmed && ! $this->isAllocated($order)) {
475:                 $this->allocationService->allocate($order, performedBy: $actorId);
476:             }
477: 
478:             return $order->fresh(['items', 'statusHistories']);
479:         });
480:     }
481: 
482:     /**
483:      * كفاية التوزيع: يكفي أن يكون لفرع الطلب قيمة أو أن يكون كل بند موزّعًا
484:      * فعليًا في فرع ما (F1) — التوزيع الجزئي (بند بلا فرع) يُعيد الاستدعاء.
485:      */
486:     private function isAllocated(Order $order): bool
487:     {
488:         if ($order->allocated_branch_id !== null) {
489:             return true;
490:         }
491: 
492:         $distribution = $order->items()
493:             ->selectRaw('COUNT(*) AS total, COUNT(allocated_branch_id) AS allocated')
494:             ->first();
495: 
496:         if ($distribution === null || (int) $distribution->total === 0) {
497:             return false;
498:         }
499: 
500:         return (int) $distribution->total === (int) $distribution->allocated;
501:     }
502: 
503:     /** عميل جملة/توزيع معتمد — يُستثنى من سقوف التجزئة (H2). */
504:     private function isWholesaleApproved(?Customer $customer): bool
505:     {
506:         return $customer !== null
507:             && $customer->status === CustomerStatus::Approved
508:             && in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true);
509:     }
510: 
511:     /**
512:      * توزيع مبلغ على أوزان بطريقة «أكبر باقٍ» بعدد صحيح من القروش (L5):
513:      * مجموع الحصص يساوي المبلغ بالضبط، ولا حصة سالبة بسبب التقريب.
514:      *
515:      * @param  array<int, float>  $weights
516:      * @return array<int, float>
517:      */
518:     private function distributeLargestRemainder(float $total, array $weights): array
519:     {
520:         $count = count($weights);
521:         if ($count === 0) {
522:             return [];
523:         }
524:         $totalCents = (int) round($total * 100);
525:         $weightSum = array_sum($weights);
526:         if ($totalCents <= 0 || $weightSum <= 0) {
527:             return array_fill(0, $count, 0.0);
528:         }
529: 
530:         $floorCents = [];
531:         $remainders = [];
532:         $assigned = 0;
533:         foreach ($weights as $i => $weight) {
534:             $exact = $totalCents * ((float) $weight / $weightSum);
535:             $floor = (int) floor($exact);
536:             $floorCents[$i] = $floor;
537:             $remainders[$i] = $exact - $floor;
538:             $assigned += $floor;
539:         }
540: 
541:         $left = $totalCents - $assigned;
542:         arsort($remainders);
543:         foreach (array_keys($remainders) as $i) {
544:             if ($left <= 0) {
545:                 break;
546:             }
547:             $floorCents[$i]++;
548:             $left--;
549:         }
550: 
551:         ksort($floorCents);
552: 
553:         return array_map(fn (int $cents): float => $cents / 100, $floorCents);
554:     }
555: 
556:     /**
557:      * الشحن: لكل حركة حجز — فك الحجز من reserved وخصم فعلي sale من on_hand
558:      * على نفس صف الرصيد، وزيادة عدّاد مبيعات المنتج.
559:      */
560:     private function shipOrder(Order $order, ?int $actorId): void
561:     {
562:         $reservations = $this->reserveMovements($order);
563:         if ($reservations->isEmpty()) {
564:             throw new BusinessException('لا توجد حجوزات مخزون لهذا الطلب؛ لا يمكن الشحن قبل التأكيد والتوزيع.');
565:         }
566: 
567:         foreach ($reservations as $movement) {
568:             $base = [
569:                 'product_variant_id' => $movement->product_variant_id,
570:                 'branch_id' => $movement->branch_id,
571:                 'location_id' => $movement->location_id,
572:                 'reference_type' => Order::class,
573:                 'reference_id' => $order->id,
574:                 'created_by' => $actorId,
575:             ];
576:             $this->inventoryService->recordMovement([...$base,
577:                 'type' => StockMovementType::ReleaseReserve,
578:                 'affected_bucket' => StockBucket::Reserved,
579:                 'quantity' => -1 * (float) $movement->quantity,
580:                 'notes' => "فك حجز عند شحن الطلب {$order->order_number}",
581:             ]);
582:             $this->inventoryService->recordMovement([...$base,
583:                 'type' => StockMovementType::Sale,
584:                 'affected_bucket' => StockBucket::OnHand,
585:                 'quantity' => -1 * (float) $movement->quantity,
586:                 'notes' => "بيع عند شحن الطلب {$order->order_number}",
587:             ]);
588:         }
589: 
590:         foreach ($order->items as $item) {
591:             $item->variant?->product?->increment('sales_count', (int) round((float) $item->qty));
592:         }
593:     }
