595:     /** إلغاء طلب مُحجوز: فك كل حجوزاته فتعود الكميات متاحة للبيع. */
596:     private function releaseReservations(Order $order, ?int $actorId, string $reason): void
597:     {
598:         foreach ($this->reserveMovements($order) as $movement) {
599:             $this->inventoryService->recordMovement([
600:                 'product_variant_id' => $movement->product_variant_id,
601:                 'branch_id' => $movement->branch_id,
602:                 'location_id' => $movement->location_id,
603:                 'type' => StockMovementType::ReleaseReserve,
604:                 'affected_bucket' => StockBucket::Reserved,
605:                 'quantity' => -1 * (float) $movement->quantity,
606:                 'reference_type' => Order::class,
607:                 'reference_id' => $order->id,
608:                 'created_by' => $actorId,
609:                 'notes' => "{$reason} {$order->order_number}",
610:             ]);
611:         }
612:     }
613: 
614:     /**
615:      * إعادة بضاعة طلب مشحون/مُسلَّم إلى المخزون: لكل حركة بيع حركة
616:      * sale_return معاكسة على نفس الرصيد، وتنقيص عدّاد المبيعات (M13).
617:      * ترجع false إذا لم توجد حركات بيع (يحتاج استلامًا يدويًا).
618:      */
619:     private function returnSalesToStock(Order $order, ?int $actorId): bool
620:     {
621:         $sales = StockMovement::query()
622:             ->where('reference_type', $order->getMorphClass())
623:             ->where('reference_id', $order->id)
624:             ->where('type', StockMovementType::Sale)
625:             ->orderBy('id')
626:             ->get();
627:         if ($sales->isEmpty()) {
628:             return false;
629:         }
630: 
631:         foreach ($sales as $movement) {
632:             $this->inventoryService->recordMovement([
633:                 'product_variant_id' => $movement->product_variant_id,
634:                 'branch_id' => $movement->branch_id,
635:                 'location_id' => $movement->location_id,
636:                 'type' => StockMovementType::SaleReturn,
637:                 'affected_bucket' => StockBucket::OnHand,
638:                 'quantity' => -1 * (float) $movement->quantity,
639:                 'reference_type' => Order::class,
640:                 'reference_id' => $order->id,
641:                 'created_by' => $actorId,
642:                 'notes' => "مرتجع مبيعات للطلب {$order->order_number}",
643:             ]);
644:         }
645: 
646:         foreach ($order->items as $item) {
647:             if ($item->variant?->product_id) {
648:                 Product::query()->whereKey($item->variant->product_id)
649:                     ->update(['sales_count' => DB::raw('GREATEST(sales_count - '.(int) round((float) $item->qty).', 0)')]);
650:             }
651:         }
652: 
653:         return true;
654:     }
