656:     /** عكس تسجيل استخدام الكوبون عند إلغاء الطلب: حذف السجل وإنقاص العدّاد (M13). */
657:     private function reverseCouponUsage(Order $order): void
658:     {
659:         foreach (CouponUsage::query()->where('order_id', $order->id)->get() as $usage) {
660:             Coupon::query()->whereKey($usage->coupon_id)->where('used_count', '>', 0)->decrement('used_count');
661:             $usage->delete();
662:         }
663:     }
664: 
665:     /** حركات الحجز الأصلية للطلب من الدفتر (مصدر الحقيقة لمواضع الحجز ومواقعه). */
666:     private function reserveMovements(Order $order): Collection
667:     {
668:         return StockMovement::query()
669:             ->where('reference_type', $order->getMorphClass())
670:             ->where('reference_id', $order->id)
671:             ->where('type', StockMovementType::Reserve)
672:             ->orderBy('id')
673:             ->get();
674:     }
