682:     /**
683:      * منفّذ حركات المخزون: الموظف الفاعل نفسه؛ وعند غيابه (عميل/ويب هوك)
684:      * يُنسب التنفيذ لمستخدم النظام المخصص (M19) — لا لأول Super Admin،
685:      * حتى يبقى سجل التدقيق صادقًا. يُحسم مرة واحدة لكل نسخة خدمة.
686:      */
687:     private function inventoryActorId(?Model $actor): ?int
688:     {
689:         if ($actor instanceof User) {
690:             return (int) $actor->getKey();
691:         }
692: 
693:         if (! $this->systemActorResolved) {
694:             $this->systemActorResolved = true;
695:             $systemId = User::query()
696:                 ->where('email', (string) config('orders.system_user_email', 'system@alfarid.local'))
697:                 ->value('id');
698:             $this->systemActorId = $systemId !== null ? (int) $systemId : null;
699:         }
700:         if ($this->systemActorId !== null) {
701:             return $this->systemActorId;
702:         }
703: 
704:         // رجوع احتياطي إن لم تُزرع هجرة مستخدم النظام بعد
705:         $adminId = User::query()
706:             ->whereHas('roles', fn ($q) => $q->where('name', 'Super Admin'))
707:             ->orderBy('id')
708:             ->value('id');
709: 
710:         return $adminId !== null ? (int) $adminId : (auth()->user() instanceof User ? (int) auth()->id() : null);
711:     }
