111:             Limit::perMinute(config('auth.customer_limits.phone_ip_minute', 20))->by('phone-send-ip:'.$request->ip()),
112:             Limit::perDay(config('auth.customer_limits.phone_ip_day', 500))->by('phone-send-day:'.$request->ip()),
113:             Limit::perMinute(1)->by('phone-send-id:'.$phoneKey($request)),
114:         ]);
115:         RateLimiter::for('customer-phone-verify', fn (Request $request) => [
116:             Limit::perMinute(config('auth.customer_limits.phone_verify_ip_minute', 120))->by('phone-verify-ip:'.$request->ip()),
117:             Limit::perMinute(5)->by('phone-verify-id:'.$phoneKey($request)),
118:         ]);
119:         // أسماء قصيرة ثابتة لمراجع الدفتر (stock_movements.reference_type):
120:         // إعادة تسمية/نقل الكلاسات لاحقًا لا تكسر أثر التدقيق التاريخي.
121:         // الصفوف القديمة المخزنة باسم الكلاس الكامل تظل قابلة للقراءة.
122:         Relation::morphMap([
123:             'stock_transfer' => StockTransfer::class,
124:             'stocktake' => Stocktake::class,
125:             'order' => Order::class,
126:             'return_request' => ReturnRequest::class,
127:             'purchase_order' => PurchaseOrder::class,
128:             'pos_shift' => PosShift::class,
129:             'expense' => Expense::class,
130:             'treasury_transfer' => TreasuryTransfer::class,
131:         ]);
132: 
133:         // حد دخول العملاء (متجر/جملة): بالمُعرّف (بريد/هاتف) وبالـ IP معًا
134:         RateLimiter::for('customer-login', function (Request $request): array {
135:             $identifier = $request->input('login');
136:             $idKey = is_string($identifier) ? hash('sha256', str_contains($identifier, '@')
137:                 ? Str::lower(trim($identifier)) : Customer::normalizePhone($identifier)) : 'none';
138: 
139:             return [
140:                 Limit::perMinute(5)->by('customer-login-id:'.$idKey),
141:                 Limit::perHour(config('auth.customer_limits.login_id_hour', 30))->by('customer-login-id-hour:'.$idKey),
142:                 Limit::perDay(config('auth.customer_limits.login_id_day', 100))->by('customer-login-id-day:'.$idKey),
143:                 Limit::perMinute(config('auth.customer_limits.login_ip_minute', 120))->by('customer-login-ip:'.($request->ip() ?? 'unknown')),
144:             ];
145:         });
146: 
147:         // حدود مسارات السلة وإتمام الشراء وتتبع الطلب والويب هوك (M3/M5)
148:         RateLimiter::for('cart', fn (Request $request) => [
149:             Limit::perMinute(60)->by('cart-ip:'.$request->ip()),
150:         ]);
151:         // تخمين أكواد الكوبونات (F-24): حد ضيق خاص لكل IP وأيضًا لكل
152:         // توكن/جلسة سلة، بدل الاعتماد على حد السلة العام فقط
153:         RateLimiter::for('coupon', function (Request $request): array {
154:             $identity = $request->bearerToken() ?? $request->header('X-Cart-Session') ?? 'guest';
155: 
156:             return [
157:                 Limit::perMinute(10)->by('coupon-ip:'.$request->ip()),
158:                 Limit::perMinute(10)->by('coupon-id:'.hash('sha256', (string) $identity)),
159:             ];
160:         });
161:         // إتمام الشراء: بالـ IP وأيضًا بالهاتف المُوحَّد (F5) — الزائر بلا
162:         // تحقق من الهاتف لا يراكم طلبات وهمية يحبس بها مخزونًا برقم واحد
163:         RateLimiter::for('checkout', function (Request $request): array {
164:             $phone = $request->input('recipient_phone');
165:             $phoneKey = hash('sha256', is_string($phone) && trim($phone) !== ''
166:                 ? Customer::normalizePhone($phone) : 'guest');
167: 
168:             return [
169:                 Limit::perMinute(10)->by('checkout-ip:'.$request->ip()),
170:                 Limit::perMinute(5)->by('checkout-phone:'.$phoneKey),
171:                 Limit::perDay(20)->by('checkout-phone-day:'.$phoneKey),
172:             ];
173:         });
174:         RateLimiter::for('order-tracking', fn (Request $request) => [
175:             Limit::perMinute(10)->by('order-tracking-ip:'.$request->ip()),
176:         ]);
177:         RateLimiter::for('webhooks', fn (Request $request) => [
178:             Limit::perMinute(120)->by('webhooks-ip:'.$request->ip()),
179:         ]);
180: 
181:         RateLimiter::for('supplier-login', function (Request $request): array {
182:             $email = $request->input('email');
183:             $normalizedEmail = is_string($email)
184:                 ? Str::transliterate(Str::lower(trim($email)))
185:                 : '';
186:             $emailKey = hash('sha256', $normalizedEmail);
187: 
188:             return [
189:                 Limit::perMinute(5)->by('supplier-login-email:'.$emailKey),
190:                 Limit::perHour(30)->by('supplier-login-email-hour:'.$emailKey),
191:                 Limit::perMinute(120)->by('supplier-login-ip:'.($request->ip() ?? 'unknown')),
192:             ];
193:         });
194: 
