204:                 Limit::perHour(30)->by('admin-login-email-hour:'.$emailKey),
205:                 Limit::perMinute(120)->by('admin-login-ip:'.($request->ip() ?? 'unknown')),
206:             ];
207:         });
208: 
209:         RateLimiter::for('customer-password-reset', fn (Request $request) => [
210:             Limit::perMinute(config('auth.customer_limits.reset_ip_minute', 20))->by('customer-password-reset:'.$request->ip()),
211:             Limit::perDay(config('auth.customer_limits.reset_ip_day', 500))->by('customer-password-reset-day:'.$request->ip()),
212:             Limit::perMinute(5)->by('customer-password-reset-id:'.$identifierKey($request)),
213:             Limit::perDay(10)->by('customer-password-reset-id-day:'.$identifierKey($request)),
214:         ]);
215: 
216:         // حد تسجيل دخول الكاشير على نقطة البيع
217:         RateLimiter::for('pos-login', function (Request $request): array {
218:             $email = $request->input('email');
219:             $emailKey = hash('sha256', Str::lower(trim(is_string($email) ? $email : '')));
220: 
